/* =========================================================
  실제 화면 로고 적용

  로고가 있으면:
  - 이미지 표시
  - GS 기본 마크 숨김

  로고가 없으면:
  - 이미지 숨김
  - GS 기본 마크 표시
========================================================= */

function applyBrandLogoToScreen(
  imageElement,
  fallbackElement,
  logoUrl
) {
  if (
    !imageElement ||
    !fallbackElement
  ) {
    return;
  }


  const normalizedLogoUrl =
    String(
      logoUrl ||
      ""
    ).trim();


  if (
    normalizedLogoUrl
  ) {
    imageElement.src =
      normalizedLogoUrl;

    imageElement.hidden =
      false;

    fallbackElement.hidden =
      true;

    return;
  }


  imageElement.removeAttribute(
    "src"
  );

  imageElement.hidden =
    true;

  fallbackElement.hidden =
    false;
}

/* =========================================================
  브랜드 설정 실제 화면 적용

  적용 대상:
  - 로그인 화면 배경
  - 로그인 카드
  - 로그인 후 상단 헤더

  로그인 화면 왼쪽:
  - 회사 로고 숨김
  - 회사명 숨김
  - 배경 이미지 안의 로고·슬로건 사용
========================================================= */

function applyBrandManagementToActualScreen() {
  const {
    companyNameInput,
    programNameInput,
    programSubtitleInput,

    positionXInput,
    positionYInput,
    overlayInput
  } =
    getBrandManagementElements();


  const {
    headerBrand,
    headerLogoFallback,
    headerLogoImage,
    headerProgramName,
    headerCompanyName,

    loginBackground,
    loginOverlay,

    introductionLogo,
    introductionLogoFallback,
    introductionLogoImage,
    introductionCompanyName,
    introductionProgramName,
    introductionProgramSubtitle,

    loginCardLogoFallback,
    loginCardLogoImage,
    loginCardCompanyName,
    loginCardProgramName
  } =
    getAppliedBrandElements();


  const savedSettings =
    brandManagementState.savedSettings ||
    DEFAULT_BRAND_SETTINGS;


  /* =====================================================
    현재 설정값
  ====================================================== */

  const companyName =
    String(
      companyNameInput?.value ||
      savedSettings.companyName ||
      DEFAULT_BRAND_SETTINGS.companyName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS.companyName;


  const programName =
    String(
      programNameInput?.value ||
      savedSettings.programName ||
      DEFAULT_BRAND_SETTINGS.programName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS.programName;


  const programSubtitle =
    String(
      programSubtitleInput?.value ||
      savedSettings.programSubtitle ||
      DEFAULT_BRAND_SETTINGS.programSubtitle
    ).trim() ||
    DEFAULT_BRAND_SETTINGS.programSubtitle;


  const positionX =
    clampBrandNumber(
      positionXInput?.value,
      0,
      100,
      savedSettings.backgroundPositionX
    );


  const positionY =
    clampBrandNumber(
      positionYInput?.value,
      0,
      100,
      savedSettings.backgroundPositionY
    );


  const overlayPercent =
    clampBrandNumber(
      overlayInput?.value,
      0,
      80,
      savedSettings.backgroundOverlay
    );


  const overlayOpacity =
    overlayPercent /
    100;


  const logoUrl =
    getCurrentBrandLogoUrl();


  const backgroundUrl =
    getCurrentBrandBackgroundUrl();


  /* =====================================================
    로그인 후 상단 헤더

    상단 헤더에는 회사 로고와 회사명을 그대로 표시한다.
  ====================================================== */

  if (
    headerProgramName
  ) {
    headerProgramName.textContent =
      programName;
  }


  if (
    headerCompanyName
  ) {
    headerCompanyName.textContent =
      companyName;
  }


  if (
    headerBrand
  ) {
    headerBrand.setAttribute(
      "aria-label",
      `${programName} 홈`
    );
  }


  applyBrandLogoToScreen(
    headerLogoImage,
    headerLogoFallback,
    logoUrl
  );


  /* =====================================================
    로그인 화면 왼쪽 중복 브랜드 숨김

    배경 이미지에 이미 회사 로고와 슬로건이 있으므로
    HTML 로고와 회사명은 표시하지 않는다.
  ====================================================== */

  if (
    introductionLogo
  ) {
    introductionLogo.hidden =
      true;


    introductionLogo.style.display =
      "none";
  }


  if (
    introductionLogoFallback
  ) {
    introductionLogoFallback.hidden =
      true;
  }


  if (
    introductionLogoImage
  ) {
    introductionLogoImage.hidden =
      true;


    introductionLogoImage.removeAttribute(
      "src"
    );
  }


  if (
    introductionCompanyName
  ) {
    introductionCompanyName.hidden =
      true;


    introductionCompanyName.style.display =
      "none";
  }


  /* =====================================================
    로그인 화면 왼쪽 프로그램 안내

    GS Shift Log 제목과 설명은 유지한다.
  ====================================================== */

  if (
    introductionProgramName
  ) {
    introductionProgramName.textContent =
      programName;
  }


  if (
    introductionProgramSubtitle
  ) {
    introductionProgramSubtitle.textContent =
      programSubtitle;
  }


  /* =====================================================
    모바일 로그인 카드

    모바일에서는 배경 속 로고가 잘릴 수 있으므로
    로그인 카드 안의 로고와 회사명은 유지한다.
  ====================================================== */

  if (
    loginCardCompanyName
  ) {
    loginCardCompanyName.textContent =
      companyName;
  }


  if (
    loginCardProgramName
  ) {
    loginCardProgramName.textContent =
      programName;
  }


  applyBrandLogoToScreen(
    loginCardLogoImage,
    loginCardLogoFallback,
    logoUrl
  );


  /* =====================================================
    로그인 배경
  ====================================================== */

  if (
    loginBackground
  ) {
    loginBackground.style.backgroundImage =
      backgroundUrl
        ? `url("${backgroundUrl}")`
        : `linear-gradient(
            135deg,
            #17385f,
            #2d6daf
          )`;


    loginBackground.style.backgroundPosition =
      `${positionX}% ${positionY}%`;


    loginBackground.style.backgroundSize =
      "cover";


    loginBackground.style.backgroundRepeat =
      "no-repeat";
  }


  /* =====================================================
    로그인 배경 어둡기
  ====================================================== */

  if (
    loginOverlay
  ) {
    loginOverlay.style.background =
      `linear-gradient(
        90deg,
        rgba(
          8,
          25,
          48,
          ${Math.min(
            0.86,
            overlayOpacity + 0.18
          )}
        ) 0%,
        rgba(
          8,
          25,
          48,
          ${overlayOpacity}
        ) 54%,
        rgba(
          8,
          25,
          48,
          ${Math.max(
            0.05,
            overlayOpacity - 0.12
          )}
        ) 100%
      )`;
  }
}
