/* =========================================================
  이미지 미리보기 HTML 생성
========================================================= */

function renderBrandImagePreview(
  container,
  imageUrl,
  options = {}
) {
  if (
    !container
  ) {
    return;
  }


  const {
    emptyTitle =
      "이미지 미리보기",

    emptyDescription =
      "이미지를 선택해 주세요.",

    alt =
      "브랜드 이미지"
  } = options;


  if (
    !imageUrl
  ) {
    container.innerHTML = `
      <div class="brand-preview__empty">

        <strong>
          ${escapeEmployeeManagementHtml(
            emptyTitle
          )}
        </strong>

        <span>
          ${escapeEmployeeManagementHtml(
            emptyDescription
          )}
        </span>

      </div>
    `;


    return;
  }


  container.innerHTML = `
    <img
      src="${escapeEmployeeManagementHtml(
        imageUrl
      )}"
      alt="${escapeEmployeeManagementHtml(
        alt
      )}"
    />
  `;
}


/* =========================================================
  최종 미리보기 로고 적용

  이미지가 없으면 GS 기본 마크 표시
========================================================= */

function applyBrandLogoPreview(
  container,
  logoUrl
) {
  if (
    !container
  ) {
    return;
  }


  if (
    logoUrl
  ) {
    container.classList.add(
      "has-image"
    );


    container.innerHTML = `
      <img
        src="${escapeEmployeeManagementHtml(
          logoUrl
        )}"
        alt="회사 로고"
      />
    `;


    return;
  }


  container.classList.remove(
    "has-image"
  );


  container.textContent =
    "GS";
}

/* =========================================================
  브랜드 설정 실시간 미리보기 갱신
========================================================= */

function updateBrandManagementPreview() {
  const {
    companyNameInput,
    programNameInput,
    programSubtitleInput,

    logoPreview,
    backgroundPreview,

    positionXInput,
    positionYInput,
    overlayInput,

    positionXValue,
    positionYValue,
    overlayValue,

    loginFinalPreview,
    loginFinalPreviewLogo,
    loginFinalPreviewCompany,
    loginFinalPreviewProgram,
    loginFinalPreviewSubtitle,

    headerFinalPreviewLogo,
    headerFinalPreviewProgram,
    headerFinalPreviewCompany
  } =
    getBrandManagementElements();


  const companyName =
    String(
      companyNameInput?.value ||
      brandManagementState
        .savedSettings
        .companyName ||
      DEFAULT_BRAND_SETTINGS
        .companyName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .companyName;


  const programName =
    String(
      programNameInput?.value ||
      brandManagementState
        .savedSettings
        .programName ||
      DEFAULT_BRAND_SETTINGS
        .programName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .programName;


  const programSubtitle =
    String(
      programSubtitleInput?.value ||
      brandManagementState
        .savedSettings
        .programSubtitle ||
      DEFAULT_BRAND_SETTINGS
        .programSubtitle
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .programSubtitle;


  const positionX =
    clampBrandNumber(
      positionXInput?.value,
      0,
      100,
      DEFAULT_BRAND_SETTINGS
        .backgroundPositionX
    );


  const positionY =
    clampBrandNumber(
      positionYInput?.value,
      0,
      100,
      DEFAULT_BRAND_SETTINGS
        .backgroundPositionY
    );


  const overlayPercent =
    clampBrandNumber(
      overlayInput?.value,
      0,
      80,
      DEFAULT_BRAND_SETTINGS
        .backgroundOverlay
    );


  const overlayOpacity =
    overlayPercent /
    100;


  const logoUrl =
    getCurrentBrandLogoUrl();


  const backgroundUrl =
    getCurrentBrandBackgroundUrl();


  /* =====================================================
    단독 이미지 미리보기
  ====================================================== */

  renderBrandImagePreview(
    logoPreview,
    logoUrl,
    {
      emptyTitle:
        "회사 로고 미리보기",

      emptyDescription:
        "PNG·JPG·WEBP 이미지",

      alt:
        "회사 로고 미리보기"
    }
  );


  renderBrandImagePreview(
    backgroundPreview,
    backgroundUrl,
    {
      emptyTitle:
        "로그인 배경 미리보기",

      emptyDescription:
        "가로형 고화질 이미지를 권장합니다.",

      alt:
        "로그인 배경 미리보기"
    }
  );


  /* =====================================================
    로그인 미리보기 텍스트
  ====================================================== */

  if (
    loginFinalPreviewCompany
  ) {
    loginFinalPreviewCompany.textContent =
      companyName;
  }


  if (
    loginFinalPreviewProgram
  ) {
    loginFinalPreviewProgram.textContent =
      programName;
  }


  if (
    loginFinalPreviewSubtitle
  ) {
    loginFinalPreviewSubtitle.textContent =
      programSubtitle;
  }


  /* =====================================================
    헤더 미리보기 텍스트
  ====================================================== */

  if (
    headerFinalPreviewProgram
  ) {
    headerFinalPreviewProgram.textContent =
      programName;
  }


  if (
    headerFinalPreviewCompany
  ) {
    headerFinalPreviewCompany.textContent =
      companyName;
  }


  /* =====================================================
    로그인·헤더 로고
  ====================================================== */

  applyBrandLogoPreview(
    loginFinalPreviewLogo,
    logoUrl
  );


  applyBrandLogoPreview(
    headerFinalPreviewLogo,
    logoUrl
  );


  /* =====================================================
    로그인 배경 미리보기
  ====================================================== */

  if (
    loginFinalPreview
  ) {
    loginFinalPreview.style
      .backgroundImage =
      backgroundUrl
        ? `linear-gradient(
            rgba(
              10,
              28,
              54,
              ${overlayOpacity}
            ),
            rgba(
              10,
              28,
              54,
              ${overlayOpacity}
            )
          ),
          url("${backgroundUrl}")`
        : `linear-gradient(
            135deg,
            #17385f,
            #2b69ad
          )`;


    loginFinalPreview.style
      .backgroundPosition =
      `${positionX}% ${positionY}%`;


    loginFinalPreview.style
      .backgroundSize =
      "cover";
  }


  /* =====================================================
    슬라이더 표시값
  ====================================================== */

  if (
    positionXValue
  ) {
    positionXValue.textContent =
      `${positionX}%`;
  }


  if (
    positionYValue
  ) {
    positionYValue.textContent =
      `${positionY}%`;
  }


  if (
    overlayValue
  ) {
    overlayValue.textContent =
      `${overlayPercent}%`;
  }


  /*
    실제 로그인 화면과 상단 헤더에도
    현재 설정을 즉시 반영한다.
  */
  applyBrandManagementToActualScreen();
}

/* =========================================================
  브랜드 설정 서버 저장

  POST /api/brand-settings

  저장:
  - 회사명·프로그램명·표시 설정 → D1
  - 회사 로고·로그인 배경 → R2
========================================================= */

async function handleBrandManagementSavePreview() {
  if (
    brandManagementState.isSaving
  ) {
    return;
  }


  const {
    companyNameInput,
    programNameInput,
    programSubtitleInput,

    positionXInput,
    positionYInput,
    overlayInput,

    logoFileInput,
    backgroundFileInput,

    saveBrandButton
  } =
    getBrandManagementElements();


  const companyName =
    String(
      companyNameInput?.value ||
      ""
    ).trim();


  const programName =
    String(
      programNameInput?.value ||
      ""
    ).trim();


  const programSubtitle =
    String(
      programSubtitleInput?.value ||
      ""
    ).trim();


  if (
    !companyName
  ) {
    showBrandManagementMessage(
      "회사명을 입력해 주세요.",
      "error"
    );


    companyNameInput?.focus();


    return;
  }


  if (
    !programName
  ) {
    showBrandManagementMessage(
      "프로그램명을 입력해 주세요.",
      "error"
    );


    programNameInput?.focus();


    return;
  }


  if (
    !programSubtitle
  ) {
    showBrandManagementMessage(
      "프로그램 설명을 입력해 주세요.",
      "error"
    );


    programSubtitleInput?.focus();


    return;
  }


  const sessionToken =
    getShiftLogSessionToken();


  if (
    !sessionToken
  ) {
    showBrandManagementMessage(
      "로그인 세션을 확인할 수 없습니다. 다시 로그인해 주세요.",
      "error"
    );


    return;
  }


  const formData =
    new FormData();


  formData.append(
    "companyName",
    companyName
  );


  formData.append(
    "programName",
    programName
  );


  formData.append(
    "programSubtitle",
    programSubtitle
  );


  formData.append(
    "backgroundPositionX",
    String(
      clampBrandNumber(
        positionXInput?.value,
        0,
        100,
        DEFAULT_BRAND_SETTINGS.backgroundPositionX
      )
    )
  );


  formData.append(
    "backgroundPositionY",
    String(
      clampBrandNumber(
        positionYInput?.value,
        0,
        100,
        DEFAULT_BRAND_SETTINGS.backgroundPositionY
      )
    )
  );


  formData.append(
    "backgroundOverlay",
    String(
      clampBrandNumber(
        overlayInput?.value,
        0,
        80,
        DEFAULT_BRAND_SETTINGS.backgroundOverlay
      )
    )
  );


  /*
    새로 선택한 파일이 있는 경우에만 업로드한다.
  */
  if (
    brandManagementState.logoFile instanceof
      File
  ) {
    formData.append(
      "logo",
      brandManagementState.logoFile,
      brandManagementState.logoFile.name
    );
  }


  if (
    brandManagementState.backgroundFile instanceof
      File
  ) {
    formData.append(
      "background",
      brandManagementState.backgroundFile,
      brandManagementState.backgroundFile.name
    );
  }


  /*
    삭제 버튼을 누른 상태는 별도 boolean으로 전달한다.
  */
  formData.append(
    "removeLogo",
    String(
      brandManagementState.logoRemoved
    )
  );


  formData.append(
    "removeBackground",
    String(
      brandManagementState.backgroundRemoved
    )
  );


  brandManagementState.isSaving =
    true;


  if (
    saveBrandButton
  ) {
    saveBrandButton.disabled =
      true;


    saveBrandButton.textContent =
      "저장 중...";
  }


  showBrandManagementMessage(
    "브랜드 설정과 이미지를 저장하고 있습니다.",
    "info"
  );


  try {
    const response =
      await fetch(
        BRAND_SETTINGS_API_URL,
        {
          method:
            "POST",

          headers: {
            Accept:
              "application/json",

            Authorization:
              `Bearer ${sessionToken}`
          },

          body:
            formData,

          cache:
            "no-store"
        }
      );


    const responseText =
      await response.text();


    let result = {};


    if (
      responseText.trim()
    ) {
      try {
        result =
          JSON.parse(
            responseText
          );

      } catch {
        throw new Error(
          "브랜드 설정 저장 서버 응답 형식이 올바르지 않습니다."
        );
      }
    }


    if (
      !response.ok ||
      result.ok === false
    ) {
      throw new Error(
        result.message ||
        result.error ||
        `브랜드 설정 저장 실패 (HTTP ${response.status})`
      );
    }


    const savedSettings =
      normalizeBrandSettings(
        result.brand ||
        result.data ||
        result
      );


    /*
      저장 전에 사용하던 Blob URL을 정리한다.
    */
    revokeBrandPreviewUrl(
      brandManagementState.logoPreviewUrl
    );


    revokeBrandPreviewUrl(
      brandManagementState.backgroundPreviewUrl
    );


    brandManagementState.savedSettings = {
      ...savedSettings
    };


    brandManagementState.logoFile =
      null;


    brandManagementState.logoPreviewUrl =
      "";


    brandManagementState.logoRemoved =
      false;


    brandManagementState.backgroundFile =
      null;


    brandManagementState.backgroundPreviewUrl =
      "";


    brandManagementState.backgroundRemoved =
      false;


    if (
      logoFileInput
    ) {
      logoFileInput.value =
        "";
    }


    if (
      backgroundFileInput
    ) {
      backgroundFileInput.value =
        "";
    }


    populateBrandManagementForm(
      savedSettings
    );


    updateBrandManagementPreview();


    showBrandManagementMessage(
      "브랜드 설정을 저장했습니다. 모든 사용자에게 동일하게 적용됩니다.",
      "success"
    );


    showToast(
      "브랜드 설정이 저장되었습니다."
    );


    console.log(
      "브랜드 설정 서버 저장 완료:",
      savedSettings
    );

  } catch (
    error
  ) {
    console.error(
      "브랜드 설정 서버 저장 오류:",
      error
    );


    showBrandManagementMessage(
      error.message ||
      "브랜드 설정을 저장하지 못했습니다.",
      "error"
    );


    showToast(
      error.message ||
      "브랜드 설정 저장에 실패했습니다."
    );

  } finally {
    brandManagementState.isSaving =
      false;


    if (
      saveBrandButton
    ) {
      saveBrandButton.disabled =
        false;


      saveBrandButton.textContent =
        "브랜드 설정 저장";
    }
  }
}

/* =========================================================
  브랜드 관리 이벤트 연결
========================================================= */

function bindBrandManagementEvents() {
  const {
    employeeTabButton,
    brandTabButton,

    companyNameInput,
    programNameInput,
    programSubtitleInput,

    logoFileInput,
    backgroundFileInput,

    removeLogoButton,
    removeBackgroundButton,

    positionXInput,
    positionYInput,
    overlayInput,

    saveBrandButton
  } =
    getBrandManagementElements();


  employeeTabButton
    ?.addEventListener(
      "click",
      () => {
        switchSystemAdminView(
          "employees"
        );
      }
    );


  brandTabButton
    ?.addEventListener(
      "click",
      () => {
        switchSystemAdminView(
          "brand"
        );
      }
    );


  [
    companyNameInput,
    programNameInput,
    programSubtitleInput,
    positionXInput,
    positionYInput,
    overlayInput
  ]
    .filter(Boolean)
    .forEach(
      input => {
        input.addEventListener(
          "input",
          updateBrandManagementPreview
        );
      }
    );


  logoFileInput
    ?.addEventListener(
      "change",
      handleBrandLogoFileChange
    );


  backgroundFileInput
    ?.addEventListener(
      "change",
      handleBrandBackgroundFileChange
    );


  removeLogoButton
    ?.addEventListener(
      "click",
      removeBrandLogoPreview
    );


  removeBackgroundButton
    ?.addEventListener(
      "click",
      removeBrandBackgroundPreview
    );


  saveBrandButton
    ?.addEventListener(
      "click",
      handleBrandManagementSavePreview
    );


  updateBrandManagementPreview();
}

/* =========================================================
  직원 직접 추가 기능 최종본

  기능:
  - 직원 추가 버튼 클릭
  - 직원 추가 패널 열기·닫기
  - 사번·이름·권한 입력
  - D1 employees 저장
  - users 로그인 계정 자동 생성
  - 초기 비밀번호는 사번과 동일
========================================================= */


/* =========================================================
  직원 추가 요소 가져오기
========================================================= */

function getShiftLogEmployeeAddElements() {
  return {
    panel:
      document.getElementById(
        "employeeAddPanel"
      ),

    openButton:
      document.getElementById(
        "openEmployeeAddButton"
      ),

    closeButton:
      document.getElementById(
        "closeEmployeeAddButton"
      ),

    employeeNoInput:
      document.getElementById(
        "employeeAddEmployeeNo"
      ),

    nameInput:
      document.getElementById(
        "employeeAddName"
      ),

    roleSelect:
      document.getElementById(
        "employeeAddRole"
      ),

    saveButton:
      document.getElementById(
        "saveEmployeeAddButton"
      ),

    message:
      document.getElementById(
        "employeeAddMessage"
      )
  };
}


/* =========================================================
  직원 추가 메시지 표시
========================================================= */

function showShiftLogEmployeeAddMessage(
  message,
  type = "info"
) {
  const {
    message: messageElement
  } =
    getShiftLogEmployeeAddElements();


  if (
    !messageElement
  ) {
    return;
  }


  messageElement.textContent =
    String(
      message ||
      ""
    );


  messageElement.hidden =
    !message;


  messageElement.classList.remove(
    "is-error",
    "is-success"
  );


  if (
    type ===
    "error"
  ) {
    messageElement.classList.add(
      "is-error"
    );
  }


  if (
    type ===
    "success"
  ) {
    messageElement.classList.add(
      "is-success"
    );
  }
}


/* =========================================================
  직원 추가 입력값 초기화
========================================================= */

function resetShiftLogEmployeeAddForm() {
  const {
    employeeNoInput,
    nameInput,
    roleSelect
  } =
    getShiftLogEmployeeAddElements();


  if (
    employeeNoInput
  ) {
    employeeNoInput.value =
      "";
  }


  if (
    nameInput
  ) {
    nameInput.value =
      "";
  }


  if (
    roleSelect
  ) {
    roleSelect.value =
      "user";
  }


  showShiftLogEmployeeAddMessage(
    ""
  );
}


