/* =========================================================
  GS Shift Log
  - 현황 / 조회 탭
  - 날짜 이동
  - 업무일지 작성 모달
  - 작업 항목 추가 / 삭제
  - 첨부파일 표시
  - 임시저장 / 저장 / 결재요청
  - 상세보기
  - TAG → Facility Navigator 이동
========================================================= */

const FACILITY_NAVIGATOR_URL =
  "https://gs-facility-navigator-2mg.pages.dev/";

const STORAGE_KEYS = {
  logs:
    "gsShiftLog.logs",

  draft:
    "gsShiftLog.draft",

  operationStatus:
    "gsShiftLog.operationStatus",

  memberWorkStatuses:
    "gsShiftLog.memberWorkStatuses"
};


/* =========================================================
  현재 근무일자·근무구분 계산

  D/S : 07:00 ~ 19:00
  N/S : 19:00 ~ 다음 날 07:00

  00:00 ~ 06:59는 전날 N/S로 처리한다.
========================================================= */

function getCurrentShiftContext(now = new Date()) {
  const currentDate =
    new Date(now);

  const hour =
    currentDate.getHours();

  if (hour >= 7 && hour < 19) {
    return {
      date:
        new Date(
          currentDate.getFullYear(),
          currentDate.getMonth(),
          currentDate.getDate()
        ),

      shift:
        "DS"
    };
  }

  if (hour < 7) {
    currentDate.setDate(
      currentDate.getDate() - 1
    );
  }

  return {
    date:
      new Date(
        currentDate.getFullYear(),
        currentDate.getMonth(),
        currentDate.getDate()
      ),

    shift:
      "NS"
  };
}


function getShiftDisplayName(shift) {
  return (
    String(shift || "")
      .trim()
      .toUpperCase() === "DS"
      ? "D/S"
      : "N/S"
  );
}


async function toggleSelectedShift() {
  appState.selectedShift =
    appState.selectedShift === "DS"
      ? "NS"
      : "DS";

  renderSelectedDate();

  await loadLegacyLogsForSelectedDate();

  renderLogTable();
  updateShiftMemberCardStates();
}

const initialShiftContext =
  getCurrentShiftContext();

const appState = {
  selectedDate:
    initialShiftContext.date,

  selectedShift:
    initialShiftContext.shift,

  currentDetailLogId:
    null,

  logs: [],

  editorEntries: [],

  editingEntryIndex:
    -1,

  /*
    날짜·근무·보직별 근무 상태

    예:
    2026-07-21||DS||TGO : 출근
    2026-07-21||DS||BCO1 : 휴가
  */
  memberWorkStatuses: {}
};

/* =========================================================
  근무자 출근·부재 상태 관리

  상태 종류:
  - 출근
  - 교육
  - 휴가
  - 출장
  - 결원
========================================================= */

function getMemberWorkStatusKey(
  date,
  shift,
  role
) {
  const normalizedDate =
    String(
      date || ""
    ).trim();

  const normalizedShift =
    String(
      shift || ""
    )
      .trim()
      .toUpperCase();

  const normalizedRole =
    normalizeMemberLogRole(
      role
    );

  return [
    normalizedDate,
    normalizedShift,
    normalizedRole
  ].join("||");
}


function loadMemberWorkStatuses() {
  const savedStatuses =
    localStorage.getItem(
      STORAGE_KEYS.memberWorkStatuses
    );

  if (!savedStatuses) {
    appState.memberWorkStatuses = {};
    return;
  }

  try {
    const parsedStatuses =
      JSON.parse(
        savedStatuses
      );

    appState.memberWorkStatuses =
      parsedStatuses &&
      typeof parsedStatuses ===
        "object" &&
      !Array.isArray(
        parsedStatuses
      )
        ? parsedStatuses
        : {};
  } catch (error) {
    console.error(
      "근무자 상태 불러오기 실패:",
      error
    );

    appState.memberWorkStatuses = {};

    localStorage.removeItem(
      STORAGE_KEYS.memberWorkStatuses
    );
  }
}


function persistMemberWorkStatuses() {
  localStorage.setItem(
    STORAGE_KEYS.memberWorkStatuses,
    JSON.stringify(
      appState.memberWorkStatuses
    )
  );
}


function getMemberWorkStatus(
  date,
  shift,
  role
) {
  const statusKey =
    getMemberWorkStatusKey(
      date,
      shift,
      role
    );

  const savedStatus =
    String(
      appState
        .memberWorkStatuses[
          statusKey
        ] ||
      ""
    ).trim();

  const validStatuses = [
    "출근",
    "교육",
    "휴가",
    "출장",
    "결원"
  ];

  return validStatuses.includes(
    savedStatus
  )
    ? savedStatus
    : "출근";
}


function setMemberWorkStatus(
  date,
  shift,
  role,
  status
) {
  const validStatuses = [
    "출근",
    "교육",
    "휴가",
    "출장",
    "결원"
  ];

  const normalizedStatus =
    String(
      status || ""
    ).trim();

  if (
    !validStatuses.includes(
      normalizedStatus
    )
  ) {
    return false;
  }

  const statusKey =
    getMemberWorkStatusKey(
      date,
      shift,
      role
    );

  /*
    기본값인 출근은 저장소에서 제거하여
    불필요한 데이터가 쌓이지 않게 한다.
  */
  if (
    normalizedStatus ===
    "출근"
  ) {
    delete appState
      .memberWorkStatuses[
        statusKey
      ];
  } else {
    appState
      .memberWorkStatuses[
        statusKey
      ] =
      normalizedStatus;
  }

  persistMemberWorkStatuses();

  return true;
}

/* =========================================================
  조회 기본 기간 설정

  종료일:
  오늘

  시작일:
  오늘 기준 7일 전

  예:
  오늘이 2026-07-23이면
  시작일 2026-07-16
  종료일 2026-07-23
========================================================= */

function setDefaultSearchDateRange() {
  const searchStartDate =
    document.getElementById(
      "searchStartDate"
    );

  const searchEndDate =
    document.getElementById(
      "searchEndDate"
    );


  if (
    !searchStartDate ||
    !searchEndDate
  ) {
    return;
  }


  const today =
    new Date();


  const sevenDaysAgo =
    new Date(today);


  sevenDaysAgo.setDate(
    sevenDaysAgo.getDate() - 7
  );


  searchStartDate.value =
    formatInputDate(
      sevenDaysAgo
    );


  searchEndDate.value =
    formatInputDate(
      today
    );
}

