/* =========================================================
  파트장 업무 직접 추가 위치 표시

  파트장 업무일지:
  - 파트장
  - TGO
  - BCO1
  - BCO2
  선택 가능

  일반 보직:
  - 추가 위치 선택창 숨김
========================================================= */

function updateLogEntryTargetRoleVisibility() {
  const targetRoleField =
    elements.logEntryTargetRoleField ||
    document.getElementById(
      "logEntryTargetRoleField"
    );


  const targetRoleSelect =
    elements.logEntryTargetRole ||
    document.getElementById(
      "logEntryTargetRole"
    );


  const currentLogRole =
    normalizeMemberLogRole(
      elements.logRole?.value ||
      document.getElementById(
        "logRole"
      )?.value ||
      ""
    );


  const isLeaderLog =
    currentLogRole ===
      "파트장";


  if (
    !targetRoleField
  ) {
    return;
  }


  /*
    파트장 업무일지에서만 표시
  */
  targetRoleField.hidden =
    !isLeaderLog;


  targetRoleField.classList.toggle(
    "is-visible",
    isLeaderLog
  );


  if (
    !targetRoleSelect
  ) {
    return;
  }


  targetRoleSelect.disabled =
    !isLeaderLog;


  /*
    일반 업무일지를 열었다가
    다시 파트장 업무일지를 열었을 때
    이전 선택값이 남지 않도록 한다.
  */
  if (
    !isLeaderLog
  ) {
    targetRoleSelect.value =
      "파트장";


    return;
  }


  /*
    잘못된 값이 들어가 있으면
    파트장을 기본값으로 사용한다.
  */
  const allowedTargetRoles = [
    "파트장",
    "TGO",
    "BCO1",
    "BCO2"
  ];


  const currentTargetRole =
    normalizeMemberLogRole(
      targetRoleSelect.value
    );


  if (
    !allowedTargetRoles.includes(
      currentTargetRole
    )
  ) {
    targetRoleSelect.value =
      "파트장";
  }
}


/* =========================================================
  파트장 추가 위치 표시 자동 연결

  이유:
  logRole은 수정창을 열 때
  JavaScript에서 직접 값이 변경될 수 있다.

  따라서:
  - 보직 직접 변경
  - 수정창 열림
  두 경우 모두 다시 확인한다.
========================================================= */

function initializeLogEntryTargetRoleVisibility() {
  const logRole =
    elements.logRole ||
    document.getElementById(
      "logRole"
    );


  const logEditorModal =
    elements.logEditorModal ||
    document.getElementById(
      "logEditorModal"
    );


  /*
    HTML 요소를 elements에도 다시 연결한다.
  */
  elements.logEntryTargetRoleField =
    document.getElementById(
      "logEntryTargetRoleField"
    );


  elements.logEntryTargetRole =
    document.getElementById(
      "logEntryTargetRole"
    );


  /*
    보직을 직접 변경하는 경우
  */
  if (
    logRole &&
    logRole.dataset
      .targetRoleVisibilityBound !==
      "true"
  ) {
    logRole.addEventListener(
      "change",
      updateLogEntryTargetRoleVisibility
    );


    logRole.dataset
      .targetRoleVisibilityBound =
      "true";
  }


  /*
    수정창이 열릴 때마다 현재 보직을 다시 확인한다.

    프로그램에서 logRole.value를
    직접 바꿔도 정상 작동한다.
  */
  if (
    logEditorModal &&
    logEditorModal.dataset
      .targetRoleVisibilityObserverBound !==
      "true"
  ) {
    const observer =
      new MutationObserver(
        () => {
          const isOpen =
            logEditorModal.classList.contains(
              "is-open"
            ) ||
            logEditorModal.getAttribute(
              "aria-hidden"
            ) ===
              "false";


          if (
            !isOpen
          ) {
            return;
          }


          window.requestAnimationFrame(
            updateLogEntryTargetRoleVisibility
          );
        }
      );


    observer.observe(
      logEditorModal,
      {
        attributes:
          true,

        attributeFilter: [
          "class",
          "aria-hidden"
        ]
      }
    );


    logEditorModal.dataset
      .targetRoleVisibilityObserverBound =
      "true";
  }


  updateLogEntryTargetRoleVisibility();
}

/* =========================================================
  D1에 보관된 과거 업무일지 1일 불러오기

  - 조회 날짜의 D/S·N/S 모두 불러오기
  - 원본 업무일지와 첨부파일 함께 연결
  - 과거 서버는 직접 호출하지 않음
========================================================= */

async function loadLegacyLogsForSearchDate(
  searchDate
) {
  const normalizedDate =
    String(
      searchDate || ""
    ).trim();


  if (!normalizedDate) {
    return [];
  }


  const requestUrl =
    new URL(
      "/api/legacy-logs",
      window.location.origin
    );


  /*
    shift를 지정하지 않으면
    해당 날짜의 D/S와 N/S를 모두 반환한다.
  */
  requestUrl.searchParams.set(
    "date",
    normalizedDate
  );


  const response =
    await fetch(
      requestUrl.toString(),
      {
        method:
          "GET",

        headers: {
          Accept:
            "application/json"
        },

        cache:
          "no-store"
      }
    );


  let result = {};


  try {
    result =
      await response.json();

  } catch (error) {
    throw new Error(
      `${normalizedDate} D1 과거 업무일지 응답을 읽을 수 없습니다.`
    );
  }


  if (
    !response.ok ||
    !result.success
  ) {
    throw new Error(
      result.message ||
      `${normalizedDate} 저장된 과거 업무일지를 불러오지 못했습니다.`
    );
  }


  const storedItems =
    Array.isArray(
      result.items
    )
      ? result.items
      : [];


  /*
    D1의 original은 기존 업무일지 원본이고,
    attachments는 별도로 저장된 첨부파일 목록이다.

    두 데이터를 변환된 업무일지에 함께 연결한다.
  */
  const convertedLogs =
    storedItems
      .map(
        (
          storedItem,
          itemIndex
        ) => {
          const originalItem =
            storedItem?.original &&
            typeof storedItem.original ===
              "object"
              ? storedItem.original
              : null;


          if (!originalItem) {
            console.warn(
              "과거 업무일지 원본이 없어 제외했습니다.",
              storedItem
            );

            return null;
          }


          const storedShift =
            String(
              storedItem.shift ||
              ""
            )
              .trim()
              .toUpperCase();


          const convertedLog =
            convertLegacyDiaryToLog(
              originalItem,
              itemIndex,
              normalizedDate,
              storedShift
            );


          if (!convertedLog) {
            return null;
          }


          /*
            조회용 업무일지에도 D1 첨부파일을 연결한다.
          */
          convertedLog.attachments =
            Array.isArray(
              storedItem.attachments
            )
              ? storedItem.attachments
                  .map(
                    attachment => {
                      const attachmentId =
                        Number(
                          attachment?.id ||
                          0
                        );


                      const fileName =
                        String(
                          attachment?.fileName ||
                          attachment?.name ||
                          ""
                        ).trim();


                      const attachmentUrl =
                        String(
                          attachment?.url ||
                          (
                            attachmentId
                              ? `/api/legacy-attachment?id=${encodeURIComponent(
                                  attachmentId
                                )}`
                              : ""
                          )
                        ).trim();


                      return {
                        id:
                          attachmentId,

                        name:
                          fileName,

                        fileName,

                        mimeType:
                          String(
                            attachment?.mimeType ||
                            ""
                          ).trim(),

                        fileSize:
                          Number(
                            attachment?.fileSize ||
                            0
                          ),

                        r2Key:
                          String(
                            attachment?.r2Key ||
                            ""
                          ).trim(),

                        originalUrl:
                          String(
                            attachment?.originalUrl ||
                            ""
                          ).trim(),

                        uploadedAt:
                          String(
                            attachment?.uploadedAt ||
                            ""
                          ).trim(),

                        url:
                          attachmentUrl
                      };
                    }
                  )
                  .filter(
                    attachment => {
                      return Boolean(
                        attachment.url
                      );
                    }
                  )
              : [];


          convertedLog.legacyAttachmentCount =
            convertedLog
              .attachments
              .length;


          return convertedLog;
        }
      )
      .filter(Boolean);


  /*
    2026-07-21까지의 과거 자료는
    기존 파트장 취합 구조를 동일하게 적용한다.

    D/S와 N/S가 섞이지 않도록
    근무별로 따로 재구성한다.
  */
  if (
    normalizedDate <=
    "2026-07-21"
  ) {
    const dsLogs =
      convertedLogs.filter(
        log => {
          return (
            log.shift ===
            "DS"
          );
        }
      );


    const nsLogs =
      convertedLogs.filter(
        log => {
          return (
            log.shift ===
            "NS"
          );
        }
      );


    rebuildLegacyLeaderLogFromMemberLogs(
      dsLogs
    );


    rebuildLegacyLeaderLogFromMemberLogs(
      nsLogs
    );
  }


  return convertedLogs;
}

/* =========================================================
  업무일지 조회 최대 종료일 계산

  기준:
  시작일로부터 달력 기준 6개월

  예:
  2026-02-02 → 2026-08-02
  2026-08-31 → 2027-02-28
========================================================= */

function getSearchMaximumEndDate(
  startDateValue
) {
  const normalizedStartDate =
    String(
      startDateValue ||
      ""
    ).trim();


  if (
    !normalizedStartDate
  ) {
    return "";
  }


  const startDate =
    new Date(
      `${normalizedStartDate}T00:00:00`
    );


  if (
    Number.isNaN(
      startDate.getTime()
    )
  ) {
    return "";
  }


  /*
    31일인 날짜가 짧은 달로 이동할 때
    다음 달로 넘어가지 않게 원래 일자를 보관한다.
  */
  const originalDay =
    startDate.getDate();


  const maximumEndDate =
    new Date(
      startDate
    );


  /*
    먼저 1일로 이동한 뒤
    6개월을 더한다.
  */
  maximumEndDate.setDate(
    1
  );


  maximumEndDate.setMonth(
    maximumEndDate.getMonth() +
    6
  );


  /*
    대상 월의 마지막 날짜
  */
  const lastDayOfTargetMonth =
    new Date(
      maximumEndDate.getFullYear(),
      maximumEndDate.getMonth() + 1,
      0
    ).getDate();


  maximumEndDate.setDate(
    Math.min(
      originalDay,
      lastDayOfTargetMonth
    )
  );


  return formatInputDate(
    maximumEndDate
  );
}

/* =========================================================
  시작일 ~ 종료일 날짜 배열 생성

  예:
  2026-07-20 ~ 2026-07-22

  결과:
  [
    "2026-07-20",
    "2026-07-21",
    "2026-07-22"
  ]
========================================================= */

function createSearchDateRange(
  startDate,
  endDate
) {
  const normalizedStartDate =
    String(
      startDate || ""
    ).trim();


  const normalizedEndDate =
    String(
      endDate || ""
    ).trim();


  if (
    !normalizedStartDate ||
    !normalizedEndDate
  ) {
    return [];
  }


  const start =
    new Date(
      `${normalizedStartDate}T00:00:00`
    );


  const end =
    new Date(
      `${normalizedEndDate}T00:00:00`
    );


  if (
    Number.isNaN(
      start.getTime()
    ) ||
    Number.isNaN(
      end.getTime()
    ) ||
    start > end
  ) {
    return [];
  }


  const dateList = [];

  const currentDate =
    new Date(start);


  while (
    currentDate <= end
  ) {
    dateList.push(
      formatInputDate(
        currentDate
      )
    );


    currentDate.setDate(
      currentDate.getDate() + 1
    );
  }


  return dateList;
}

/* =========================================================
  조회 기간 전체의 과거 업무일지 불러오기

  처리 방식:
  - 시작일~종료일 날짜 목록 생성
  - 날짜 6개씩 묶어서 병렬 조회
  - 한 번에 지나치게 많은 요청을 보내지 않음
  - 특정 날짜 실패 시 나머지 날짜는 계속 조회
========================================================= */

async function loadLegacyLogsForSearchRange(
  startDate,
  endDate
) {
  const searchDates =
    createSearchDateRange(
      startDate,
      endDate
    );


  if (
    !searchDates.length
  ) {
    return [];
  }


  const allLegacyLogs = [];


  /*
    동시에 조회할 날짜 수

    날짜 1개당 D/S와 N/S를 조회하므로
    실제 동시 요청은 최대 약 12개다.
  */
  const batchSize =
    6;


  for (
    let startIndex = 0;
    startIndex <
      searchDates.length;
    startIndex +=
      batchSize
  ) {
    const dateBatch =
      searchDates.slice(
        startIndex,
        startIndex +
        batchSize
      );


    const batchResults =
      await Promise.allSettled(
        dateBatch.map(
          searchDate => {
            return (
              loadLegacyLogsForSearchDate(
                searchDate
              )
            );
          }
        )
      );


    batchResults.forEach(
      (
        result,
        resultIndex
      ) => {
        const searchDate =
          dateBatch[
            resultIndex
          ];


        if (
          result.status ===
          "fulfilled"
        ) {
          const dateLogs =
            Array.isArray(
              result.value
            )
              ? result.value
              : [];


          allLegacyLogs.push(
            ...dateLogs
          );


          return;
        }


        console.error(
          `${searchDate} 조회용 과거 업무일지 불러오기 실패:`,
          result.reason
        );
      }
    );
  }


  return allLegacyLogs;
}

/* =========================================================
  조회 날짜 입력창 제한 동기화

  시작일 선택 시:
  - 종료일 최소값 = 시작일
  - 종료일 최대값 = 시작일 기준 6개월

  폼 초기화 시:
  - 초기값을 기준으로 다시 계산
========================================================= */

function syncSearchDateInputLimits() {
  const searchStartDate =
    document.getElementById(
      "searchStartDate"
    );


  const searchEndDate =
    document.getElementById(
      "searchEndDate"
    );


  if (
    !searchStartDate ||
    !searchEndDate
  ) {
    return;
  }


  const startDate =
    String(
      searchStartDate.value ||
      ""
    ).trim();


  if (
    !startDate
  ) {
    searchEndDate.removeAttribute(
      "min"
    );


    searchEndDate.removeAttribute(
      "max"
    );


    return;
  }


  const maximumEndDate =
    getSearchMaximumEndDate(
      startDate
    );


  searchEndDate.min =
    startDate;


  if (
    maximumEndDate
  ) {
    searchEndDate.max =
      maximumEndDate;

  } else {
    searchEndDate.removeAttribute(
      "max"
    );
  }
}


/* =========================================================
  조회 날짜 제한 이벤트 연결
========================================================= */

function initializeSearchDateInputLimits() {
  const searchForm =
    document.getElementById(
      "searchForm"
    );


  const searchStartDate =
    document.getElementById(
      "searchStartDate"
    );


  if (
    !searchStartDate
  ) {
    return;
  }


  searchStartDate.addEventListener(
    "change",
    syncSearchDateInputLimits
  );


  searchStartDate.addEventListener(
    "input",
    syncSearchDateInputLimits
  );


  searchForm?.addEventListener(
    "reset",
    () => {
      window.setTimeout(
        syncSearchDateInputLimits,
        0
      );
    }
  );


  /*
    기존 기본 날짜 설정 함수가 실행된 뒤
    제한값을 다시 계산한다.
  */
  window.setTimeout(
    syncSearchDateInputLimits,
    0
  );
}


document.addEventListener(
  "DOMContentLoaded",
  initializeSearchDateInputLimits
);

/* =========================================================
  TO · BO1 · BO2 전 근무자 운전현황 가져오기
  1단계

  현재 근무 기준 직전 근무:
  DS → 전날 NS
  NS → 같은 날 DS
========================================================= */


/* =========================================================
  전 근무 날짜·근무 계산
========================================================= */

function getPreviousShiftContext(
  dateValue,
  shiftValue
) {
  const normalizedDate =
    String(
      dateValue ||
      ""
    ).trim();


  const normalizedShift =
    String(
      shiftValue ||
      ""
    )
      .trim()
      .toUpperCase();


  const currentDate =
    new Date(
      `${normalizedDate}T00:00:00`
    );


  if (
    Number.isNaN(
      currentDate.getTime()
    )
  ) {
    return null;
  }


  /*
    현재 N/S 작성 중이면
    바로 전 근무는 같은 날짜 D/S
  */
  if (
    normalizedShift ===
    "NS"
  ) {
    return {
      date:
        formatInputDate(
          currentDate
        ),

      shift:
        "DS"
    };
  }


  /*
    현재 D/S 작성 중이면
    바로 전 근무는 전날 N/S
  */
  if (
    normalizedShift ===
    "DS"
  ) {
    currentDate.setDate(
      currentDate.getDate() - 1
    );


    return {
      date:
        formatInputDate(
          currentDate
        ),

      shift:
        "NS"
    };
  }


  return null;
}


/* =========================================================
  지정 날짜의 D1 업무일지 조회
========================================================= */

async function loadLegacyLogsForOperationStatusDate(
  dateValue
) {
  const normalizedDate =
    String(
      dateValue ||
      ""
    ).trim();


  if (!normalizedDate) {
    return [];
  }


  const requestUrl =
    new URL(
      "/api/legacy-logs",
      window.location.origin
    );


  requestUrl.searchParams.set(
    "date",
    normalizedDate
  );


  requestUrl.searchParams.set(
    "_",
    String(
      Date.now()
    )
  );


  const response =
    await fetch(
      requestUrl.toString(),
      {
        method:
          "GET",

        headers: {
          Accept:
            "application/json"
        },

        cache:
          "no-store"
      }
    );


  let result = {};


  try {
    result =
      await response.json();

  } catch {
    throw new Error(
      "전 근무자 업무일지 응답을 읽을 수 없습니다."
    );
  }


  if (
    !response.ok ||
    !result.success
  ) {
    throw new Error(
      result.message ||
      "전 근무자 업무일지를 불러오지 못했습니다."
    );
  }


  const storedItems =
    Array.isArray(
      result.items
    )
      ? result.items
      : [];


  return storedItems
    .map(
      (
        storedItem,
        itemIndex
      ) => {
        const originalItem =
          storedItem?.original &&
          typeof storedItem.original ===
            "object"
            ? storedItem.original
            : null;


        if (!originalItem) {
          return null;
        }


        const storedShift =
          String(
            storedItem.shift ||
            ""
          )
            .trim()
            .toUpperCase();


        return convertLegacyDiaryToLog(
          originalItem,
          itemIndex,
          normalizedDate,
          storedShift
        );
      }
    )
    .filter(
      Boolean
    );
}

/* =========================================================
  모든 보직의 전 근무 인계사항 조회

  현재 근무 기준:
  - N/S → 같은 날 D/S
  - D/S → 전날 N/S

  가져오는 항목:
  - 인계사항
  - TM 작업
  - BM 발행
  - BM 작업
  - CM 발행

  제외:
  - TM 발행
  - 비고

  항목별 시간·구분·TAG·줄바꿈·출처 정보를
  원본 그대로 유지한다.
========================================================= */

async function getPreviousShiftHandoverEntries(
  roleValue,
  dateValue,
  shiftValue
) {
  const normalizedRole =
    normalizeMemberLogRole(
      roleValue
    );


  const allowedRoles = [
    "파트장",
    "TGO",
    "BCO1",
    "BCO2",
    "TO",
    "BO1",
    "BO2"
  ];


  if (
    !allowedRoles.includes(
      normalizedRole
    )
  ) {
    return null;
  }


  const previousContext =
    getPreviousShiftContext(
      dateValue,
      shiftValue
    );


  if (
    !previousContext
  ) {
    return null;
  }


  const normalizeShiftValue = (
    value
  ) => {
    return String(
      value ||
      ""
    )
      .trim()
      .toUpperCase()
      .replace(
        /\s+/g,
        ""
      )
      .replaceAll(
        "/",
        ""
      );
  };


  const getLogModifiedTime = (
    sourceLog
  ) => {
    const parsedTime =
      new Date(
        sourceLog?.updatedAt ||
        sourceLog?.createdAt ||
        0
      ).getTime();


    return Number.isFinite(
      parsedTime
    )
      ? parsedTime
      : 0;
  };


  /*
    저장 시점에 따라 구분명의
    띄어쓰기가 다르더라도 같은 구분으로 처리한다.
  */
  const normalizeHandoverCategory = (
    value
  ) => {
    const categoryText =
      String(
        value ||
        "인계사항"
      ).trim();


    const compactCategory =
      categoryText
        .toUpperCase()
        .replace(
          /\s+/g,
          ""
        );


    if (
      !compactCategory ||
      compactCategory ===
        "인계사항" ||
      compactCategory ===
        "인계"
    ) {
      return "인계사항";
    }


    if (
      compactCategory.includes(
        "비고"
      )
    ) {
      return "비고";
    }


    if (
      compactCategory.startsWith(
        "TM발행"
      )
    ) {
      return "TM 발행";
    }


    if (
      compactCategory.startsWith(
        "TM작업"
      )
    ) {
      return "TM 작업";
    }


    if (
      compactCategory.startsWith(
        "BM발행"
      )
    ) {
      return "BM 발행";
    }


    if (
      compactCategory.startsWith(
        "BM작업"
      )
    ) {
      return "BM 작업";
    }


    if (
      compactCategory.startsWith(
        "CM발행"
      )
    ) {
      return "CM 발행";
    }


    return (
      categoryText ||
      "인계사항"
    );
  };


  /*
    같은 날짜·근무·보직의 일지가 여러 개면
    가장 최근에 수정된 일지를 사용한다.
  */
  const findLatestPreviousLog = (
    sourceLogs
  ) => {
    const safeLogs =
      Array.isArray(
        sourceLogs
      )
        ? sourceLogs
        : [];


    return (
      safeLogs
        .filter(
          sourceLog => {
            return (
              String(
                sourceLog?.date ||
                ""
              ).trim() ===
                previousContext.date &&

              normalizeShiftValue(
                sourceLog?.shift
              ) ===
                normalizeShiftValue(
                  previousContext.shift
                ) &&

              normalizeMemberLogRole(
                sourceLog?.role
              ) ===
                normalizedRole
            );
          }
        )
        .sort(
          (
            firstLog,
            secondLog
          ) => {
            return (
              getLogModifiedTime(
                secondLog
              ) -
              getLogModifiedTime(
                firstLog
              )
            );
          }
        )[0] ||
      null
    );
  };


  /*
    업무일지 한 건에서 인계사항 영역에
    표시되는 항목만 추출한다.

    handoverEntries가 있으면 먼저 사용하고,
    없으면 기존 entries 배열을 사용한다.
  */
  const collectHandoverEntries = (
    sourceLog
  ) => {
    if (
      !sourceLog ||
      typeof sourceLog !==
        "object"
    ) {
      return [];
    }


    const candidates = [];


    const appendCandidate = (
      entry,
      entryIndex,
      sourceCollection
    ) => {
      const sourceEntry =
        entry &&
        typeof entry ===
          "object" &&
        !Array.isArray(
          entry
        )
          ? entry
          : {
              content:
                String(
                  entry ||
                  ""
                )
            };


      const category =
        normalizeHandoverCategory(
          sourceEntry.category ||
          "인계사항"
        );


      /*
        TM 발행은 위쪽 TM 발행 내역 영역이며,
        비고는 아래쪽 비고 영역이므로 제외한다.
      */
      if (
        category ===
          "TM 발행" ||
        category ===
          "비고"
      ) {
        return false;
      }


      const rawContent =
        String(
          sourceEntry.content ||
          sourceEntry.text ||
          ""
        )
          .replace(
            /\r\n/g,
            "\n"
          )
          .replace(
            /\r/g,
            "\n"
          )
          .trim();


      if (
        !rawContent
      ) {
        return false;
      }


      /*
        화면에서 자동으로 붙었던 번호만 제거한다.

        항목 내부의 줄바꿈과
        "- 하위 설명"은 그대로 유지한다.
      */
      const content =
        rawContent
          .replace(
            /^(?:\d+\s*[.)\-:：]\s*|[①②③④⑤⑥⑦⑧⑨⑩]\s*)/u,
            ""
          )
          .trim();


      if (
        !content
      ) {
        return false;
      }


      candidates.push({
        time:
          String(
            sourceEntry.time ||
            ""
          ).trim(),

        category,

        tag:
          String(
            sourceEntry.tag ||
            ""
          )
            .trim()
            .toUpperCase(),

        content,

        attachmentName:
          String(
            sourceEntry.attachmentName ||
            sourceEntry.fileName ||
            ""
          ).trim(),

        importedFromRole:
          normalizeMemberLogRole(
            sourceEntry.importedFromRole ||
            sourceEntry.sourceRole ||
            normalizedRole
          ),

        importedFromAuthor:
          String(
            sourceEntry.importedFromAuthor ||
            sourceLog.author ||
            ""
          ).trim(),

        importedFromLogId:
          String(
            sourceEntry.importedFromLogId ||
            sourceLog.id ||
            ""
          ).trim(),

        importedFromEntryIndex:
          sourceEntry
            .importedFromEntryIndex,

        entryIndex,

        sourceCollection
      });


      return true;
    };


    /*
      최신 분리 저장 배열 우선
    */
    if (
      Array.isArray(
        sourceLog.handoverEntries
      )
    ) {
      sourceLog.handoverEntries.forEach(
        (
          entry,
          entryIndex
        ) => {
          appendCandidate(
            entry,
            entryIndex,
            "handoverEntries"
          );
        }
      );
    }


    /*
      분리 배열에서 항목을 찾지 못했을 때만
      기존 entries 배열을 사용한다.
    */
    if (
      !candidates.length &&
      Array.isArray(
        sourceLog.entries
      )
    ) {
      sourceLog.entries.forEach(
        (
          entry,
          entryIndex
        ) => {
          appendCandidate(
            entry,
            entryIndex,
            "entries"
          );
        }
      );
    }


    /*
      handoverEntries와 entries에
      같은 항목이 중복 저장된 경우 한 번만 사용한다.

      구분·시간·TAG·내용 전체를
      하나의 중복 확인 단위로 사용한다.
    */
    const uniqueEntryMap =
      new Map();


    candidates.forEach(
      candidate => {
        const uniqueKey = [
          candidate.category,
          candidate.time,
          candidate.tag,
          candidate.content
        ]
          .map(
            value => {
              return String(
                value ||
                ""
              )
                .normalize(
                  "NFKC"
                )
                .replace(
                  /[\u200B-\u200D\u2060\uFEFF]/g,
                  ""
                )
                .replace(
                  /\s+/g,
                  " "
                )
                .trim()
                .toUpperCase();
            }
          )
          .join("||");


        if (
          !uniqueKey ||
          uniqueEntryMap.has(
            uniqueKey
          )
        ) {
          return;
        }


        const rawImportedIndex =
          candidate
            .importedFromEntryIndex;


        const importedFromEntryIndex =
          rawImportedIndex === "" ||
          rawImportedIndex === null ||
          rawImportedIndex === undefined
            ? null
            : Number(
                rawImportedIndex
              );


        uniqueEntryMap.set(
          uniqueKey,
          {
            time:
              candidate.time,

            category:
              candidate.category,

            tag:
              candidate.tag,

            /*
              여러 줄 내용도 한 항목으로 유지
            */
            content:
              candidate.content,

            attachmentName:
              candidate.attachmentName,

            importedFromRole:
              candidate.importedFromRole ||
              normalizedRole,

            importedFromAuthor:
              candidate.importedFromAuthor,

            importedFromLogId:
              candidate.importedFromLogId,

            importedFromEntryIndex:
              Number.isInteger(
                importedFromEntryIndex
              )
                ? importedFromEntryIndex
                : candidate.entryIndex,

            source:
              "previous-shift-handover",

            sourceCollection:
              candidate.sourceCollection,

            inheritedFromDate:
              previousContext.date,

            inheritedFromShift:
              previousContext.shift
          }
        );
      }
    );


    return [
      ...uniqueEntryMap.values()
    ];
  };


  const createResult = (
    sourceLog,
    sourceType
  ) => {
    return {
      role:
        normalizedRole,

      date:
        previousContext.date,

      shift:
        previousContext.shift,

      author:
        String(
          sourceLog?.author ||
          ""
        ).trim(),

      sourceLogId:
        String(
          sourceLog?.id ||
          ""
        ).trim(),

      source:
        sourceType,

      entries:
        collectHandoverEntries(
          sourceLog
        )
    };
  };


  /*
    1. 현재 불러온 신규 업무일지에서 조회
  */
  const currentPreviousLog =
    findLatestPreviousLog(
      appState.logs
    );


  if (
    currentPreviousLog
  ) {
    return createResult(
      currentPreviousLog,
      "current"
    );
  }


  /*
    2. D1 과거 업무일지에서 조회
  */
  const legacyLogs =
    await loadLegacyLogsForOperationStatusDate(
      previousContext.date
    );


  const legacyPreviousLog =
    findLatestPreviousLog(
      legacyLogs
    );


  if (
    legacyPreviousLog
  ) {
    return createResult(
      legacyPreviousLog,
      "legacy"
    );
  }


  return null;
}

/* =========================================================
  버튼으로 전 근무 인계사항 가져오기

  적용 방식:
  - 같은 보직의 직전 근무 인계사항 조회
  - 현재 작성한 항목은 그대로 유지
  - 중복되지 않은 항목만 추가
  - 시간·구분·TAG·줄바꿈 유지
  - 자동 저장하지 않음
========================================================= */

async function loadPreviousShiftHandoverEntriesForCurrentEditor() {
  const editorForm =
    elements.logEditorForm;


  const importButton =
    document.getElementById(
      "loadPreviousHandoverEntriesButton"
    );


  if (
    !editorForm ||
    !importButton
  ) {
    return;
  }


  const currentRole =
    normalizeMemberLogRole(
      elements.logRole?.value
    );


  const currentDate =
    String(
      elements.logDate?.value ||
      ""
    ).trim();


  const currentShift =
    String(
      elements.logShift?.value ||
      ""
    )
      .trim()
      .toUpperCase();


  const allowedRoles = [
    "파트장",
    "TGO",
    "BCO1",
    "BCO2",
    "TO",
    "BO1",
    "BO2"
  ];


  if (
    !allowedRoles.includes(
      currentRole
    ) ||
    !currentDate ||
    !currentShift
  ) {
    showToast(
      "날짜·근무·보직 정보를 먼저 확인해 주세요."
    );

    return;
  }


  const normalizeShiftValue = (
    value
  ) => {
    return String(
      value ||
      ""
    )
      .trim()
      .toUpperCase()
      .replace(
        /\s+/g,
        ""
      )
      .replaceAll(
        "/",
        ""
      );
  };


  /*
    저장 시점에 따라 구분명의
    띄어쓰기가 달라도 같은 구분으로 처리한다.
  */
  const normalizeHandoverCategory = (
    value
  ) => {
    const categoryText =
      String(
        value ||
        "인계사항"
      ).trim();


    const compactCategory =
      categoryText
        .toUpperCase()
        .replace(
          /\s+/g,
          ""
        );


    if (
      !compactCategory ||
      compactCategory ===
        "인계사항" ||
      compactCategory ===
        "인계"
    ) {
      return "인계사항";
    }


    if (
      compactCategory.includes(
        "비고"
      )
    ) {
      return "비고";
    }


    if (
      compactCategory.startsWith(
        "TM발행"
      )
    ) {
      return "TM 발행";
    }


    if (
      compactCategory.startsWith(
        "TM작업"
      )
    ) {
      return "TM 작업";
    }


    if (
      compactCategory.startsWith(
        "BM발행"
      )
    ) {
      return "BM 발행";
    }


    if (
      compactCategory.startsWith(
        "BM작업"
      )
    ) {
      return "BM 작업";
    }


    if (
      compactCategory.startsWith(
        "CM발행"
      )
    ) {
      return "CM 발행";
    }


    return (
      categoryText ||
      "인계사항"
    );
  };


  /*
    한 항목 안의 줄바꿈은 유지하고
    맨 앞에 저장된 기존 번호만 제거한다.
  */
  const normalizeHandoverContent = (
    value
  ) => {
    return String(
      value ||
      ""
    )
      .replace(
        /\r\n/g,
        "\n"
      )
      .replace(
        /\r/g,
        "\n"
      )
      .trim()
      .replace(
        /^(?:\d+\s*[.)\-:：]\s*|[①②③④⑤⑥⑦⑧⑨⑩]\s*)/u,
        ""
      )
      .trim();
  };


  /*
    구분·시간·TAG·내용이 모두 같을 때만
    동일한 항목으로 판단한다.
  */
  const createHandoverEntryKey = (
    entry
  ) => {
    const category =
      normalizeHandoverCategory(
        entry?.category
      );


    const content =
      normalizeHandoverContent(
        entry?.content
      );


    if (
      !content ||
      category ===
        "TM 발행" ||
      category ===
        "비고"
    ) {
      return "";
    }


    return [
      category,

      String(
        entry?.time ||
        ""
      ).trim(),

      String(
        entry?.tag ||
        ""
      )
        .trim()
        .toUpperCase(),

      content
    ]
      .map(
        value => {
          return String(
            value ||
            ""
          )
            .normalize(
              "NFKC"
            )
            .replace(
              /[\u200B-\u200D\u2060\uFEFF]/g,
              ""
            )
            .replace(
              /\s+/g,
              " "
            )
            .trim()
            .toUpperCase();
        }
      )
      .join("||");
  };


  const requestedContextKey = [
    currentRole,
    currentDate,
    normalizeShiftValue(
      currentShift
    )
  ].join("||");


  const requestToken =
    createId();


  appState.previousShiftHandoverRequestToken =
    requestToken;


  const originalButtonText =
    String(
      importButton.textContent ||
      "이전일지 가져오기"
    ).trim();


  importButton.disabled =
    true;

  importButton.textContent =
    "가져오는 중...";


  try {
    const previousHandoverResult =
      await getPreviousShiftHandoverEntries(
        currentRole,
        currentDate,
        currentShift
      );


    if (
      appState
        .previousShiftHandoverRequestToken !==
      requestToken
    ) {
      return;
    }


    /*
      조회 중 날짜·근무·보직이 변경되었다면
      현재 작성창에는 반영하지 않는다.
    */
    const latestContextKey = [
      normalizeMemberLogRole(
        elements.logRole?.value
      ),

      String(
        elements.logDate?.value ||
        ""
      ).trim(),

      normalizeShiftValue(
        elements.logShift?.value
      )
    ].join("||");


    if (
      requestedContextKey !==
      latestContextKey
    ) {
      showToast(
        "날짜·근무·보직이 변경되어 가져오기를 취소했습니다."
      );

      return;
    }


    const sourceEntries =
      Array.isArray(
        previousHandoverResult?.entries
      )
        ? previousHandoverResult.entries
        : [];


    if (
      !sourceEntries.length
    ) {
      showToast(
        `${currentRole} 전 근무 업무일지에 인계사항이 없습니다.`
      );

      return;
    }


    /*
      현재 작성창에 이미 존재하는
      인계사항 영역 항목을 수집한다.

      TM 발행과 비고는 제외한다.
    */
    const existingEntryKeys =
      new Set();


    (
      Array.isArray(
        appState.editorEntries
      )
        ? appState.editorEntries
        : []
    )
      .forEach(
        entry => {
          const uniqueKey =
            createHandoverEntryKey(
              entry
            );


          if (
            uniqueKey
          ) {
            existingEntryKeys.add(
              uniqueKey
            );
          }
        }
      );


    const importedEntries = [];


    sourceEntries.forEach(
      (
        entry,
        entryIndex
      ) => {
        const category =
          normalizeHandoverCategory(
            entry?.category
          );


        const time =
          String(
            entry?.time ||
            ""
          ).trim();


        const tag =
          String(
            entry?.tag ||
            ""
          )
            .trim()
            .toUpperCase();


        const content =
          normalizeHandoverContent(
            entry?.content
          );


        const normalizedEntry = {
          category,
          time,
          tag,
          content
        };


        const uniqueKey =
          createHandoverEntryKey(
            normalizedEntry
          );


        if (
          !content ||
          !uniqueKey ||
          existingEntryKeys.has(
            uniqueKey
          )
        ) {
          return;
        }


        existingEntryKeys.add(
          uniqueKey
        );


        const rawImportedIndex =
          entry
            ?.importedFromEntryIndex;


        const importedFromEntryIndex =
          rawImportedIndex === "" ||
          rawImportedIndex === null ||
          rawImportedIndex === undefined
            ? null
            : Number(
                rawImportedIndex
              );


        importedEntries.push({
          id:
            createId(),

          /*
            시간·구분·TAG·줄바꿈을
            이전 일지 원본대로 유지한다.
          */
          time,

          category,

          tag,

          content,

          attachmentName:
            String(
              entry?.attachmentName ||
              ""
            ).trim(),

          importedFromRole:
            normalizeMemberLogRole(
              entry?.importedFromRole ||
              previousHandoverResult?.role ||
              currentRole
            ),

          importedFromAuthor:
            String(
              entry?.importedFromAuthor ||
              previousHandoverResult?.author ||
              ""
            ).trim(),

          importedFromLogId:
            String(
              entry?.importedFromLogId ||
              previousHandoverResult
                ?.sourceLogId ||
              ""
            ).trim(),

          importedFromEntryIndex:
            Number.isInteger(
              importedFromEntryIndex
            )
              ? importedFromEntryIndex
              : entryIndex,

          source:
            "previous-shift-handover",

          sourceCollection:
            String(
              entry?.sourceCollection ||
              ""
            ).trim(),

          inheritedFromDate:
            String(
              previousHandoverResult?.date ||
              ""
            ).trim(),

          inheritedFromShift:
            String(
              previousHandoverResult?.shift ||
              ""
            )
              .trim()
              .toUpperCase()
        });
      }
    );


    if (
      !importedEntries.length
    ) {
      showToast(
        "전 근무 인계사항이 이미 모두 반영되어 있습니다."
      );

      return;
    }


    appState.editorEntries = [
      ...(
        Array.isArray(
          appState.editorEntries
        )
          ? appState.editorEntries
          : []
      ),

      ...importedEntries
    ];


    renderLogEntryTable();


    showToast(
      `${previousHandoverResult.date} ${previousHandoverResult.shift} ${currentRole} 인계사항 ${importedEntries.length}건을 가져왔습니다.`
    );

  } catch (error) {
    console.error(
      `${currentRole} 전 근무 인계사항 가져오기 실패:`,
      error
    );


    showToast(
      "전 근무 인계사항을 가져오지 못했습니다."
    );

  } finally {
    if (
      appState
        .previousShiftHandoverRequestToken ===
      requestToken
    ) {
      importButton.disabled =
        false;

      importButton.textContent =
        originalButtonText;
    }
  }
}

/* =========================================================
  TO · BO1 · BO2 운전현황 자유 텍스트 정리

  제거:
  1. 내용
  2) 내용
  3 - 내용
  ① 내용

  유지:
  1호기
  #3호기
  설비 4
  56°C
  TR Oil & Winding Temp

  줄바꿈은 그대로 유지한다.
========================================================= */

function normalizeManualOperationStatusContent(
  value
) {
  const normalizedLines =
    String(
      value ||
      ""
    )
      /*
        HTML 또는 문자열 형태 줄바꿈을
        실제 줄바꿈으로 통일한다.
      */
      .replace(
        /<br\s*\/?>/gi,
        "\n"
      )
      .replace(
        /\\n/g,
        "\n"
      )
      .replace(
        /\r\n/g,
        "\n"
      )
      .replace(
        /\r/g,
        "\n"
      )
      .split(
        "\n"
      )
      .map(
        line => {
          return String(
            line ||
            ""
          )
            /*
              문장 앞에 자동으로 붙은 번호만 제거한다.

              1.
              1)
              1 -
              ①
            */
            .replace(
              /^\s*(?:\d+\s*(?:[.)]|-\s+)\s*|[①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳]\s*)/u,
              ""
            )
            .trim();
        }
      )
      /*
        과거 자료에 들어 있는 보직 제목 줄 제거
      */
      .filter(
        line => {
          return (
            Boolean(
              line
            ) &&
            !/^\[\s*(?:TO|BO1|BO2)\s*\]$/i
              .test(
                line
              )
          );
        }
      );


  return normalizedLines
    .join(
      "\n"
    )
    .trim();
}

/* =========================================================
  모든 보직의 전 근무 운전현황 조회 최종본

  사용 보직:
  - TGO
  - BCO1
  - BCO2
  - TO
  - BO1
  - BO2

  조회 순서:
  1. 현재 불러온 신규 업무일지
  2. D1 과거 업무일지

  TGO·BCO1·BCO2:
  - 설비별 운전현황 배열까지 반환

  TO·BO1·BO2:
  - 자유 텍스트 운전현황 반환
========================================================= */

async function getPreviousShiftOperationStatus(
  roleValue,
  dateValue,
  shiftValue
) {
  const normalizedRole =
    normalizeMemberLogRole(
      roleValue
    );


  const equipmentRoles = [
    "TGO",
    "BCO1",
    "BCO2"
  ];


  const manualTextRoles = [
    "TO",
    "BO1",
    "BO2"
  ];


  const allowedRoles = [
    ...equipmentRoles,
    ...manualTextRoles
  ];


  if (
    !allowedRoles.includes(
      normalizedRole
    )
  ) {
    return null;
  }


  const previousContext =
    getPreviousShiftContext(
      dateValue,
      shiftValue
    );


  if (
    !previousContext
  ) {
    return null;
  }


  const normalizeShiftValue = (
    value
  ) => {
    return String(
      value ||
      ""
    )
      .trim()
      .toUpperCase()
      .replaceAll(
        "/",
        ""
      );
  };


  /*
    업무일지 한 건을
    전 근무 운전현황 객체로 변환한다.
  */
  const createPreviousStatusFromLog = (
    sourceLog
  ) => {
    if (
      !sourceLog ||
      typeof sourceLog !==
        "object"
    ) {
      return null;
    }


    const rawOperationItems =
      Array.isArray(
        sourceLog.operationStatusItems
      )
        ? sourceLog.operationStatusItems
        : (
            Array.isArray(
              sourceLog.operationItems
            )
              ? sourceLog.operationItems
              : (
                  Array.isArray(
                    sourceLog.items
                  )
                    ? sourceLog.items
                    : []
                )
          );


    const rawContent =
      String(
        sourceLog.operationStatus ||
        sourceLog.operationStatusContent ||
        ""
      ).trim();


    /*
      TO·BO1·BO2는 자유 텍스트 보직이다.

      - 설비형 배열로 변환하지 않는다.
      - 줄 앞 자동 번호만 제거한다.
      - 원래 줄바꿈은 유지한다.
    */
    if (
      manualTextRoles.includes(
        normalizedRole
      )
    ) {
      const fallbackContent =
        rawOperationItems
          .map(
            item => {
              if (
                typeof item ===
                  "string"
              ) {
                return item;
              }


              return String(
                item?.content ||
                item?.text ||
                ""
              );
            }
          )
          .filter(
            content => {
              return Boolean(
                String(
                  content ||
                  ""
                ).trim()
              );
            }
          )
          .join(
            "\n"
          )
          .trim();


      const manualContent =
        normalizeManualOperationStatusContent(
          rawContent ||
          fallbackContent
        );


      if (
        !manualContent
      ) {
        return null;
      }


      return {
        role:
          normalizedRole,

        date:
          previousContext.date,

        shift:
          previousContext.shift,

        author:
          String(
            sourceLog.author ||
            ""
          ).trim(),

        type:
          "normal",

        content:
          manualContent,

        operationItems:
          [],

        items:
          [],

        updatedAt:
          String(
            sourceLog.operationStatusUpdatedAt ||
            sourceLog.updatedAt ||
            sourceLog.createdAt ||
            ""
          ),

        updatedBy:
          String(
            sourceLog.operationStatusUpdatedBy ||
            sourceLog.author ||
            ""
          ).trim(),

        createdAt:
          String(
            sourceLog.createdAt ||
            ""
          )
      };
    }


    /*
      TGO·BCO1·BCO2만
      설비별 운전현황 구조로 변환한다.
    */
    const operationItems =
      getOperationStatusItems({
        role:
          normalizedRole,

        operationItems:
          rawOperationItems,

        items:
          rawOperationItems,

        content:
          rawContent,

        type:
          sourceLog.operationStatusType ||
          sourceLog.type ||
          "normal"
      })
        .map(
          (
            item,
            itemIndex
          ) => {
            return normalizeOperationStatusItem(
              {
                ...item,

                role:
                  normalizedRole,

                sourceRole:
                  normalizedRole
              },
              itemIndex
            );
          }
        );


    const content =
      operationItems.length
        ? serializeOperationStatusItems(
            operationItems
          )
        : rawContent;


    if (
      !content &&
      !operationItems.length
    ) {
      return null;
    }


    const representativeType =
      operationItems.length
        ? getRepresentativeOperationStatusType(
            operationItems
          )
        : normalizeOperationStatusType(
            sourceLog.operationStatusType ||
            sourceLog.type ||
            "normal"
          );


    return {
      role:
        normalizedRole,

      date:
        previousContext.date,

      shift:
        previousContext.shift,

      author:
        String(
          sourceLog.author ||
          ""
        ).trim(),

      type:
        representativeType,

      content,

      operationItems,

      items:
        operationItems,

      updatedAt:
        String(
          sourceLog.operationStatusUpdatedAt ||
          sourceLog.updatedAt ||
          sourceLog.createdAt ||
          ""
        ),

      updatedBy:
        String(
          sourceLog.operationStatusUpdatedBy ||
          sourceLog.author ||
          ""
        ).trim(),

      createdAt:
        String(
          sourceLog.createdAt ||
          ""
        )
    };
  };


  /*
    업무일지 배열에서 같은 보직의
    가장 최근 전 근무 일지를 찾는다.
  */
  const findLatestPreviousStatus = (
    sourceLogs
  ) => {
    const safeLogs =
      Array.isArray(
        sourceLogs
      )
        ? sourceLogs
        : [];


    const matchedStatuses =
      safeLogs
        .filter(
          sourceLog => {
            const sourceDate =
              String(
                sourceLog?.date ||
                ""
              ).trim();


            const sourceShift =
              normalizeShiftValue(
                sourceLog?.shift
              );


            const sourceRole =
              normalizeMemberLogRole(
                sourceLog?.role
              );


            return (
              sourceDate ===
                previousContext.date &&

              sourceShift ===
                normalizeShiftValue(
                  previousContext.shift
                ) &&

              sourceRole ===
                normalizedRole
            );
          }
        )
        .map(
          sourceLog => {
            return createPreviousStatusFromLog(
              sourceLog
            );
          }
        )
        .filter(Boolean)
        .sort(
          (
            firstStatus,
            secondStatus
          ) => {
            const firstTime =
              new Date(
                firstStatus.updatedAt ||
                firstStatus.createdAt ||
                0
              ).getTime();


            const secondTime =
              new Date(
                secondStatus.updatedAt ||
                secondStatus.createdAt ||
                0
              ).getTime();


            return (
              secondTime -
              firstTime
            );
          }
        );


    return (
      matchedStatuses[0] ||
      null
    );
  };


  /*
    1. 현재 불러온 D1 업무일지에서 조회
  */
  const currentStoredStatus =
    findLatestPreviousStatus(
      appState.logs
    );


  if (
    currentStoredStatus
  ) {
    return {
      ...currentStoredStatus,

      source:
        "current"
    };
  }


  /*
    2. D1 과거 업무일지에서 조회
  */
  const legacyLogs =
    await loadLegacyLogsForOperationStatusDate(
      previousContext.date
    );


  const legacyStatus =
    findLatestPreviousStatus(
      legacyLogs
    );


  if (
    legacyStatus
  ) {
    return {
      ...legacyStatus,

      source:
        "legacy"
    };
  }


  return null;
}

/* =========================================================
  선택 날짜의 D1 과거 업무일지 불러오기

  과거 서버를 직접 호출하지 않고
  legacy_logs 테이블에 보관된 자료만 사용한다.
========================================================= */

async function loadLegacyLogsForSelectedDate() {
  const selectedDate =
    formatInputDate(
      appState.selectedDate
    );


  try {
    const requestUrl =
      new URL(
        "/api/legacy-logs",
        window.location.origin
      );


    /*
      근무값을 지정하지 않아
      선택 날짜의 D/S와 N/S를 한 번에 불러온다.
    */
    requestUrl.searchParams.set(
      "date",
      selectedDate
    );


    /*
      이전 응답이나 브라우저 캐시를 피한다.
    */
    requestUrl.searchParams.set(
      "_",
      String(
        Date.now()
      )
    );


    const response =
      await fetch(
        requestUrl.toString(),
        {
          method:
            "GET",

          headers: {
            Accept:
              "application/json"
          },

          cache:
            "no-store"
        }
      );


    let result = {};


    try {
      result =
        await response.json();

    } catch {
      throw new Error(
        "D1 과거 업무일지 응답을 읽을 수 없습니다."
      );
    }


    if (
      !response.ok ||
      !result.success
    ) {
      throw new Error(
        result.message ||
        "저장된 과거 업무일지를 불러오지 못했습니다."
      );
    }


    /*
      이전에 메모리에 불러온 같은 날짜의
      과거 자료만 제거한다.

      GS Shift Log에서 직접 작성한 신규 업무일지는 유지한다.
    */
    appState.logs =
      appState.logs.filter(
        log => {
          const isSameDate =
            String(
              log.date ||
              ""
            ).trim() ===
            selectedDate;


          const isLegacyLog =
            String(
              log.source ||
              ""
            ).startsWith(
              "legacy"
            );


          return !(
            isSameDate &&
            isLegacyLog
          );
        }
      );


    const storedItems =
      Array.isArray(
        result.items
      )
        ? result.items
        : [];


    const convertedLogs =
      storedItems
        .map(
          (
            storedItem,
            itemIndex
          ) => {
            const originalItem =
              storedItem?.original &&
              typeof storedItem.original ===
                "object"
                ? storedItem.original
                : null;


            if (!originalItem) {
              console.warn(
                "과거 업무일지 원본이 없어 제외했습니다.",
                storedItem
              );

              return null;
            }


            const storedShift =
              String(
                storedItem.shift ||
                ""
              )
                .trim()
                .toUpperCase();


            const convertedLog =
              convertLegacyDiaryToLog(
                originalItem,
                itemIndex,
                selectedDate,
                storedShift
              );


            if (!convertedLog) {
              return null;
            }


            /*
              legacy-logs API에서 반환한 첨부파일을
              변환된 업무일지에 그대로 연결한다.

              기존 코드에서는 original만 넘기면서
              storedItem.attachments가 유실되고 있었다.
            */
            convertedLog.attachments =
              Array.isArray(
                storedItem.attachments
              )
                ? storedItem.attachments
                    .map(
                      attachment => {
                        const attachmentId =
                          Number(
                            attachment?.id ||
                            0
                          );


                        const fileName =
                          String(
                            attachment?.fileName ||
                            attachment?.name ||
                            ""
                          ).trim();


                        const attachmentUrl =
                          String(
                            attachment?.url ||
                            (
                              attachmentId
                                ? `/api/legacy-attachment?id=${encodeURIComponent(
                                    attachmentId
                                  )}`
                                : ""
                            )
                          ).trim();


                        return {
                          id:
                            attachmentId,

                          name:
                            fileName,

                          fileName,

                          mimeType:
                            String(
                              attachment?.mimeType ||
                              ""
                            ).trim(),

                          fileSize:
                            Number(
                              attachment?.fileSize ||
                              0
                            ),

                          r2Key:
                            String(
                              attachment?.r2Key ||
                              ""
                            ).trim(),

                          originalUrl:
                            String(
                              attachment?.originalUrl ||
                              ""
                            ).trim(),

                          uploadedAt:
                            String(
                              attachment?.uploadedAt ||
                              ""
                            ).trim(),

                          url:
                            attachmentUrl
                        };
                      }
                    )
                    .filter(
                      attachment => {
                        return Boolean(
                          attachment.url
                        );
                      }
                    )
                : [];


            convertedLog.legacyAttachmentCount =
              convertedLog
                .attachments
                .length;


            return convertedLog;
          }
        )
        .filter(Boolean);


    /*
      과거 파트장 업무일지는
      D/S와 N/S별로 분리하여 재구성한다.
    */
    if (
      selectedDate <=
      "2026-07-21"
    ) {
      const dsLogs =
        convertedLogs.filter(
          log => {
            return (
              log.shift ===
              "DS"
            );
          }
        );


      const nsLogs =
        convertedLogs.filter(
          log => {
            return (
              log.shift ===
              "NS"
            );
          }
        );


      rebuildLegacyLeaderLogFromMemberLogs(
        dsLogs
      );


      rebuildLegacyLeaderLogFromMemberLogs(
        nsLogs
      );
    }


    /*
      D1 과거 자료를 먼저 넣고
      신규 GS Shift Log 자료는 그대로 유지한다.
    */
    appState.logs = [
      ...convertedLogs,
      ...appState.logs
    ];


    const dsCount =
      convertedLogs.filter(
        log => {
          return (
            log.shift ===
            "DS"
          );
        }
      ).length;


    const nsCount =
      convertedLogs.filter(
        log => {
          return (
            log.shift ===
            "NS"
          );
        }
      ).length;


    const attachmentCount =
      convertedLogs.reduce(
        (
          total,
          log
        ) => {
          return (
            total +
            (
              Array.isArray(
                log.attachments
              )
                ? log.attachments.length
                : 0
            )
          );
        },
        0
      );


    console.log(
      [
        `D1 과거 업무일지 D/S ${dsCount}건`,
        `N/S ${nsCount}건`,
        `첨부파일 ${attachmentCount}건을 불러왔습니다.`
      ].join(", ")
    );

  } catch (error) {
    console.error(
      "D1 과거 업무일지 불러오기 실패:",
      error
    );


    /*
      D1 조회에 실패해도
      신규 GS Shift Log 기능은 계속 작동한다.
    */
  }
}

/* =========================================================
  과거 파트장 업무일지 재구성 최종본

  처리 기준:
  - TGO·BCO1·BCO2: TM·업무·비고 전체 취합
  - TO·BO1·BO2: TM만 취합
  - 기존 파트장 통합본문 중 팀원 원본과 같은 내용 제거
  - 팀원 원본과 일치하지 않는 항목만 파트장 직접 업무로 유지
  - TM / 업무 / 비고를 각각 분리 저장
========================================================= */

function rebuildLegacyLeaderLogFromMemberLogs(
  convertedLogs
) {
  if (
    !Array.isArray(
      convertedLogs
    ) ||
    convertedLogs.length ===
      0
  ) {
    return;
  }


  const fullImportRoles = [
    "TGO",
    "BCO1",
    "BCO2"
  ];


  const tmOnlyRoles = [
    "TO",
    "BO1",
    "BO2"
  ];


  const allMemberRoles = [
    ...fullImportRoles,
    ...tmOnlyRoles
  ];


  const leaderLog =
    convertedLogs.find(
      (
        log
      ) => {
        return (
          normalizeMemberLogRole(
            log?.role
          ) ===
          "파트장"
        );
      }
    );


  if (
    !leaderLog
  ) {
    return;
  }


  /* =====================================================
    구분명 정규화
  ====================================================== */

  const normalizeCategory = (
    category,
    fallbackCategory =
      "인계사항"
  ) => {
    const categoryText =
      String(
        category ||
        fallbackCategory ||
        "인계사항"
      ).trim();


    if (
      categoryText.includes(
        "비고"
      )
    ) {
      return "비고";
    }


    if (
      categoryText
        .toUpperCase()
        .replace(
          /\s+/g,
          ""
        )
        .startsWith(
          "TM"
        )
    ) {
      return "TM 발행";
    }


    return (
      categoryText ||
      "인계사항"
    );
  };


  /* =====================================================
    비교용 대분류
  ====================================================== */

  const getCategoryGroup = (
    category
  ) => {
    const normalizedCategory =
      normalizeCategory(
        category
      );


    if (
      normalizedCategory ===
      "TM 발행"
    ) {
      return "tm";
    }


    if (
      normalizedCategory ===
      "비고"
    ) {
      return "remark";
    }


    return "work";
  };


  /* =====================================================
    업무일지 한 건의 전체 항목 수집

    새 분리 배열이 존재하면:
    - tmEntries
    - handoverEntries
    - remarkEntries

    없으면 기존 entries를 사용한다.
  ====================================================== */

  const collectLogEntries = (
    sourceLog
  ) => {
    if (
      !sourceLog ||
      typeof sourceLog !==
        "object"
    ) {
      return [];
    }


    const separatedEntries = [];


    if (
      Array.isArray(
        sourceLog.tmEntries
      )
    ) {
      sourceLog.tmEntries.forEach(
        (
          entry
        ) => {
          separatedEntries.push({
            ...entry,

            category:
              "TM 발행"
          });
        }
      );
    }


    if (
      Array.isArray(
        sourceLog.handoverEntries
      )
    ) {
      sourceLog.handoverEntries.forEach(
        (
          entry
        ) => {
          separatedEntries.push({
            ...entry,

            category:
              normalizeCategory(
                entry?.category,
                "인계사항"
              )
          });
        }
      );
    }


    if (
      Array.isArray(
        sourceLog.remarkEntries
      )
    ) {
      sourceLog.remarkEntries.forEach(
        (
          entry
        ) => {
          separatedEntries.push({
            ...entry,

            category:
              "비고",

            time:
              "",

            tag:
              ""
          });
        }
      );
    }


    const hasSeparatedEntries =
      separatedEntries.some(
        (
          entry
        ) => {
          return Boolean(
            String(
              entry?.content ||
              ""
            ).trim()
          );
        }
      );


    const sourceEntries =
      hasSeparatedEntries
        ? separatedEntries
        : (
            Array.isArray(
              sourceLog.entries
            )
              ? sourceLog.entries
              : []
          );


    const normalizedEntries =
      sourceEntries
        .map(
          (
            entry,
            entryIndex
          ) => {
            const category =
              normalizeCategory(
                entry?.category,
                "인계사항"
              );


            return {
              ...entry,

              category,

              time:
                category ===
                  "비고"
                  ? ""
                  : String(
                      entry?.time ||
                      ""
                    ).trim(),

              tag:
                category ===
                  "비고"
                  ? ""
                  : String(
                      entry?.tag ||
                      ""
                    )
                      .trim()
                      .toUpperCase(),

              content:
                String(
                  entry?.content ||
                  ""
                ).trim(),

              sourceEntryIndex:
                entryIndex
            };
          }
        )
        .filter(
          (
            entry
          ) => {
            return Boolean(
              entry.content
            );
          }
        );


    /*
      비고 배열과 entries에 비고가 없을 때만
      기존 note 문자열을 추가한다.
    */
    const hasRemark =
      normalizedEntries.some(
        (
          entry
        ) => {
          return (
            entry.category ===
            "비고"
          );
        }
      );


    if (
      !hasRemark &&
      String(
        sourceLog.note ||
        ""
      ).trim()
    ) {
      String(
        sourceLog.note
      )
        .replace(
          /\r\n/g,
          "\n"
        )
        .replace(
          /\r/g,
          "\n"
        )
        .split(
          "\n"
        )
        .map(
          (
            line
          ) => {
            return String(
              line ||
              ""
            )
              .replace(
                /^\s*\d+\s*[.)\-:]\s*/,
                ""
              )
              .trim();
          }
        )
        .filter(Boolean)
        .forEach(
          (
            content,
            noteIndex
          ) => {
            normalizedEntries.push({
              id:
                "",

              category:
                "비고",

              time:
                "",

              tag:
                "",

              content,

              sourceEntryIndex:
                normalizedEntries.length +
                noteIndex
            });
          }
        );
    }


    return normalizedEntries;
  };


  /* =====================================================
    두 항목이 같은 원본 업무인지 판정
  ====================================================== */

  const isSameSourceEntry = (
    firstEntry,
    secondEntry
  ) => {
    if (
      getCategoryGroup(
        firstEntry?.category
      ) !==
      getCategoryGroup(
        secondEntry?.category
      )
    ) {
      return false;
    }


    const firstTag =
      String(
        firstEntry?.tag ||
        ""
      )
        .trim()
        .toUpperCase();


    const secondTag =
      String(
        secondEntry?.tag ||
        ""
      )
        .trim()
        .toUpperCase();


    /*
      양쪽 모두 TAG가 있는데 다르면
      다른 업무로 판단한다.
    */
    if (
      firstTag &&
      secondTag &&
      firstTag !==
        secondTag
    ) {
      return false;
    }


    const firstContent =
      String(
        firstEntry?.content ||
        ""
      ).trim();


    const secondContent =
      String(
        secondEntry?.content ||
        ""
      ).trim();


    if (
      !firstContent ||
      !secondContent
    ) {
      return false;
    }


    const firstNormalizedContent =
      normalizeMemberImportContent(
        firstContent
      );


    const secondNormalizedContent =
      normalizeMemberImportContent(
        secondContent
      );


    /*
      완전히 같은 내용
    */
    if (
      firstNormalizedContent &&
      firstNormalizedContent ===
        secondNormalizedContent
    ) {
      return true;
    }


    /*
      표현이나 공백만 조금 다른 기존 자료
    */
    return (
      calculateLegacyContentSimilarity(
        firstContent,
        secondContent
      ) >=
      0.93
    );
  };


  /* =====================================================
    팀원 원본 업무 취합
  ====================================================== */

  const memberImportedEntries = [];


  allMemberRoles.forEach(
    (
      memberRole
    ) => {
      const memberLog =
        convertedLogs.find(
          (
            log
          ) => {
            return (
              normalizeMemberLogRole(
                log?.role
              ) ===
              memberRole
            );
          }
        );


      if (
        !memberLog
      ) {
        return;
      }


      const memberEntries =
        collectLogEntries(
          memberLog
        );


      memberEntries.forEach(
        (
          entry,
          entryIndex
        ) => {
          const category =
            normalizeCategory(
              entry.category
            );


          const isTmEntry =
            category ===
            "TM 발행";


          const canImportAll =
            fullImportRoles.includes(
              memberRole
            );


          /*
            TGO·BCO1·BCO2:
            TM·업무·비고 전체

            TO·BO1·BO2:
            TM만
          */
          if (
            !canImportAll &&
            !isTmEntry
          ) {
            return;
          }


          memberImportedEntries.push({
            ...entry,

            category,

            importedFromRole:
              memberRole,

            importedFromAuthor:
              String(
                memberLog.author ||
                ""
              ).trim(),

            importedFromLogId:
              String(
                memberLog.id ||
                ""
              ).trim(),

            importedFromEntryIndex:
              Number.isInteger(
                entry.sourceEntryIndex
              )
                ? entry.sourceEntryIndex
                : entryIndex,

            source:
              "legacy-member-copy"
          });
        }
      );
    }
  );


  /* =====================================================
    기존 파트장 본문의 실제 직접 업무만 추출

    기존 통합자료는 TGO·BCO1·BCO2 업무가
    파트장 출처로 잘못 저장돼 있을 수 있다.

    따라서 팀원 원본과 같은 항목은 제거하고,
    어느 팀원 원본에도 없는 항목만
    파트장 직접 업무로 유지한다.
  ====================================================== */

  const leaderOwnEntries =
    collectLogEntries(
      leaderLog
    )
      .filter(
        (
          leaderEntry
        ) => {
          return !memberImportedEntries.some(
            (
              memberEntry
            ) => {
              return isSameSourceEntry(
                leaderEntry,
                memberEntry
              );
            }
          );
        }
      )
      .map(
        (
          entry,
          entryIndex
        ) => {
          return {
            ...entry,

            category:
              normalizeCategory(
                entry.category
              ),

            importedFromRole:
              "파트장",

            importedFromAuthor:
              String(
                leaderLog.author ||
                ""
              ).trim(),

            importedFromLogId:
              String(
                leaderLog.id ||
                ""
              ).trim(),

            importedFromEntryIndex:
              Number.isInteger(
                entry.sourceEntryIndex
              )
                ? entry.sourceEntryIndex
                : entryIndex,

            source:
              "legacy-leader-own"
          };
        }
      );


  /* =====================================================
    TM 상·하위 보직 중복 제거
  ====================================================== */

  const hierarchyFilteredEntries =
    filterLeaderTmEntriesByRoleHierarchy([
      ...memberImportedEntries,
      ...leaderOwnEntries
    ]);


  /* =====================================================
    최종 완전 중복 제거
  ====================================================== */

  const uniqueEntryMap =
    new Map();


  hierarchyFilteredEntries.forEach(
    (
      entry
    ) => {
      const category =
        normalizeCategory(
          entry.category
        );


      const sourceRole =
        normalizeMemberLogRole(
          entry.importedFromRole ||
          "파트장"
        );


      const contentKey =
        normalizeMemberImportContent(
          entry.content
        ) ||
        String(
          entry.content ||
          ""
        )
          .trim()
          .replace(
            /\s+/g,
            " "
          )
          .toLowerCase();


      /*
        비고는 보직이 달라도 내용이 같으면
        한 번만 표시한다.

        일반 업무는 같은 내용이어도
        보직이 다르면 각각 유지한다.
      */
      const uniqueKey = [
        category,

        category ===
          "비고"
          ? ""
          : sourceRole,

        String(
          entry.time ||
          ""
        ).trim(),

        String(
          entry.tag ||
          ""
        )
          .trim()
          .toUpperCase(),

        contentKey
      ].join(
        "||"
      );


      if (
        !uniqueEntryMap.has(
          uniqueKey
        )
      ) {
        uniqueEntryMap.set(
          uniqueKey,
          {
            ...entry,

            category,

            importedFromRole:
              sourceRole
          }
        );
      }
    }
  );


  const finalEntries = [
    ...uniqueEntryMap.values()
  ];


  /* =====================================================
    최종 저장 구조

    비고가 handoverEntries로 들어가지 않도록
    세 배열을 완전히 분리한다.
  ====================================================== */

  const tmEntries =
    finalEntries.filter(
      (
        entry
      ) => {
        return (
          entry.category ===
          "TM 발행"
        );
      }
    );


  const remarkEntries =
    finalEntries.filter(
      (
        entry
      ) => {
        return (
          entry.category ===
          "비고"
        );
      }
    );


  const handoverEntries =
    finalEntries.filter(
      (
        entry
      ) => {
        return (
          entry.category !==
            "TM 발행" &&
          entry.category !==
            "비고"
        );
      }
    );


  leaderLog.tmEntries =
    tmEntries;


  leaderLog.handoverEntries =
    handoverEntries;


  leaderLog.remarkEntries =
    remarkEntries;


  /*
    기존 코드 호환용 전체 배열
  */
  leaderLog.entries = [
    ...tmEntries,
    ...handoverEntries,
    ...remarkEntries
  ];


  /*
    기존 비고 문자열 호환
  */
  leaderLog.note =
    remarkEntries
      .map(
        (
          entry
        ) => {
          return String(
            entry.content ||
            ""
          ).trim();
        }
      )
      .filter(Boolean)
      .join("\n");


  leaderLog.legacyRebuiltFromMembers =
    true;
}

/* =========================================================
  파트장 TM 발행 내역 중복 정리

  상위 보직:
  TGO, BCO1, BCO2

  하위 보직:
  TO, BO1, BO2

  상위·하위 보직의 TM 내용이
  70% 이상 유사하면 상위 보직 항목만 유지한다.
========================================================= */

function getUpperRoleForTmRole(
  role
) {
  const normalizedRole =
    normalizeMemberLogRole(
      role
    );

  const upperRoleMap = {
    TO:
      "TGO",

    BO1:
      "BCO1",

    BO2:
      "BCO2"
  };

  return (
    upperRoleMap[
      normalizedRole
    ] ||
    ""
  );
}

function filterLeaderTmEntriesByRoleHierarchy(
  entries
) {
  const sourceEntries =
    Array.isArray(
      entries
    )
      ? entries
      : [];


  /*
    상위·하위 보직 비교 기준

    TGO  > TO
    BCO1 > BO1
    BCO2 > BO2
  */
  const memberSimilarityThreshold =
    0.7;


  /*
    BCO 보직 간 비교 기준

    BCO1 > BCO2
  */
  const bcoSimilarityThreshold =
    0.8;


  const upperRoles = [
    "TGO",
    "BCO1",
    "BCO2"
  ];


  const lowerRoles = [
    "TO",
    "BO1",
    "BO2"
  ];


  /*
    TM 발행이 아닌 항목은
    중복 비교하지 않고 그대로 유지한다.
  */
  const nonTmEntries =
    sourceEntries.filter(
      (
        entry
      ) => {
        return (
          String(
            entry.category ||
            ""
          ).trim() !==
          "TM 발행"
        );
      }
    );


  /*
    TM 발행 항목만 분리한다.
  */
  const tmEntries =
    sourceEntries.filter(
      (
        entry
      ) => {
        return (
          String(
            entry.category ||
            ""
          ).trim() ===
          "TM 발행"
        );
      }
    );


  /*
    TGO·BCO1·BCO2 TM을 분리한다.
  */
  const upperTmEntries =
    tmEntries.filter(
      (
        entry
      ) => {
        const sourceRole =
          normalizeMemberLogRole(
            entry.importedFromRole
          );


        return upperRoles.includes(
          sourceRole
        );
      }
    );


  /*
    BCO1 TM을 따로 준비한다.

    BCO2와 80% 이상 중복되는지
    비교할 때 사용한다.
  */
  const bco1TmEntries =
    upperTmEntries.filter(
      (
        entry
      ) => {
        return (
          normalizeMemberLogRole(
            entry.importedFromRole
          ) ===
          "BCO1"
        );
      }
    );


  /*
    BCO1 > BCO2 중복 제거

    BCO2 TM 내용이 BCO1 TM과
    80% 이상 유사하면 BCO2 TM을 제외한다.

    TGO와 BCO1 TM은 그대로 유지한다.
  */
  const filteredUpperTmEntries =
    upperTmEntries.filter(
      (
        entry
      ) => {
        const sourceRole =
          normalizeMemberLogRole(
            entry.importedFromRole
          );


        if (
          sourceRole !==
          "BCO2"
        ) {
          return true;
        }


        const bco2Content =
          String(
            entry.content ||
            ""
          ).trim();


        const hasSimilarBco1Entry =
          bco1TmEntries.some(
            (
              bco1Entry
            ) => {
              const bco1Content =
                String(
                  bco1Entry.content ||
                  ""
                ).trim();


              const similarity =
                calculateLegacyContentSimilarity(
                  bco1Content,
                  bco2Content
                );


              return (
                similarity >=
                bcoSimilarityThreshold
              );
            }
          );


        /*
          BCO1과 중복되지 않는
          BCO2 TM만 유지한다.
        */
        return !hasSimilarBco1Entry;
      }
    );


  /*
    TO·BO1·BO2 TM 중복 제거

    TGO  > TO
    BCO1 > BO1
    BCO2 > BO2

    대응하는 상위 보직과
    70% 이상 유사하면 하위 보직 TM을 제외한다.
  */
  const filteredLowerTmEntries =
    tmEntries.filter(
      (
        entry
      ) => {
        const lowerRole =
          normalizeMemberLogRole(
            entry.importedFromRole
          );


        if (
          !lowerRoles.includes(
            lowerRole
          )
        ) {
          return false;
        }


        const upperRole =
          getUpperRoleForTmRole(
            lowerRole
          );


        const lowerContent =
          String(
            entry.content ||
            ""
          ).trim();


        /*
          BCO2가 BCO1과 중복되어
          최종 목록에서 제외되더라도,
          BO2와의 중복 판단에는 원래 BCO2 TM을 사용한다.

          따라서 동일 계통의 중복 항목이
          다시 BO2로 남는 것을 방지한다.
        */
        const hasSimilarUpperEntry =
          upperTmEntries.some(
            (
              upperEntry
            ) => {
              const upperEntryRole =
                normalizeMemberLogRole(
                  upperEntry.importedFromRole
                );


              if (
                upperEntryRole !==
                upperRole
              ) {
                return false;
              }


              const upperContent =
                String(
                  upperEntry.content ||
                  ""
                ).trim();


              const similarity =
                calculateLegacyContentSimilarity(
                  upperContent,
                  lowerContent
                );


              return (
                similarity >=
                memberSimilarityThreshold
              );
            }
          );


        return !hasSimilarUpperEntry;
      }
    );


  /*
    출처 보직이 없는 기존 TM이나
    파트장이 직접 작성한 TM은 그대로 유지한다.
  */
  const otherTmEntries =
    tmEntries.filter(
      (
        entry
      ) => {
        const sourceRole =
          normalizeMemberLogRole(
            entry.importedFromRole
          );


        return (
          !upperRoles.includes(
            sourceRole
          ) &&
          !lowerRoles.includes(
            sourceRole
          )
        );
      }
    );


  return [
    ...filteredUpperTmEntries,
    ...filteredLowerTmEntries,
    ...otherTmEntries,
    ...nonTmEntries
  ];
}

function calculateLegacyContentSimilarity(
  firstContent,
  secondContent
) {
  const firstText =
    normalizeLegacyContentForComparison(
      firstContent
    );

  const secondText =
    normalizeLegacyContentForComparison(
      secondContent
    );

  if (
    !firstText ||
    !secondText
  ) {
    return 0;
  }

  if (
    firstText ===
    secondText
  ) {
    return 1;
  }

  /*
    한쪽 문장이 다른 문장을 포함하는 경우
  */
  const shorterText =
    firstText.length <=
    secondText.length
      ? firstText
      : secondText;

  const longerText =
    firstText.length >
    secondText.length
      ? firstText
      : secondText;

  const containmentScore =
    longerText.includes(
      shorterText
    )
      ? Math.min(
          1,
          shorterText.length /
          Math.max(
            longerText.length,
            1
          ) +
          0.2
        )
      : 0;


  /*
    글자 두 개 단위 유사도
  */
  const diceScore =
    calculateDiceSimilarity(
      firstText,
      secondText
    );


  /*
    단어 및 설비 핵심어 유사도

    영문 설비명, TAG, 숫자, 한글 단어가
    얼마나 겹치는지 추가로 비교한다.
  */
  const firstTokens =
    createLegacyComparisonTokens(
      firstContent
    );

  const secondTokens =
    createLegacyComparisonTokens(
      secondContent
    );

  const tokenScore =
    calculateLegacyTokenSimilarity(
      firstTokens,
      secondTokens
    );


  /*
    문장 길이가 다르더라도
    주요 단어가 동일하면 높은 점수를 준다.
  */
  const combinedScore =
    (
      diceScore *
      0.45
    ) +
    (
      tokenScore *
      0.55
    );

  return Math.max(
    containmentScore,
    diceScore,
    tokenScore,
    combinedScore
  );
}

function createLegacyComparisonTokens(
  content
) {
  const ignoredTokens =
    new Set([
      "실시",
      "확인",
      "점검",
      "운전",
      "작업",
      "완료",
      "정상",
      "양호",
      "관련",
      "및",
      "후",
      "중",
      "전",
      "업무",
      "인계사항"
    ]);

  return String(
    content || ""
  )
    .toLowerCase()

    /*
      수기 번호 제거
    */
    .replace(
      /^\s*\d+\s*[.)\-:]\s*/,
      ""
    )

    /*
      시간 표현은 비교에서 제외
    */
    .replace(
      /\b(?:[01]?\d|2[0-3]):[0-5]\d\b/g,
      " "
    )

    /*
      한글·영문·숫자만 남긴다.
    */
    .replace(
      /[^a-z0-9가-힣]+/g,
      " "
    )
    .trim()
    .split(/\s+/)
    .map((token) => {
      return token.trim();
    })
    .filter((token) => {
      return (
        token.length >= 2 &&
        !ignoredTokens.has(
          token
        )
      );
    });
}


function calculateLegacyTokenSimilarity(
  firstTokens,
  secondTokens
) {
  if (
    !Array.isArray(
      firstTokens
    ) ||
    !Array.isArray(
      secondTokens
    ) ||
    !firstTokens.length ||
    !secondTokens.length
  ) {
    return 0;
  }

  const firstSet =
    new Set(
      firstTokens
    );

  const secondSet =
    new Set(
      secondTokens
    );

  const matchedTokens = [
    ...firstSet
  ].filter((token) => {
    return secondSet.has(
      token
    );
  });

  if (
    !matchedTokens.length
  ) {
    return 0;
  }

  const smallerTokenCount =
    Math.min(
      firstSet.size,
      secondSet.size
    );

  const largerTokenCount =
    Math.max(
      firstSet.size,
      secondSet.size
    );

  const coverageScore =
    matchedTokens.length /
    smallerTokenCount;

  const balanceScore =
    matchedTokens.length /
    largerTokenCount;

  return (
    coverageScore *
    0.7
  ) +
  (
    balanceScore *
    0.3
  );
}


function normalizeLegacyContentForComparison(
  content
) {
  return String(
    content || ""
  )
    .toLowerCase()

    /*
      줄 앞의 수기 번호 제거
    */
    .replace(
      /^\s*\d+\s*[.)\-:]\s*/,
      ""
    )

    /*
      문장 앞 시간 제거
    */
    .replace(
      /^\s*(?:[01]?\d|2[0-3]):[0-5]\d\s*/,
      ""
    )

    /*
      비교에 방해되는 기호와 공백 제거
    */
    .replace(
      /[^a-z0-9가-힣]/g,
      ""
    )
    .trim();
}


function calculateDiceSimilarity(
  firstText,
  secondText
) {
  if (
    firstText.length < 2 ||
    secondText.length < 2
  ) {
    return (
      firstText ===
      secondText
        ? 1
        : 0
    );
  }

  const firstBigrams =
    [];

  const secondBigrams =
    [];

  for (
    let index = 0;
    index <
    firstText.length - 1;
    index += 1
  ) {
    firstBigrams.push(
      firstText.slice(
        index,
        index + 2
      )
    );
  }

  for (
    let index = 0;
    index <
    secondText.length - 1;
    index += 1
  ) {
    secondBigrams.push(
      secondText.slice(
        index,
        index + 2
      )
    );
  }

  const remainingBigrams =
    [...secondBigrams];

  let matchCount = 0;

  firstBigrams.forEach(
    (bigram) => {
      const matchedIndex =
        remainingBigrams.indexOf(
          bigram
        );

      if (
        matchedIndex === -1
      ) {
        return;
      }

      matchCount += 1;

      remainingBigrams.splice(
        matchedIndex,
        1
      );
    }
  );

  return (
    2 *
    matchCount /
    (
      firstBigrams.length +
      secondBigrams.length
    )
  );
}

/* =========================================================
  기존 파트장 일지 body index → 담당 보직
========================================================= */

function convertLegacyBodyIndexToRole(
  bodyIndex,
  diaryRole
) {
  const normalizedDiaryRole =
    normalizeMemberLogRole(
      diaryRole
    );

  /*
    일반 근무자 업무일지는
    모든 항목을 해당 근무자의 업무로 처리한다.
  */
  if (
    normalizedDiaryRole !==
    "파트장"
  ) {
    return normalizedDiaryRole;
  }

  /*
    기존 파트장 업무일지 구조

    index 0 : 운전현황
    index 1 : TM 발행 내역
    index 2 : TGO 업무
    index 3 : BCO1 업무
    index 4 : BCO2 업무
    index 5 : TO 업무
    index 6 : BO1 업무
    index 7 : BO2 업무
    index 8 : 파트장 직접 작성 업무
  */
  const roleMap = {
    2: "TGO",
    3: "BCO1",
    4: "BCO2",
    5: "TO",
    6: "BO1",
    7: "BO2",
    8: "파트장"
  };

  return (
    roleMap[
      Number(bodyIndex)
    ] ||
    "파트장"
  );
}

/* =========================================================
  기존 업무일지 1건을 현재 구조로 변환
========================================================= */

/* =========================================================
  기존 업무일지 1건을 현재 구조로 변환 최종본

  이전 시스템 원본 body index 기준

  일반 보직:
  index 0 : 운전현황
  index 1 : TM 발행 내역
  index 2 : 인계 및 작업 내역
  index 3 : 비고

  현재 파트장 통합 구조:
  index 0 : 운전현황
  index 1 : TM 발행 내역
  index 2 : 통합 인계 및 작업 내역
  index 4 : 비고

  과거 파트장 보직별 구조:
  index 2 : TGO
  index 3 : BCO1
  index 4 : BCO2
  index 5 : TO
  index 6 : BO1
  index 7 : BO2
  index 8 : 파트장

  기존 호환:
  - entries 단일 배열 유지
  - note 문자열 유지

  주의:
  과거 파트장 재구성 함수와 충돌하지 않도록
  legacy 변환 단계에서는 분리 배열을 직접 만들지 않고
  entries의 category로 정확히 구분한다.
========================================================= */

function convertLegacyDiaryToLog(
  legacyItem,
  itemIndex,
  selectedDate,
  selectedShift
) {
  if (
    !legacyItem ||
    typeof legacyItem !==
      "object"
  ) {
    return null;
  }


  const bodyEntries =
    Array.isArray(
      legacyItem.body
    )
      ? legacyItem.body
      : [];


  const role =
    convertLegacyPositionToRole(
      legacyItem.position
    );


  const normalizedRole =
    normalizeMemberLogRole(
      role
    );


  const author =
    String(
      legacyItem.writer_name ||
      legacyItem.writerName ||
      legacyItem.writer_id ||
      "기존 업무일지"
    ).trim();


  const operationStatus =
    getLegacyBodyContent(
      bodyEntries,
      0
    );


  const legacyId =
    String(
      legacyItem.diary_id ||
      [
        selectedDate,
        selectedShift,
        role,
        itemIndex
      ].join("-")
    );


  const importedFromLogId =
    `legacy-${legacyId}`;


  /* =====================================================
    body index별 원문 확인
  ====================================================== */

  const getBodyContent = (
    targetIndex
  ) => {
    return getLegacyBodyContent(
      bodyEntries,
      targetIndex
    );
  };


  const index2Content =
    getBodyContent(
      2
    );


  const index3Content =
    getBodyContent(
      3
    );


  const index4Content =
    getBodyContent(
      4
    );


  const index5Content =
    getBodyContent(
      5
    );


  const index6Content =
    getBodyContent(
      6
    );


  const index7Content =
    getBodyContent(
      7
    );


  const index8Content =
    getBodyContent(
      8
    );


  const index9Content =
    getBodyContent(
      9
    );


  /* =====================================================
    파트장 자료 구조 판별

    현재 통합 구조 예:
    index 2 : 전체 운전 및 작업사항
    index 3 : 빈칸
    index 4 : 비고
    index 5~9 : 빈칸

    과거 보직별 구조 예:
    index 2~8에 각 보직별 업무가 저장됨
  ====================================================== */

  const hasLeaderRoleSeparatedContent =
    normalizedRole ===
      "파트장" &&
    Boolean(
      index3Content ||
      index5Content ||
      index6Content ||
      index7Content ||
      index8Content
    );


  const isLeaderCombinedStructure =
    normalizedRole ===
      "파트장" &&
    !hasLeaderRoleSeparatedContent &&
    Boolean(
      index2Content ||
      index4Content
    );


  /* =====================================================
    body index → category 판정
  ====================================================== */

  const getLegacyCategory = (
    bodyIndex
  ) => {
    const index =
      Number(
        bodyIndex
      );


    /*
      운전현황
    */
    if (
      index ===
      0
    ) {
      return "";
    }


    /*
      TM 발행 내역
    */
    if (
      index ===
      1
    ) {
      return "TM 발행";
    }


    /*
      일반 보직

      index 2 : 인계사항
      index 3 : 비고
    */
    if (
      normalizedRole !==
      "파트장"
    ) {
      if (
        index ===
        3
      ) {
        return "비고";
      }


      if (
        index ===
        2
      ) {
        return "인계사항";
      }


      /*
        예상하지 못한 추가 영역은
        데이터 유실 방지를 위해 인계사항으로 유지한다.
      */
      return "인계사항";
    }


    /*
      현재 파트장 통합 구조

      index 2 : 인계 및 작업 내역
      index 4 : 비고
    */
    if (
      isLeaderCombinedStructure
    ) {
      if (
        index ===
        4
      ) {
        return "비고";
      }


      if (
        index ===
        2
      ) {
        return "인계사항";
      }


      return "인계사항";
    }


    /*
      과거 파트장 보직별 구조

      index 2~8 : 보직별 업무
      index 9   : 비고가 존재하는 자료 호환
    */
    if (
      index ===
      9
    ) {
      return "비고";
    }


    return "인계사항";
  };


  /* =====================================================
    항목의 출처 보직 판정
  ====================================================== */

  const getLegacySourceRole = (
    bodyIndex,
    category
  ) => {
    const index =
      Number(
        bodyIndex
      );


    if (
      category ===
      "TM 발행"
    ) {
      return "";
    }


    if (
      category ===
      "비고"
    ) {
      return normalizedRole;
    }


    /*
      일반 보직의 업무는 본인 보직
    */
    if (
      normalizedRole !==
      "파트장"
    ) {
      return normalizedRole;
    }


    /*
      현재 파트장 통합 구조는
      파트장 업무일지 본문으로 처리한다.
    */
    if (
      isLeaderCombinedStructure
    ) {
      return "파트장";
    }


    /*
      과거 파트장 보직별 구조
    */
    return convertLegacyBodyIndexToRole(
      index,
      normalizedRole
    );
  };


  /* =====================================================
    변환 결과
  ====================================================== */

  const entries = [];


  bodyEntries.forEach(
    (
      bodyItem,
      bodyArrayIndex
    ) => {
      const bodyIndex =
        Number(
          bodyItem?.index ??
          bodyArrayIndex
        );


      const rawContent =
        String(
          bodyItem?.content ||
          ""
        );


      /*
        빈 영역과 운전현황 제외
      */
      if (
        !rawContent.trim() ||
        bodyIndex ===
        0
      ) {
        return;
      }


      const category =
        getLegacyCategory(
          bodyIndex
        );


      if (
        !category
      ) {
        return;
      }


      const sourceRole =
        getLegacySourceRole(
          bodyIndex,
          category
        );


      const parsedLines =
        parseLegacyDiaryContentLines(
          rawContent
        );


      parsedLines.forEach(
        (
          parsedLine,
          lineIndex
        ) => {
          const parsedContent =
            category ===
            "TM 발행"
              ? extractLegacyTagFromContent(
                  parsedLine.content
                )
              : {
                  tag:
                    "",

                  content:
                    parsedLine.content
                };


          const content =
            String(
              parsedContent.content ||
              ""
            ).trim();


          if (
            !content
          ) {
            return;
          }


          entries.push({
            id: [
              "legacy-entry",
              legacyId,
              bodyIndex,
              lineIndex
            ].join("-"),

            category,

            time:
              String(
                parsedLine.time ||
                ""
              ).trim(),

            tag:
              String(
                parsedContent.tag ||
                ""
              )
                .trim()
                .toUpperCase(),

            content,

            attachmentName:
              "",

            /*
              파트장 취합 및 상세보기의
              보직별 구분에 사용한다.
            */
            importedFromRole:
              sourceRole,

            importedFromAuthor:
              author,

            importedFromLogId,

            importedFromEntryIndex:
              lineIndex,

            legacyBodyIndex:
              bodyIndex,

            legacyLineIndex:
              lineIndex,

            source:
              category ===
                "비고"
                ? "legacy-remark"
                : "legacy"
          });
        }
      );
    }
  );


  /* =====================================================
    기존 note 문자열 호환

    비고 항목을 줄 단위 문자열로도 보관한다.
    새 화면에서는 entries의 category === 비고를 사용한다.
  ====================================================== */

  const remarkEntries =
    entries.filter(
      (
        entry
      ) => {
        return (
          String(
            entry.category ||
            ""
          ).trim() ===
          "비고"
        );
      }
    );


  const note =
    remarkEntries
      .map(
        (
          entry,
          remarkIndex
        ) => {
          const content =
            String(
              entry.content ||
              ""
            ).trim();


          return content
            ? `${remarkIndex + 1}. ${content}`
            : "";
        }
      )
      .filter(Boolean)
      .join("\n");


  return {
    id:
      importedFromLogId,

    date:
      selectedDate,

    shift:
      String(
        selectedShift ||
        ""
      )
        .trim()
        .toUpperCase(),

    role,

    author,

    writerId:
      String(
        legacyItem.writer_id ||
        ""
      ).trim(),

    team:
      getScheduledPart(
        selectedDate,
        selectedShift
      ),

    /*
      기존 GROUP_1, GROUP_2 값은
      현재 화면에서 사용하지 않는다.
    */
    group:
      "",

    operationStatus,

    /*
      기존 호환 단일 배열

      category 값으로 다음을 구분한다.
      - TM 발행
      - 인계사항
      - 비고
    */
    entries,

    /*
      기존 note 필드 호환
    */
    note,

    status:
      convertLegacyDiaryStatus(
        legacyItem.diary_status
      ),

    source:
      "legacy",

    legacyDiaryId:
      String(
        legacyItem.diary_id ||
        ""
      ),

    legacyPosition:
      String(
        legacyItem.position ||
        ""
      ),

    legacyVersion:
      legacyItem.version ??
      0,

    legacyStructure:
      normalizedRole !==
        "파트장"
        ? "member"
        : (
            isLeaderCombinedStructure
              ? "leader-combined"
              : "leader-role-separated"
          ),

    createdAt:
      legacyItem.created_at ||
      legacyItem.createdAt ||
      `${selectedDate}T00:00:00`,

    updatedAt:
      legacyItem.updated_at ||
      legacyItem.updatedAt ||
      `${selectedDate}T00:00:00`
  };
}

/* =========================================================
  기존 업무일지 내용 줄 분석 최종본

  핵심 규칙:
  - 번호가 있는 줄만 새로운 항목으로 시작한다.
  - 번호가 없는 줄은 바로 위 항목의 후속 내용으로 붙인다.
  - 14:10, 17:52 같은 시간은 번호로 인식하지 않는다.
  - 원본에 저장된 항목 순서를 그대로 유지한다.

  지원 번호:
  1. 내용
  2) 내용
  3 - 내용
  ① 내용

  지원하지 않는 번호:
  14: 내용

  이유:
  14:10 같은 시간을 항목 번호로 잘못 판단할 수 있기 때문이다.
========================================================= */

function parseLegacyDiaryContentLines(
  rawContent
) {
  const sourceLines =
    String(
      rawContent || ""
    )
      .replace(
        /\r\n/g,
        "\n"
      )
      .replace(
        /\r/g,
        "\n"
      )
      .split(
        "\n"
      );


  const parsedEntries = [];


  const numberedLinePattern =
    /^\s*(?:\d+\s*(?:[.)]|-\s+)\s*|[①②③④⑤⑥⑦⑧⑨⑩]\s*)(.*)$/;


  sourceLines.forEach(
    sourceLine => {
      /*
        과거 시스템의 유첨 안내문을
        줄 전체뿐 아니라 문장 끝에서도 제거한다.

        제거 예:
        유첨 : 제목
        ※ 유첨 : scaled_1
        업무내용 ※ 유첨 : scaled_2
        유첨 : scaled_2 [0000GH1A0A002]
      */
      const originalLine =
        String(
          sourceLine || ""
        )
          .replace(
            /\t/g,
            " "
          )
          .replace(
            /\s*\(?\s*(?:[-–—]\s*)?[※*＊•·]?\s*유첨\s*[:：]?\s*(?:제목|scaled(?:\s*[_-]?\s*\d+)?)\s*(?:\[[^\]\r\n]*\])?\s*\)?/gi,
            " "
          )
          .replace(
            / {2,}/g,
            " "
          )
          .trim();


      /*
        유첨 안내문을 제거한 뒤
        내용이 남지 않으면 제외한다.
      */
      if (
        !originalLine
      ) {
        return;
      }


      const numberedMatch =
        originalLine.match(
          numberedLinePattern
        );


      /*
        번호가 있는 줄
      */
      if (
        numberedMatch
      ) {
        const numberedContent =
          String(
            numberedMatch[1] ||
            ""
          ).trim();


        if (
          !numberedContent
        ) {
          return;
        }


        const parsedTimeExpression =
          parseLeadingLogTimeExpression(
            numberedContent
          );


        if (
          parsedTimeExpression.timeText &&
          parsedTimeExpression.content
        ) {
          parsedEntries.push({
            time:
              String(
                parsedTimeExpression.timeText ||
                ""
              ).trim(),

            content:
              String(
                parsedTimeExpression.content ||
                ""
              ).trim()
          });


          return;
        }


        parsedEntries.push({
          time:
            "",

          content:
            numberedContent
        });


        return;
      }


      /*
        번호가 없는 줄은
        바로 위 항목의 후속 내용으로 연결한다.
      */
      if (
        parsedEntries.length >
        0
      ) {
        const previousEntry =
          parsedEntries[
            parsedEntries.length - 1
          ];


        previousEntry.content = [
          String(
            previousEntry.content ||
            ""
          ).trim(),

          originalLine
        ]
          .filter(Boolean)
          .join("\n");


        return;
      }


      /*
        첫 줄부터 번호가 없는 자료
      */
      const parsedTimeExpression =
        parseLeadingLogTimeExpression(
          originalLine
        );


      if (
        parsedTimeExpression.timeText &&
        parsedTimeExpression.content
      ) {
        parsedEntries.push({
          time:
            String(
              parsedTimeExpression.timeText ||
              ""
            ).trim(),

          content:
            String(
              parsedTimeExpression.content ||
              ""
            ).trim()
        });


        return;
      }


      parsedEntries.push({
        time:
          "",

        content:
          originalLine
      });
    }
  );


  return parsedEntries.filter(
    entry => {
      return Boolean(
        String(
          entry.content ||
          ""
        ).trim()
      );
    }
  );
}
/* =========================================================
  기존 body index 내용 가져오기
========================================================= */

function getLegacyBodyContent(
  bodyEntries,
  targetIndex
) {
  const target =
    bodyEntries.find(
      (
        bodyItem,
        bodyIndex
      ) => {
        return (
          Number(
            bodyItem?.index ??
            bodyIndex
          ) ===
          Number(
            targetIndex
          )
        );
      }
    );

  return String(
    target?.content ||
    ""
  ).trim();
}


/* =========================================================
  기존 보직명을 현재 보직명으로 변환
========================================================= */

function convertLegacyPositionToRole(
  position
) {
  const normalizedPosition =
    String(
      position || ""
    )
      .trim()
      .toUpperCase();

  const roleMap = {
    GROUP_LEADER:
      "파트장",

    TGO:
      "TGO",

    BCO1:
      "BCO1",

    BCO2:
      "BCO2",

    TO:
      "TO",

    BO1:
      "BO1",

    BO2:
      "BO2"
  };

  return (
    roleMap[
      normalizedPosition
    ] ||
    normalizedPosition ||
    "미지정"
  );
}


/* =========================================================
  기존 결재 상태를 현재 상태로 변환
========================================================= */

function convertLegacyDiaryStatus(
  legacyStatus
) {
  const normalizedStatus =
    String(
      legacyStatus || ""
    )
      .trim()
      .toUpperCase();

  const statusMap = {
    /*
      파트장이 이미 승인한 과거 업무일지
    */
    APPROVED:
      "결재완료",

    /*
      결재 요청까지 마친 업무일지
    */
    SUBMITTED:
      "작성완료",

    REQUESTED:
      "작성완료",

    /*
      저장만 한 업무일지
    */
    DRAFT:
      "작성중",

    WRITING:
      "작성중",

    /*
      반려된 경우 다시 작성 중으로 처리
    */
    REJECTED:
      "작성중"
  };

  return (
    statusMap[
      normalizedStatus
    ] ||
    "작성중"
  );
}


