/* =========================================================
  조회용 업무일지 중복 제거

  우선순위:
  1. 업무일지 고유 ID
  2. 날짜 + 근무 + 보직 + 작성자 + 출처

  조회 기간의 과거 데이터를 다시 불러오더라도
  같은 업무일지가 두 번 표시되지 않게 한다.
========================================================= */

function removeDuplicateSearchLogs(
  logs
) {
  const sourceLogs =
    Array.isArray(
      logs
    )
      ? logs
      : [];


  const uniqueLogMap =
    new Map();


  sourceLogs.forEach(
    (
      log,
      logIndex
    ) => {
      if (
        !log ||
        typeof log !==
          "object"
      ) {
        return;
      }


      const logId =
        String(
          log.id ||
          ""
        ).trim();


      const uniqueKey =
        logId
          ? `ID||${logId}`
          : [
              "LOG",
              String(
                log.date ||
                ""
              ).trim(),
              String(
                log.shift ||
                ""
              ).trim(),
              normalizeMemberLogRole(
                log.role
              ),
              String(
                log.author ||
                ""
              ).trim(),
              String(
                log.source ||
                ""
              ).trim(),
              logIndex
            ].join("||");


      /*
        동일한 ID가 다시 들어오면
        마지막으로 불러온 데이터를 사용한다.
      */
      uniqueLogMap.set(
        uniqueKey,
        log
      );
    }
  );


  return [
    ...uniqueLogMap.values()
  ];
}

/* =========================================================
  조회 결과에 표시 중인 업무일지

  과거 조회 데이터는 appState.logs에 없을 수 있으므로
  조회 결과 배열 자체를 별도로 보관한다.
========================================================= */

let currentSearchResultLogs = [];


/* =========================================================
  업무일지 전체 검색 문자열 생성

  검색 대상:
  - 날짜
  - 근무
  - 보직
  - 작성자
  - 운전현황
  - TM·인계사항의 구분
  - 시간
  - TAG
  - 업무내용
  - 비고
========================================================= */

function createSearchLogText(
  log
) {
  const entries =
    Array.isArray(
      log?.entries
    )
      ? log.entries
      : [];


  const entryText =
    entries
      .map(
        (entry) => {
          return [
            entry?.category,
            entry?.time,
            entry?.tag,
            entry?.content
          ]
            .filter(Boolean)
            .join(" ");
        }
      )
      .join(" ");


  return [
    log?.date,
    log?.shift,
    log?.team,
    log?.role,
    log?.author,
    log?.status,
    log?.operationStatus,
    entryText,
    log?.note
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}


/* =========================================================
  조회 구분 정규화

  HTML select 값:
  operation
  tm
  bm
  cm
  handover
  note
========================================================= */

function getSearchEntryCategoryValue(
  entry
) {
  const category =
    String(
      entry?.category ||
      ""
    )
      .trim()
      .toUpperCase();


  if (
    category.startsWith(
      "TM"
    )
  ) {
    return "tm";
  }


  if (
    category.startsWith(
      "BM"
    )
  ) {
    return "bm";
  }


  if (
    category.startsWith(
      "CM"
    )
  ) {
    return "cm";
  }


  if (
    category ===
      "인계사항" ||
    category ===
      "인계 사항"
  ) {
    return "handover";
  }


  if (
    category ===
    "비고"
  ) {
    return "note";
  }


  return "";
}


/* =========================================================
  선택한 구분이 업무일지에 존재하는지 확인
========================================================= */

function doesLogMatchSearchCategory(
  log,
  selectedCategory
) {
  const category =
    String(
      selectedCategory ||
      ""
    ).trim();


  /*
    전체
  */
  if (!category) {
    return true;
  }


  /*
    운전현황
  */
  if (
    category ===
    "operation"
  ) {
    return Boolean(
      String(
        log?.operationStatus ||
        ""
      ).trim()
    );
  }


  /*
    비고
  */
  if (
    category ===
    "note"
  ) {
    const hasLogNote =
      Boolean(
        String(
          log?.note ||
          ""
        ).trim()
      );


    const hasNoteEntry =
      Array.isArray(
        log?.entries
      ) &&
      log.entries.some(
        (entry) => {
          return (
            getSearchEntryCategoryValue(
              entry
            ) ===
            "note"
          );
        }
      );


    return (
      hasLogNote ||
      hasNoteEntry
    );
  }


  const entries =
    Array.isArray(
      log?.entries
    )
      ? log.entries
      : [];


  return entries.some(
    (entry) => {
      return (
        getSearchEntryCategoryValue(
          entry
        ) ===
        category
      );
    }
  );
}

/* =========================================================
  조회 목록 업무내용 미리보기

  출력 규칙
  1. 일반 보직은 운전현황을 표시하지 않음
  2. 파트장은 운전현황 전체 줄 표시
  3. 번호 → 시간 → 내용 → TAG
  4. TAG는 내용 뒤에 한 번만 표시
  5. 과거 content 앞의 중복 TAG 제거
  6. 조회 버튼 안에 button을 중첩하지 않음
  7. 파트장 일지는 보직별로 분리
========================================================= */

function createSearchLogPreviewHtml(log) {
  /*
    조회 미리보기를 별도로 만들지 않고
    메인 업무일지 목록의 미리보기 HTML을 그대로 사용한다.

    따라서:
    - 운전현황
    - TM 발행 내역
    - 인계 사항
    - 보직별 업무일지
    - 비고
    - 번호·시간·내용·TAG

    구조가 메인 목록과 항상 동일해진다.
  */
  const rowHtml =
    createLogRowHtml(
      log
    );

  const template =
    document.createElement(
      "template"
    );

  /*
    createLogRowHtml() 결과가 tr이므로
    table > tbody 안에서 안전하게 분석한다.
  */
  template.innerHTML = `
    <table>
      <tbody>
        ${rowHtml}
      </tbody>
    </table>
  `;

  const mainPreview =
    template.content.querySelector(
      ".log-preview"
    );

  if (
    !mainPreview
  ) {
    return `
      <span class="log-preview__empty">
        등록된 업무 내용이 없습니다.
      </span>
    `;
  }

  /*
    조회 화면의 TAG 클릭 기능 유지
  */
  mainPreview
    .querySelectorAll(
      ".log-preview__tag"
    )
    .forEach(
      tagElement => {
        const tag =
          String(
            tagElement.textContent ||
            ""
          )
            .trim()
            .replace(
              /^[\[【]\s*/,
              ""
            )
            .replace(
              /\s*[\]】]$/,
              ""
            )
            .trim()
            .toUpperCase();

        if (
          !tag
        ) {
          return;
        }

        tagElement.dataset.searchTag =
          tag;

        tagElement.setAttribute(
          "role",
          "button"
        );

        tagElement.setAttribute(
          "tabindex",
          "0"
        );

        tagElement.setAttribute(
          "title",
          "Facility Navigator에서 설비 보기"
        );
      }
    );

  /*
    메인 목록의 button 자체는 복사하지 않고
    내부 미리보기 구조만 사용한다.

    행·업무내용 클릭은 기존
    renderSearchResults()가 처리한다.
  */
  return `
    <span
      class="
        log-preview
        search-result-log-preview
      "
    >
      ${mainPreview.innerHTML}
    </span>
  `;
}

/* =========================================================
  첨부파일 개수
========================================================= */

function getSearchLogAttachmentCount(
  log
) {
  if (
    Array.isArray(
      log?.attachments
    )
  ) {
    return log.attachments.length;
  }


  return 0;
}


/* =========================================================
  상태 배지 클래스
========================================================= */

function getSearchLogStatusClass(
  status
) {
  const normalizedStatus =
    String(
      status ||
      ""
    ).trim();


  if (
    normalizedStatus ===
      "결재완료" ||
    normalizedStatus ===
      "승인완료"
  ) {
    return "is-approved";
  }


  if (
    normalizedStatus ===
      "작성완료" ||
    normalizedStatus ===
      "저장완료"
  ) {
    return "is-saved";
  }


  return "is-writing";
}


/* =========================================================
  업무일지 조회 실행

  결과 단위:
  업무 항목 1건이 아니라
  업무일지 1건
========================================================= */

async function runSearch() {
  if (
    !elements.searchForm
  ) {
    return;
  }


  const formData =
    new FormData(
      elements.searchForm
    );


  const startDate =
    String(
      formData.get(
        "startDate"
      ) ||
      ""
    ).trim();


  const endDate =
    String(
      formData.get(
        "endDate"
      ) ||
      ""
    ).trim();


  const shift =
    String(
      formData.get(
        "shift"
      ) ||
      ""
    )
      .trim()
      .toUpperCase();


  const role =
    normalizeMemberLogRole(
      formData.get(
        "role"
      )
    );


  const category =
    String(
      formData.get(
        "category"
      ) ||
      ""
    ).trim();


  const keyword =
    String(
      formData.get(
        "keyword"
      ) ||
      ""
    )
      .trim()
      .toLowerCase();


/* =====================================================
  조회 기간 검사

  최대:
  시작일 기준 달력 6개월
====================================================== */

if (
  !startDate ||
  !endDate
) {
  showToast(
    "조회 시작일과 종료일을 선택해 주세요."
  );


  return;
}


if (
  startDate >
  endDate
) {
  showToast(
    "종료일은 시작일보다 빠를 수 없습니다."
  );


  return;
}


const maximumEndDate =
  getSearchMaximumEndDate(
    startDate
  );


if (
  !maximumEndDate
) {
  showToast(
    "조회 시작일을 확인해 주세요."
  );


  return;
}


if (
  endDate >
  maximumEndDate
) {
  showToast(
    `조회 기간은 최대 6개월까지 선택할 수 있습니다. 최대 종료일은 ${maximumEndDate}입니다.`
  );


  return;
}


const searchDates =
  createSearchDateRange(
    startDate,
    endDate
  );


if (
  !searchDates.length
) {
  showToast(
    "조회 기간을 확인해 주세요."
  );


  return;
}

  const submitButton =
    elements.searchForm
      .querySelector(
        'button[type="submit"]'
      );


  const originalButtonText =
    submitButton?.textContent ||
    "조회";


  if (
    submitButton
  ) {
    submitButton.disabled =
      true;

    submitButton.textContent =
      "조회 중...";
  }


  if (
    elements.searchResultBody
  ) {
    elements.searchResultBody
      .innerHTML =
      "";
  }


  if (
    elements.searchResultCount
  ) {
    elements.searchResultCount
      .textContent =
      "0";
  }


  if (
    elements.searchEmptyState
  ) {
    elements.searchEmptyState.hidden =
      false;


    const loadingTitle =
      elements.searchEmptyState
        .querySelector(
          "strong"
        );


    const loadingDescription =
      elements.searchEmptyState
        .querySelector(
          "p"
        );


    if (
      loadingTitle
    ) {
      loadingTitle.textContent =
        "과거 업무일지를 불러오는 중입니다.";
    }


    if (
      loadingDescription
    ) {
      loadingDescription.textContent =
        "선택한 기간의 업무일지를 확인하고 있습니다.";
    }
  }


  try {
    /*
      조회 기간의 과거 업무일지를 모두 불러온다.
    */
    const legacySearchLogs =
      await loadLegacyLogsForSearchRange(
        startDate,
        endDate
      );


    /*
      신규 업무일지와 과거 업무일지를 합친다.
    */
    const combinedLogs =
      removeDuplicateSearchLogs([
        ...appState.logs,
        ...legacySearchLogs
      ]);


    const matchedLogs =
      combinedLogs.filter(
        (log) => {
          const logDate =
            String(
              log?.date ||
              ""
            ).trim();


          const logShift =
            String(
              log?.shift ||
              ""
            )
              .trim()
              .toUpperCase();


          const logRole =
            normalizeMemberLogRole(
              log?.role
            );


          /*
            날짜
          */
          if (
            logDate <
              startDate ||
            logDate >
              endDate
          ) {
            return false;
          }


          /*
            근무
          */
          if (
            shift &&
            logShift !==
              shift
          ) {
            return false;
          }


          /*
            보직
          */
          if (
            role &&
            logRole !==
              role
          ) {
            return false;
          }


          /*
            구분
          */
          if (
            !doesLogMatchSearchCategory(
              log,
              category
            )
          ) {
            return false;
          }


          /*
            검색어

            검색어와 일치하는 항목이 하나라도 있으면
            업무일지 전체를 결과에 표시한다.
          */
          if (
            keyword
          ) {
            const searchableText =
              createSearchLogText(
                log
              );


            if (
              !searchableText.includes(
                keyword
              )
            ) {
              return false;
            }
          }


          return true;
        }
      );


    /*
      최신 날짜 우선

      같은 날짜:
      D/S → N/S

      같은 근무:
      파트장 → TGO → BCO1 → BCO2 → TO → BO1 → BO2
    */
    const roleOrder = {
      파트장:
        1,

      TGO:
        2,

      BCO1:
        3,

      BCO2:
        4,

      TO:
        5,

      BO1:
        6,

      BO2:
        7
    };


    matchedLogs.sort(
      (
        logA,
        logB
      ) => {
        const dateDifference =
          String(
            logB.date ||
            ""
          ).localeCompare(
            String(
              logA.date ||
              ""
            )
          );


        if (
          dateDifference !==
          0
        ) {
          return dateDifference;
        }


        const shiftOrder = {
          DS:
            1,

          NS:
            2
        };


        const shiftDifference =
          (
            shiftOrder[
              String(
                logA.shift ||
                ""
              ).toUpperCase()
            ] ||
            99
          ) -
          (
            shiftOrder[
              String(
                logB.shift ||
                ""
              ).toUpperCase()
            ] ||
            99
          );


        if (
          shiftDifference !==
          0
        ) {
          return shiftDifference;
        }


        return (
          roleOrder[
            normalizeMemberLogRole(
              logA.role
            )
          ] ||
          99
        ) -
        (
          roleOrder[
            normalizeMemberLogRole(
              logB.role
            )
          ] ||
          99
        );
      }
    );


    renderSearchResults(
      matchedLogs
    );

  } catch (error) {
    console.error(
      "업무일지 조회 실패:",
      error
    );


    currentSearchResultLogs =
      [];


    if (
      elements.searchResultBody
    ) {
      elements.searchResultBody
        .innerHTML =
        "";
    }


    if (
      elements.searchResultCount
    ) {
      elements.searchResultCount
        .textContent =
        "0";
    }


    if (
      elements.searchEmptyState
    ) {
      elements.searchEmptyState.hidden =
        false;


      const errorTitle =
        elements.searchEmptyState
          .querySelector(
            "strong"
          );


      const errorDescription =
        elements.searchEmptyState
          .querySelector(
            "p"
          );


      if (
        errorTitle
      ) {
        errorTitle.textContent =
          "업무일지를 불러오지 못했습니다.";
      }


      if (
        errorDescription
      ) {
        errorDescription.textContent =
          error.message ||
          "잠시 후 다시 조회해 주세요.";
      }
    }


    showToast(
      error.message ||
      "업무일지 조회 중 오류가 발생했습니다."
    );

  } finally {
    if (
      submitButton
    ) {
      submitButton.disabled =
        false;

      submitButton.textContent =
        originalButtonText;
    }
  }
}

/* =========================================================
  조회 결과 ID로 업무일지 찾기

  조회 기간에서 불러온 과거 업무일지는
  appState.logs에 존재하지 않을 수 있다.

  따라서 조회 전용 배열을 먼저 확인한다.
========================================================= */

function findSearchResultLogById(
  logId
) {
  const normalizedLogId =
    String(
      logId ||
      ""
    ).trim();


  if (
    !normalizedLogId
  ) {
    return null;
  }


  const searchLogs =
    Array.isArray(
      currentSearchResultLogs
    )
      ? currentSearchResultLogs
      : [];


  return (
    searchLogs.find(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          normalizedLogId
        );
      }
    ) ||

    appState.logs.find(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          normalizedLogId
        );
      }
    ) ||

    null
  );
}

/* =========================================================
  모바일 조회 결과 카드 1개

  구성:
  - 날짜·근무
  - 보직·작성자
  - 상태
  - 업무 미리보기
  - 첨부 개수
  - 상세보기

  조회 화면에서는 수정 버튼을 표시하지 않는다.
========================================================= */

function createMobileSearchCardHtml(
  log
) {
  const previewText =
    typeof createSearchLogPreviewText ===
      "function"
      ? createSearchLogPreviewText(
          log
        )
      : firstMeaningfulLine(
          typeof createSearchLogText ===
            "function"
            ? createSearchLogText(
                log
              )
            : ""
        );


  const attachmentCount =
    Array.isArray(
      log?.attachments
    )
      ? log.attachments.length
      : Number(
          log?.legacyAttachmentCount ||
          0
        );


  const statusText =
    typeof getMobileLogStatusDisplay ===
      "function"
      ? getMobileLogStatusDisplay(
          log?.status
        )
      : String(
          log?.status ||
          "미작성"
        ).trim();


  const statusClass =
    typeof getStatusClass ===
      "function"
      ? getStatusClass(
          log?.status
        )
      : "is-empty";


  return `
    <article
      class="mobile-search-card"
      data-search-log-id="${escapeHtml(
        log.id
      )}"
    >

      <button
        type="button"
        class="mobile-search-card__open"
        data-search-view="${escapeHtml(
          log.id
        )}"
        aria-label="${escapeHtml(
          log.date ||
          ""
        )} ${escapeHtml(
          log.role ||
          ""
        )} 업무일지 상세보기"
      >

        <!-- 날짜·근무 -->
        <div class="mobile-search-card__date-row">

          <strong>
            ${escapeHtml(
              log.date ||
              "-"
            )}
          </strong>

          <span class="mobile-search-card__shift">
            ${escapeHtml(
              getShiftDisplayName(
                log.shift
              )
            )}
          </span>

        </div>


        <!-- 보직·작성자·상태 -->
        <header class="mobile-search-card__header">

          <div class="mobile-search-card__identity">

            <strong class="mobile-search-card__role">
              ${escapeHtml(
                log.role ||
                "-"
              )}
            </strong>

            <span class="mobile-search-card__author">
              ${escapeHtml(
                log.author ||
                "-"
              )}
            </span>

            ${
              log.isSubstitute ===
                true
                ? `
                  <span class="mobile-search-card__substitute">
                    대근
                  </span>
                `
                : ""
            }

          </div>


          <span
            class="
              status-badge
              mobile-search-card__status
              ${statusClass}
            "
          >
            ${escapeHtml(
              statusText
            )}
          </span>

        </header>


        <!-- 업무내용 미리보기 -->
        <div class="mobile-search-card__content">

          <span class="mobile-search-card__content-label">
            업무 내용
          </span>

          <p>
            ${escapeHtml(
              previewText ||
              "등록된 업무 내용이 없습니다."
            )}
          </p>

        </div>

      </button>


      <!-- 하단 -->
      <footer class="mobile-search-card__footer">

        <span class="mobile-search-card__attachment">

          <span aria-hidden="true">
            📎
          </span>

          ${
            attachmentCount >
              0
              ? `첨부 ${attachmentCount}개`
              : "첨부 없음"
          }

        </span>


        <button
          type="button"
          class="mobile-search-card__detail-button"
          data-search-view="${escapeHtml(
            log.id
          )}"
        >
          상세보기
          <span aria-hidden="true">
            ›
          </span>
        </button>

      </footer>

    </article>
  `;
}

/* =========================================================
  조회 결과 ID로 업무일지 찾기

  조회 기간에서 불러온 과거 업무일지는
  appState.logs에 존재하지 않을 수 있다.

  조회 전용 배열을 먼저 확인하고,
  없으면 현재 업무일지 배열에서 다시 찾는다.
========================================================= */

function findSearchResultLogById(
  logId
) {
  const normalizedLogId =
    String(
      logId ||
      ""
    ).trim();


  if (
    !normalizedLogId
  ) {
    return null;
  }


  const searchResultLogs =
    Array.isArray(
      currentSearchResultLogs
    )
      ? currentSearchResultLogs
      : [];


  const currentLogs =
    Array.isArray(
      appState.logs
    )
      ? appState.logs
      : [];


  return (
    searchResultLogs.find(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          normalizedLogId
        );
      }
    ) ||

    currentLogs.find(
      log => {
        return (
          String(
            log?.id ||
            ""
          ).trim() ===
          normalizedLogId
        );
      }
    ) ||

    null
  );
}

/* =========================================================
  조회 결과 출력 최종본

  PC:
  기존 표 출력

  모바일:
  전용 카드 출력

  공통:
  currentSearchResultLogs에 결과를 저장하여
  조회 기간에서 새로 불러온 과거 업무일지도
  상세보기가 가능하게 한다.
========================================================= */

function renderSearchResults(
  results
) {
  if (
    !elements.searchResultBody ||
    !elements.searchResultCount ||
    !elements.searchEmptyState
  ) {
    return;
  }


  const safeResults =
    Array.isArray(
      results
    )
      ? results.filter(
          log => {
            return Boolean(
              log &&
              log.id
            );
          }
        )
      : [];


  /*
    조회 전용 결과 보관
  */
  currentSearchResultLogs = [
    ...safeResults
  ];


  /*
    PC 표 초기화
  */
  elements.searchResultBody.innerHTML =
    "";


  /*
    모바일 카드 초기화
  */
  if (
    elements.mobileSearchCardList
  ) {
    elements.mobileSearchCardList
      .innerHTML =
      "";
  }


  elements.searchResultCount.textContent =
    String(
      safeResults.length
    );


  elements.searchEmptyState.hidden =
    safeResults.length >
    0;


  if (
    !safeResults.length
  ) {
    const emptyTitle =
      elements.searchEmptyState
        .querySelector(
          "strong"
        );


    const emptyDescription =
      elements.searchEmptyState
        .querySelector(
          "p"
        );


    if (
      emptyTitle
    ) {
      emptyTitle.textContent =
        "조회 결과가 없습니다.";
    }


    if (
      emptyDescription
    ) {
      emptyDescription.textContent =
        "검색 조건을 변경하여 다시 조회해 주세요.";
    }


    return;
  }


  /* =====================================================
    PC 조회 표
  ====================================================== */

  safeResults.forEach(
    log => {
      const previewText =
        typeof createSearchLogPreviewText ===
          "function"
          ? createSearchLogPreviewText(
              log
            )
          : firstMeaningfulLine(
              typeof createSearchLogText ===
                "function"
                ? createSearchLogText(
                    log
                  )
                : ""
            );


      const attachmentCount =
        Array.isArray(
          log.attachments
        )
          ? log.attachments.length
          : Number(
              log.legacyAttachmentCount ||
              0
            );


      elements.searchResultBody
        .insertAdjacentHTML(
          "beforeend",
          `
            <tr
              data-search-log-id="${escapeHtml(
                log.id
              )}"
              tabindex="0"
              role="button"
              title="업무일지 상세보기"
            >

              <td class="search-log-date-cell">
                ${escapeHtml(
                  log.date ||
                  "-"
                )}
              </td>


              <td class="search-log-shift-cell">
                ${escapeHtml(
                  getShiftDisplayName(
                    log.shift
                  )
                )}
              </td>


              <td class="search-log-role-cell">
                ${escapeHtml(
                  log.role ||
                  "-"
                )}
              </td>


              <td class="search-log-author-cell">

                <strong>
                  ${escapeHtml(
                    log.author ||
                    "-"
                  )}
                </strong>

              </td>


              <td
                class="search-log-preview-cell"
                data-search-view="${escapeHtml(
                  log.id
                )}"
              >
                ${
                  typeof createSearchLogPreviewHtml ===
                    "function"
                    ? createSearchLogPreviewHtml(
                        log
                      )
                    : escapeHtml(
                        previewText ||
                        "등록된 업무 내용이 없습니다."
                      )
                }
              </td>


              <td class="search-log-attachment-cell">

                ${
                  attachmentCount >
                    0
                    ? `
                      <span
                        class="attachment-indicator"
                        title="첨부파일 ${attachmentCount}개"
                      >
                        📎
                      </span>
                    `
                    : `
                      <span
                        class="
                          attachment-indicator
                          is-empty
                        "
                      >
                        -
                      </span>
                    `
                }

              </td>

            </tr>
          `
        );
    }
  );


  /* =====================================================
    모바일 조회 카드
  ====================================================== */

  if (
    elements.mobileSearchCardList
  ) {
    elements.mobileSearchCardList
      .innerHTML =
      safeResults
        .map(
          log => {
            return createMobileSearchCardHtml(
              log
            );
          }
        )
        .join("");
  }


  bindSearchResultEvents();
}

/* =========================================================
  조회 결과 공통 이벤트

  지원 대상:
  - PC 표
  - 모바일 카드

  TAG 클릭:
  Facility Navigator 이동

  카드·행·상세보기 클릭:
  업무일지 상세창 열기
========================================================= */

function bindSearchResultEvents() {
  const resultContainers = [
    elements.searchResultBody,
    elements.mobileSearchCardList
  ].filter(
    Boolean
  );


  resultContainers.forEach(
    container => {
      container.onclick =
        function handleSearchResultClick(
          event
        ) {
          const tagButton =
            event.target.closest(
              "[data-search-tag]"
            );


          if (
            tagButton &&
            container.contains(
              tagButton
            )
          ) {
            event.preventDefault();

            event.stopPropagation();


            openFacilityNavigator(
              tagButton.dataset
                .searchTag
            );


            return;
          }


          const clickedElement =
            event.target.closest(
              `
                [data-search-view],
                [data-search-log-id]
              `
            );


          if (
            !clickedElement ||
            !container.contains(
              clickedElement
            )
          ) {
            return;
          }


          const cardOrRow =
            clickedElement.closest(
              "[data-search-log-id]"
            );


          const logId =
            String(
              clickedElement.dataset
                .searchView ||
              cardOrRow?.dataset
                .searchLogId ||
              ""
            ).trim();


          const log =
            findSearchResultLogById(
              logId
            );


          if (
            !log
          ) {
            showToast(
              "조회한 업무일지를 찾을 수 없습니다."
            );

            return;
          }


          openLogDetail(
            log
          );
        };


      container.onkeydown =
        function handleSearchResultKeydown(
          event
        ) {
          if (
            event.key !==
              "Enter" &&
            event.key !==
              " "
          ) {
            return;
          }


          const target =
            event.target.closest(
              "[data-search-log-id]"
            );


          if (
            !target ||
            !container.contains(
              target
            )
          ) {
            return;
          }


          event.preventDefault();


          const log =
            findSearchResultLogById(
              target.dataset
                .searchLogId
            );


          if (
            !log
          ) {
            showToast(
              "조회한 업무일지를 찾을 수 없습니다."
            );

            return;
          }


          openLogDetail(
            log
          );
        };
    }
  );
}

function matchesKeyword(text, keyword) {
  if (!text) {
    return false;
  }

  if (!keyword) {
    return true;
  }

  return String(text).toLowerCase().includes(keyword);
}


/* =========================================================
  모달 / 토스트
========================================================= */
function openModal(modalElement) {
  modalElement.classList.add("is-open");
  modalElement.setAttribute("aria-hidden", "false");
  document.body.classList.add("modal-open");
}


function closeModal(modalElement) {
  modalElement.classList.remove("is-open");
  modalElement.setAttribute("aria-hidden", "true");

  const anyOpenModal = document.querySelector(
    ".modal-backdrop.is-open"
  );

  if (!anyOpenModal) {
    document.body.classList.remove("modal-open");
  }
}


let toastTimer = null;

/* =========================================================
  화면 중앙 안내 메시지

  사용 예시:
  showToast(
    "저장이 되었습니다.",
    1600
  );

  동작:
  - 화면 정중앙 표시
  - 기본 1.6초 유지
  - 부드럽게 나타났다가 사라짐
  - 여러 번 실행되면 기존 문구 제거 후 새 문구 표시
========================================================= */

function showToast(
  message,
  duration = 1600
) {
  /*
    기존 중앙 안내가 남아 있으면 제거한다.
  */
  document
    .querySelectorAll(
      ".center-toast"
    )
    .forEach(
      (toast) => {
        toast.remove();
      }
    );


  const toast =
    document.createElement(
      "div"
    );


  toast.className =
    "center-toast";


  toast.setAttribute(
    "role",
    "status"
  );


  toast.setAttribute(
    "aria-live",
    "polite"
  );


  toast.innerHTML = `
    <div class="center-toast__content">
      <span
        class="center-toast__icon"
        aria-hidden="true"
      >
        ✓
      </span>

      <span class="center-toast__message">
        ${escapeHtml(
          String(
            message ||
            ""
          )
        )}
      </span>
    </div>
  `;


  document.body.appendChild(
    toast
  );


  /*
    DOM 추가 후 표시 애니메이션 실행
  */
  window.requestAnimationFrame(
    () => {
      window.requestAnimationFrame(
        () => {
          toast.classList.add(
            "is-visible"
          );
        }
      );
    }
  );


  /*
    지정 시간 후 사라지게 한다.
  */
  window.setTimeout(
    () => {
      toast.classList.remove(
        "is-visible"
      );


      toast.classList.add(
        "is-hiding"
      );


      window.setTimeout(
        () => {
          toast.remove();
        },
        220
      );
    },
    Math.max(
      1000,
      Number(
        duration
      ) ||
      1600
    )
  );
}


/* =========================================================
  공통
========================================================= */
function firstMeaningfulLine(text) {
  return String(text || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .find(Boolean) || "";
}


function getMainCategory(category) {
  const value = String(category || "");

  if (value.startsWith("TM")) {
    return "TM";
  }

  if (value.startsWith("BM")) {
    return "BM";
  }

  if (value.startsWith("CM")) {
    return "CM";
  }

  if (value === "인계사항") {
    return "인계사항";
  }

  return "비고";
}

/* =========================================================
  업무일지 구분 통합 판정

  발행:
  - TM 발행
  - BM 발행
  - CM 발행

  작업:
  - TM 작업
  - BM 작업
  - CM 작업
========================================================= */

const LOG_ENTRY_ISSUE_CATEGORIES =
  new Set([
    "TM 발행",
    "BM 발행",
    "CM 발행"
  ]);


const LOG_ENTRY_WORK_CATEGORIES =
  new Set([
    "TM 작업",
    "BM 작업",
    "CM 작업"
  ]);


/* =========================================================
  구분명 정규화

  과거 종결 자료:
  - TM 종결 → TM 작업
  - BM 종결 → BM 작업
  - CM 종결 → CM 작업

  기존 일반 구분:
  - 운전조작·점검 → 인계사항
========================================================= */

function normalizeLogEntryCategory(
  value
) {
  const rawCategory =
    String(
      value ||
      "인계사항"
    ).trim();


  const compactCategory =
    rawCategory
      .toUpperCase()
      .replace(
        /\s+/g,
        ""
      );


  if (
    !compactCategory ||
    compactCategory ===
      "인계사항" ||
    compactCategory ===
      "인계"
  ) {
    return "인계사항";
  }


  if (
    compactCategory.includes(
      "비고"
    )
  ) {
    return "비고";
  }


  if (
    compactCategory.startsWith(
      "TM발행"
    )
  ) {
    return "TM 발행";
  }


  if (
    compactCategory.startsWith(
      "TM작업"
    ) ||
    compactCategory.startsWith(
      "TM종결"
    )
  ) {
    return "TM 작업";
  }


  if (
    compactCategory.startsWith(
      "BM발행"
    )
  ) {
    return "BM 발행";
  }


  if (
    compactCategory.startsWith(
      "BM작업"
    ) ||
    compactCategory.startsWith(
      "BM종결"
    )
  ) {
    return "BM 작업";
  }


  if (
    compactCategory.startsWith(
      "CM발행"
    )
  ) {
    return "CM 발행";
  }


  if (
    compactCategory.startsWith(
      "CM작업"
    ) ||
    compactCategory.startsWith(
      "CM종결"
    )
  ) {
    return "CM 작업";
  }


  return "인계사항";
}


/* =========================================================
  발행 항목 여부
========================================================= */

function isIssueLogEntryCategory(
  value
) {
  return LOG_ENTRY_ISSUE_CATEGORIES.has(
    normalizeLogEntryCategory(
      value
    )
  );
}


/* =========================================================
  작업 항목 여부
========================================================= */

function isWorkLogEntryCategory(
  value
) {
  return LOG_ENTRY_WORK_CATEGORIES.has(
    normalizeLogEntryCategory(
      value
    )
  );
}

function createId() {
  if (window.crypto?.randomUUID) {
    return window.crypto.randomUUID();
  }

  return `log-${Date.now()}-${Math.random()
    .toString(16)
    .slice(2)}`;
}


function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}


