const efficiencyDailyWorkPrintBoundButtons =
  new WeakSet();

const efficiencyDailyWorkPrintBoundForms =
  new WeakSet();

const efficiencyDailyWorkPrintingWindows =
  new WeakSet();

let efficiencyDailyWorkPrintOpening =
  false;

let efficiencyDailyWorkPrintWindowSequence =
  0;

/* =========================================================
  인쇄 오류 및 A4 초과 표시
========================================================= */

function showEfficiencyDailyWorkPrintError(
  message
) {
  const elements =
    getEfficiencyDailyWorkElements();

  if (elements.messageElement) {
    elements.messageElement.textContent =
      "";
  }

  showEfficiencyDailyWorkEditorError(
    message
  );

  if (elements.errorElement) {
    elements.errorElement.dataset
      .efficiencyDailyWorkErrorSource =
      "print";
  }
}

function clearEfficiencyDailyWorkPrintError() {
  const elements =
    getEfficiencyDailyWorkElements();

  if (
    elements.errorElement?.dataset
      .efficiencyDailyWorkErrorSource !==
    "print"
  ) {
    return false;
  }

  elements.errorElement.textContent =
    "";

  elements.errorElement.hidden =
    true;

  delete elements.errorElement.dataset
    .efficiencyDailyWorkErrorSource;

  return true;
}

function refreshEfficiencyDailyWorkPageOverflowState() {
  const elements =
    getEfficiencyDailyWorkElements();

  if (!elements.paper) {
    return false;
  }

  const overflowingTextarea = [
    ...elements.paper.querySelectorAll(
      "textarea"
    )
  ].some(
    control => {
      return (
        control.scrollHeight >
          control.clientHeight + 2 ||
        control.scrollWidth >
          control.clientWidth + 2
      );
    }
  );

  const overflowingPaper =
    elements.paper.scrollHeight >
      elements.paper.clientHeight + 2 ||
    elements.paper.scrollWidth >
      elements.paper.clientWidth + 2;

  const hasOverflow =
    overflowingTextarea ||
    overflowingPaper;

  elements.paper.classList.toggle(
    "is-overflowing",
    hasOverflow
  );

  if (elements.overflowWarning) {
    elements.overflowWarning.hidden =
      !hasOverflow;
  }

  return hasOverflow;
}

/* =========================================================
  현재 인쇄 대상 확인
========================================================= */

function createEfficiencyDailyWorkPrintContext() {
  if (
    efficiencyDailyWorkState.isLoading ||
    efficiencyDailyWorkState.isSaving ||
    efficiencyDailyWorkDateTransitionPending
  ) {
    throw new Error(
      "현재 기록 처리가 끝난 뒤 다시 시도해주세요."
    );
  }

  const elements =
    getEfficiencyDailyWorkElements();

  const workDate =
    normalizeEfficiencyDailyWorkDateValue(
      elements.dateInput?.value
    );

  const selectedDate =
    normalizeEfficiencyDailyWorkDateValue(
      efficiencyDailyWorkState.selectedDate
    );

  if (!elements.paper) {
    throw new Error(
      "인쇄할 일일업무현황 양식을 찾을 수 없습니다."
    );
  }

  if (!workDate) {
    throw new Error(
      "작성일을 올바르게 선택해주세요."
    );
  }

  if (
    selectedDate &&
    selectedDate !== workDate
  ) {
    throw new Error(
      "현재 기록과 작성일 정보가 일치하지 않습니다. 날짜 이동을 마친 뒤 다시 시도해주세요."
    );
  }

  return {
    elements,

    workDate,

    formattedDate:
      formatEfficiencyDailyWorkDisplayDate(
        workDate
      ) ||
      workDate,

    hasOverflow:
      refreshEfficiencyDailyWorkPageOverflowState()
  };
}

/* =========================================================
  입력 요소를 정적 출력값으로 변환
========================================================= */

function staticizeEfficiencyDailyWorkControl(
  sourceControl,
  clonedControl,
  targetDocument
) {
  const type =
    String(
      sourceControl.type ||
      ""
    ).toLowerCase();

  if (type === "hidden") {
    clonedControl.remove();

    return;
  }

  if (
    type === "checkbox" ||
    type === "radio"
  ) {
    const visual =
      clonedControl.nextElementSibling;

    if (
      visual?.classList.contains(
        "efficiency-daily-work-generation-check__box"
      )
    ) {
      visual.textContent =
        sourceControl.checked
          ? "✓"
          : "";

      visual.classList.toggle(
        "is-checked",
        sourceControl.checked
      );

      visual.setAttribute(
        "role",
        "checkbox"
      );

      visual.setAttribute(
        "aria-checked",
        String(
          sourceControl.checked
        )
      );

      clonedControl.remove();

      return;
    }

    const check =
      targetDocument.createElement(
        "span"
      );

    check.textContent =
      sourceControl.checked
        ? "☑"
        : "☐";

    clonedControl.replaceWith(
      check
    );

    return;
  }

  const isTextarea =
    sourceControl.tagName ===
    "TEXTAREA";

  const isSelect =
    sourceControl.tagName ===
    "SELECT";

  const output =
    targetDocument.createElement(
      isTextarea
        ? "div"
        : "span"
    );

  output.className = [
    "efficiency-daily-work-static-control",

    isTextarea
      ? "is-static-textarea"
      : "",

    isSelect
      ? "is-static-select"
      : ""
  ]
    .filter(Boolean)
    .join(" ");

  let value =
    "";

  if (isSelect) {
    value =
      sourceControl.value
        ? [
            ...sourceControl.selectedOptions
          ]
            .map(
              option => {
                return String(
                  option.textContent ||
                  ""
                ).trim();
              }
            )
            .filter(Boolean)
            .join(", ")
        : "";

  } else {
    value =
      String(
        sourceControl.value ??
        ""
      ).replace(
        /\r\n?/g,
        "\n"
      );
  }

  output.textContent =
    value ||
    "\u00a0";

  if (clonedControl.id) {
    output.id =
      clonedControl.id;
  }

  const fieldName =
    sourceControl.dataset
      ?.efficiencyDailyWorkField;

  if (fieldName) {
    output.dataset
      .efficiencyDailyWorkField =
      fieldName;
  }

  const ariaLabel =
    sourceControl.getAttribute(
      "aria-label"
    );

  if (ariaLabel) {
    output.setAttribute(
      "aria-label",
      ariaLabel
    );
  }

  output.setAttribute(
    "aria-readonly",
    "true"
  );

  clonedControl.replaceWith(
    output
  );
}

function createEfficiencyDailyWorkStaticPaper(
  printContext,
  targetDocument
) {
  const sourcePaper =
    printContext.elements.paper;

  const clonedPaper =
    targetDocument.importNode(
      sourcePaper,
      true
    );

  const sourceControls = [
    ...sourcePaper.querySelectorAll(
      "input, select, textarea"
    )
  ];

  const clonedControls = [
    ...clonedPaper.querySelectorAll(
      "input, select, textarea"
    )
  ];

  if (
    sourceControls.length !==
    clonedControls.length
  ) {
    throw new Error(
      "인쇄용 입력 요소를 정확히 복제하지 못했습니다."
    );
  }

  sourceControls.forEach(
    (
      sourceControl,
      index
    ) => {
      staticizeEfficiencyDailyWorkControl(
        sourceControl,
        clonedControls[index],
        targetDocument
      );
    }
  );

  clonedPaper.classList.remove(
    "is-overflowing"
  );

  const clonedDate =
    clonedPaper.querySelector(
      "#efficiencyDailyWorkFormattedDate"
    );

  if (clonedDate) {
    clonedDate.textContent =
      printContext.formattedDate;

    clonedDate.setAttribute(
      "datetime",
      printContext.workDate
    );
  }

  return clonedPaper;
}

/* =========================================================
  스타일시트와 폰트 준비
========================================================= */

function copyEfficiencyDailyWorkStylesToPreviewDocument(
  targetDocument
) {
  const readyPromises = [
    ...document.querySelectorAll(
      'link[rel~="stylesheet"][href], style'
    )
  ].map(
    sourceNode => {
      if (
        sourceNode.tagName ===
        "STYLE"
      ) {
        const style =
          targetDocument.createElement(
            "style"
          );

        style.textContent =
          sourceNode.textContent ||
          "";

        targetDocument.head.append(
          style
        );

        return Promise.resolve();
      }

      const link =
        targetDocument.createElement(
          "link"
        );

      link.rel =
        "stylesheet";

      link.href =
        sourceNode.href;

      const ready =
        new Promise(
          resolve => {
            let finished =
              false;

            const finish =
              () => {
                if (finished) {
                  return;
                }

                finished =
                  true;

                resolve();
              };

            link.addEventListener(
              "load",
              finish,
              {
                once:
                  true
              }
            );

            link.addEventListener(
              "error",
              finish,
              {
                once:
                  true
              }
            );

            window.setTimeout(
              finish,
              2500
            );
          }
        );

      targetDocument.head.append(
        link
      );

      return ready;
    }
  );

  const previewStyle =
    targetDocument.createElement(
      "style"
    );

  previewStyle.textContent =
    EFFICIENCY_DAILY_WORK_PREVIEW_STYLE;

  targetDocument.head.append(
    previewStyle
  );

  return Promise.all(
    readyPromises
  );
}

async function waitEfficiencyDailyWorkPreviewReady(
  previewWindow,
  stylesheetReady
) {
  await stylesheetReady;

  try {
    await previewWindow.document.fonts
      ?.ready;

  } catch (error) {
    console.error(
      "일일업무현황 미리보기 폰트 확인 오류:",
      error
    );
  }

  await new Promise(
    resolve => {
      previewWindow.requestAnimationFrame(
        () => {
          previewWindow.requestAnimationFrame(
            resolve
          );
        }
      );
    }
  );
}

/* =========================================================
  미리보기 상단 버튼 및 실제 인쇄
========================================================= */

function createEfficiencyDailyWorkPreviewToolbar(
  previewWindow,
  printContext
) {
  const doc =
    previewWindow.document;

  const toolbar =
    doc.createElement(
      "header"
    );

  toolbar.className =
    "efficiency-daily-work-popup-toolbar";

  const textGroup =
    doc.createElement(
      "div"
    );

  textGroup.className =
    "efficiency-daily-work-popup-toolbar__text";

  const title =
    doc.createElement(
      "strong"
    );

  title.textContent =
    `${printContext.formattedDate} PDF 미리보기`;

  const description =
    doc.createElement(
      "span"
    );

  description.textContent =
    printContext.hasOverflow
      ? "입력 내용이 A4 한 페이지를 초과했습니다. 잘리는 부분이 없는지 확인해주세요."
      : "인쇄 창에서 ‘PDF로 저장’을 선택하면 PDF 파일로 저장할 수 있습니다.";

  description.classList.toggle(
    "is-warning",
    printContext.hasOverflow
  );

  textGroup.append(
    title,
    description
  );

  const actions =
    doc.createElement(
      "div"
    );

  actions.className =
    "efficiency-daily-work-popup-toolbar__actions";

  const printButton =
    doc.createElement(
      "button"
    );

  printButton.type =
    "button";

  printButton.className =
    "is-primary";

  printButton.textContent =
    "인쇄 · PDF 저장";

  printButton.disabled =
    true;

  const closeButton =
    doc.createElement(
      "button"
    );

  closeButton.type =
    "button";

  closeButton.textContent =
    "닫기";

  closeButton.addEventListener(
    "click",
    () => {
      previewWindow.close();
    }
  );

  actions.append(
    printButton,
    closeButton
  );

  toolbar.append(
    textGroup,
    actions
  );

  return {
    toolbar,

    printButton
  };
}

async function printEfficiencyDailyWorkPopup(
  previewWindow,
  readyPromise,
  closeAfterPrint
) {
  if (
    !previewWindow ||
    previewWindow.closed ||
    efficiencyDailyWorkPrintingWindows
      .has(previewWindow)
  ) {
    return false;
  }

  efficiencyDailyWorkPrintingWindows
    .add(previewWindow);

  try {
    await readyPromise;

    if (previewWindow.closed) {
      return false;
    }

    if (closeAfterPrint) {
      previewWindow.addEventListener(
        "afterprint",
        () => {
          window.setTimeout(
            () => {
              if (!previewWindow.closed) {
                previewWindow.close();
              }
            },
            150
          );
        },
        {
          once:
            true
        }
      );
    }

    previewWindow.focus();

    previewWindow.print();

    return true;

  } catch (error) {
    console.error(
      "일일업무현황 인쇄 실패:",
      error
    );

    showEfficiencyDailyWorkPrintError(
      "인쇄 화면을 준비하지 못했습니다. 다시 시도해주세요."
    );

    return false;

  } finally {
    efficiencyDailyWorkPrintingWindows
      .delete(previewWindow);
  }
}

/* =========================================================
  A4 미리보기 창 생성
========================================================= */

function openEfficiencyDailyWorkPrintWindow(
  autoPrint
) {
  if (efficiencyDailyWorkPrintOpening) {
    return null;
  }

  let printContext;

  try {
    printContext =
      createEfficiencyDailyWorkPrintContext();

  } catch (error) {
    showEfficiencyDailyWorkPrintError(
      error.message ||
      "인쇄할 내용을 확인해주세요."
    );

    return null;
  }

  efficiencyDailyWorkPrintOpening =
    true;

  const windowName =
    autoPrint
      ? `GS_EFFICIENCY_DAILY_WORK_PRINT_${++efficiencyDailyWorkPrintWindowSequence}`
      : EFFICIENCY_DAILY_WORK_PREVIEW_WINDOW_NAME;

  let previewWindow =
    null;

  try {
    previewWindow =
      window.open(
        "about:blank",
        windowName,
        "popup=yes,width=1100,height=900,resizable=yes,scrollbars=yes"
      );

    if (
      !previewWindow ||
      previewWindow.closed
    ) {
      showEfficiencyDailyWorkPrintError(
        "팝업이 차단되었습니다. 브라우저에서 이 사이트의 팝업을 허용해주세요."
      );

      if (
        typeof showToast ===
        "function"
      ) {
        showToast(
          "팝업 차단을 해제해주세요."
        );
      }

      return null;
    }

    const doc =
      previewWindow.document;

    doc.open();

    doc.write(
      '<!DOCTYPE html><html lang="ko"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head><body></body></html>'
    );

    doc.close();

    doc.title =
      `설비운영팀 일일 업무 현황 - ${printContext.workDate}`;

    doc.body.className =
      "efficiency-daily-work-preview-body is-efficiency-daily-work-printing";

    const stylesheetReady =
      copyEfficiencyDailyWorkStylesToPreviewDocument(
        doc
      );

    const toolbar =
      createEfficiencyDailyWorkPreviewToolbar(
        previewWindow,
        printContext
      );

    const modalRoot =
      doc.createElement(
        "main"
      );

    modalRoot.id =
      "efficiencyTeamModal";

    const stage =
      doc.createElement(
        "div"
      );

    stage.className =
      "efficiency-daily-work-popup-stage";

    stage.append(
      createEfficiencyDailyWorkStaticPaper(
        printContext,
        doc
      )
    );

    modalRoot.append(
      stage
    );

    doc.body.append(
      toolbar.toolbar,
      modalRoot
    );

    const readyPromise =
      waitEfficiencyDailyWorkPreviewReady(
        previewWindow,
        stylesheetReady
      );

    readyPromise.then(
      () => {
        if (!previewWindow.closed) {
          toolbar.printButton.disabled =
            false;
        }
      }
    );

    toolbar.printButton.addEventListener(
      "click",
      () => {
        printEfficiencyDailyWorkPopup(
          previewWindow,
          readyPromise,
          false
        );
      }
    );

    if (printContext.hasOverflow) {
      showEfficiencyDailyWorkPrintError(
        "입력 내용이 A4 한 페이지를 초과했습니다. 미리보기에서 잘리는 부분이 없는지 확인해주세요."
      );

    } else {
      clearEfficiencyDailyWorkPrintError();
    }

    previewWindow.focus();

    if (autoPrint) {
      printEfficiencyDailyWorkPopup(
        previewWindow,
        readyPromise,
        true
      );
    }

    return previewWindow;

  } catch (error) {
    console.error(
      "일일업무현황 미리보기 생성 실패:",
      error
    );

    if (
      previewWindow &&
      !previewWindow.closed
    ) {
      previewWindow.close();
    }

    showEfficiencyDailyWorkPrintError(
      error.message ||
      "PDF 미리보기를 만들지 못했습니다."
    );

    return null;

  } finally {
    window.setTimeout(
      () => {
        efficiencyDailyWorkPrintOpening =
          false;
      },
      350
    );
  }
}

/* =========================================================
  버튼 이벤트 연결
========================================================= */

function bindEfficiencyDailyWorkPrintEvents() {
  const elements =
    getEfficiencyDailyWorkElements();

  [
    [
      elements.previewPdfButton,

      event => {
        event.preventDefault();

        openEfficiencyDailyWorkPrintWindow(
          false
        );
      }
    ],

    [
      elements.printButton,

      event => {
        event.preventDefault();

        openEfficiencyDailyWorkPrintWindow(
          true
        );
      }
    ]
  ].forEach(
    (
      [
        button,
        handler
      ]
    ) => {
      if (
        !button ||
        efficiencyDailyWorkPrintBoundButtons
          .has(button)
      ) {
        return;
      }

      button.addEventListener(
        "click",
        handler
      );

      efficiencyDailyWorkPrintBoundButtons
        .add(button);
    }
  );

  if (
    elements.form &&
    !efficiencyDailyWorkPrintBoundForms
      .has(elements.form)
  ) {
    const refreshOverflow =
      () => {
        clearEfficiencyDailyWorkPrintError();

        refreshEfficiencyDailyWorkPageOverflowState();
      };

    elements.form.addEventListener(
      "input",
      refreshOverflow
    );

    elements.form.addEventListener(
      "change",
      refreshOverflow
    );

    efficiencyDailyWorkPrintBoundForms
      .add(elements.form);
  }

  refreshEfficiencyDailyWorkPageOverflowState();

  return true;
}

function initializeEfficiencyDailyWorkPrint() {
  return bindEfficiencyDailyWorkPrintEvents();
}

initializeEfficiencyDailyWorkPrint();

/* =========================================================
  효율팀 - 일일업무현황
  15단계: 입력칸 글자 서식 적용·저장·복원·PDF 연결
========================================================= */

(function installEfficiencyDailyWorkFormatFeature() {
  if (window.__efficiencyDailyWorkFormatFeatureInstalled) {
    return;
  }

  window.__efficiencyDailyWorkFormatFeatureInstalled =
    true;

  const FIELD_NAMES = Object.freeze([
    "notice",
    "tmMeeting",
    "teamInstruction",

    "efficiencyOverallAssignee",
    "efficiencyOverallTasks",
    "efficiencyOverallRemarks",

    "efficiency1Assignee",
    "efficiency1Tasks",
    "efficiency1Remarks",

    "efficiency2Assignee",
    "efficiency2Tasks",
    "efficiency2Remarks",

    "efficiency3Assignee",
    "efficiency3Tasks",
    "efficiency3Remarks",

    "purchaseAdminAssignee",
    "purchaseAdminTasks",
    "purchaseAdminRemarks",

    "dayMembers",
    "dayTasks",
    "dayRemarks",

    "nightMembers",
    "nightTasks",
    "nightRemarks",

    "otherNotes"
  ]);

  const FONT_FAMILIES = Object.freeze({
    pretendard:
      'Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif',

    "malgun-gothic":
      '"Malgun Gothic", "맑은 고딕", sans-serif',

    "nanum-gothic":
      '"Nanum Gothic", "나눔고딕", sans-serif',

    dotum:
      'Dotum, "돋움", sans-serif',

    gulim:
      'Gulim, "굴림", sans-serif',

    batang:
      'Batang, "바탕", serif'
  });

  const FONT_SIZES = Object.freeze([
    7,
    8,
    9,
    10,
    11,
    12,
    14,
    16
  ]);

  const STYLE_PROPERTIES = Object.freeze([
    "font-family",
    "font-size",
    "font-weight",
    "color"
  ]);

  const state = {
    target: null
  };


  function getFormatElements() {
    return {
      ...getEfficiencyDailyWorkElements(),

      toolbar:
        document.getElementById(
          "efficiencyDailyWorkFormatToolbar"
        ),

      targetLabel:
        document.getElementById(
          "efficiencyDailyWorkFormatTargetLabel"
        ),

      fontFamily:
        document.getElementById(
          "efficiencyDailyWorkFontFamily"
        ),

      fontSize:
        document.getElementById(
          "efficiencyDailyWorkFontSize"
        ),

      boldButton:
        document.getElementById(
          "toggleEfficiencyDailyWorkBoldButton"
        ),

      textColor:
        document.getElementById(
          "efficiencyDailyWorkTextColor"
        ),

      textColorValue:
        document.getElementById(
          "efficiencyDailyWorkTextColorValue"
        ),

      resetButton:
        document.getElementById(
          "resetEfficiencyDailyWorkFormatButton"
        )
    };
  }


  function getFormatControls(
    elements =
      getFormatElements()
  ) {
    return [
      ...(
        elements.paper?.querySelectorAll(
          'input[type="text"][name], textarea[name]'
        ) ||
        []
      )
    ].filter(
      control => {
        return FIELD_NAMES.includes(
          control.name
        );
      }
    );
  }


  function isFormatControl(
    control,
    elements =
      getFormatElements()
  ) {
    return Boolean(
      control &&
      elements.paper?.contains(
        control
      ) &&
      control.matches?.(
        'input[type="text"][name], textarea[name]'
      ) &&
      FIELD_NAMES.includes(
        control.name
      )
    );
  }


  function normalizeFontFamily(
    value
  ) {
    const token =
      String(
        value ||
        ""
      ).trim();

    return Object.prototype
      .hasOwnProperty
      .call(
        FONT_FAMILIES,
        token
      )
        ? token
        : "";
  }


  function normalizeFontSize(
    value
  ) {
    const numericValue =
      Number(
        String(
          value ??
          ""
        )
          .replace(
            /px$/i,
            ""
          )
          .trim()
      );

    return FONT_SIZES.includes(
      numericValue
    )
      ? numericValue
      : null;
  }


  function normalizeTextColor(
    value
  ) {
    const color =
      String(
        value ||
        ""
      )
        .trim()
        .toLowerCase();

    return /^#[0-9a-f]{6}$/.test(
      color
    )
      ? color
      : "";
  }


  function normalizeBoldValue(
    source
  ) {
    if (
      !source ||
      !Object.prototype
        .hasOwnProperty
        .call(
          source,
          "bold"
        )
    ) {
      return undefined;
    }

    const value =
      String(
        source.bold
      )
        .trim()
        .toLowerCase();

    if (
      source.bold ===
        true ||
      [
        "1",
        "true",
        "bold"
      ].includes(
        value
      )
    ) {
      return true;
    }

    if (
      source.bold ===
        false ||
      [
        "0",
        "false",
        "normal"
      ].includes(
        value
      )
    ) {
      return false;
    }

    return undefined;
  }


  function normalizeFieldFormat(
    source
  ) {
    const parsed =
      parseEfficiencyDailyWorkStructuredValue(
        source,
        {}
      );

    const safe =
      parsed &&
      !Array.isArray(
        parsed
      )
        ? parsed
        : {};

    const format = {};

    const fontFamily =
      normalizeFontFamily(
        safe.fontFamily ??
        safe.font_family
      );

    const fontSize =
      normalizeFontSize(
        safe.fontSize ??
        safe.font_size
      );

    const bold =
      normalizeBoldValue(
        safe
      );

    const textColor =
      normalizeTextColor(
        safe.textColor ??
        safe.text_color ??
        safe.color
      );

    if (fontFamily) {
      format.fontFamily =
        fontFamily;
    }

    if (
      fontSize !==
        null
    ) {
      format.fontSize =
        fontSize;
    }

    if (
      bold !==
        undefined
    ) {
      format.bold =
        bold;
    }

    if (textColor) {
      format.textColor =
        textColor;
    }

    return format;
  }


  function normalizeFieldFormats(
    source
  ) {
    const parsed =
      parseEfficiencyDailyWorkStructuredValue(
        source,
        {}
      );

    const safe =
      parsed &&
      !Array.isArray(
        parsed
      )
        ? parsed
        : {};

    const result = {};

    FIELD_NAMES.forEach(
      fieldName => {
        const format =
          normalizeFieldFormat(
            safe[fieldName]
          );

        if (
          Object.keys(
            format
          ).length
        ) {
          result[fieldName] =
            format;
        }
      }
    );

    return result;
  }


  function readControlFormat(
    control
  ) {
    if (!control) {
      return {};
    }

    const source = {
      fontFamily:
        control.dataset
          .efficiencyDailyWorkFormatFontFamily,

      fontSize:
        control.dataset
          .efficiencyDailyWorkFormatFontSize,

      textColor:
        control.dataset
          .efficiencyDailyWorkFormatTextColor
    };

    if (
      control.hasAttribute(
        "data-efficiency-daily-work-format-bold"
      )
    ) {
      source.bold =
        control.dataset
          .efficiencyDailyWorkFormatBold;
    }

    return normalizeFieldFormat(
      source
    );
  }


  function writeControlFormat(
    control,
    source
  ) {
    if (!control) {
      return {};
    }

    const format =
      normalizeFieldFormat(
        source
      );

    if (
      format.fontFamily
    ) {
      control.dataset
        .efficiencyDailyWorkFormatFontFamily =
        format.fontFamily;

      control.style.setProperty(
        "font-family",
        FONT_FAMILIES[
          format.fontFamily
        ],
        "important"
      );

    } else {
      delete control.dataset
        .efficiencyDailyWorkFormatFontFamily;

      control.style.removeProperty(
        "font-family"
      );
    }

    if (
      format.fontSize !==
        undefined
    ) {
      control.dataset
        .efficiencyDailyWorkFormatFontSize =
        String(
          format.fontSize
        );

      control.style.setProperty(
        "font-size",
        `${format.fontSize}px`,
        "important"
      );

    } else {
      delete control.dataset
        .efficiencyDailyWorkFormatFontSize;

      control.style.removeProperty(
        "font-size"
      );
    }

    if (
      Object.prototype
        .hasOwnProperty
        .call(
          format,
          "bold"
        )
    ) {
      control.dataset
        .efficiencyDailyWorkFormatBold =
        String(
          format.bold
        );

      control.style.setProperty(
        "font-weight",
        format.bold
          ? "900"
          : "500",
        "important"
      );

    } else {
      delete control.dataset
        .efficiencyDailyWorkFormatBold;

      control.style.removeProperty(
        "font-weight"
      );
    }

    if (
      format.textColor
    ) {
      control.dataset
        .efficiencyDailyWorkFormatTextColor =
        format.textColor;

      control.style.setProperty(
        "color",
        format.textColor,
        "important"
      );

    } else {
      delete control.dataset
        .efficiencyDailyWorkFormatTextColor;

      control.style.removeProperty(
        "color"
      );
    }

    return format;
  }


  function collectFieldFormats(
    elements =
      getFormatElements()
  ) {
    const source = {};

    getFormatControls(
      elements
    ).forEach(
      control => {
        const format =
          readControlFormat(
            control
          );

        if (
          Object.keys(
            format
          ).length
        ) {
          source[
            control.name
          ] =
            format;
        }
      }
    );

    return normalizeFieldFormats(
      source
    );
  }


  function clearTarget(
    elements =
      getFormatElements()
  ) {
    getFormatControls(
      elements
    ).forEach(
      control => {
        control.removeAttribute(
          "data-efficiency-daily-work-format-target"
        );
      }
    );

    state.target =
      null;

    renderToolbar(
      elements
    );
  }


  function clearAllFormats(
    elements =
      getFormatElements()
  ) {
    getFormatControls(
      elements
    ).forEach(
      control => {
        writeControlFormat(
          control,
          {}
        );
      }
    );

    clearTarget(
      elements
    );
  }


  function applyFieldFormats(
    source,
    elements =
      getFormatElements()
  ) {
    const formats =
      normalizeFieldFormats(
        source
      );

    getFormatControls(
      elements
    ).forEach(
      control => {
        writeControlFormat(
          control,
          formats[
            control.name
          ] ||
          {}
        );
      }
    );

    clearTarget(
      elements
    );

    return formats;
  }


  function getTargetLabel(
    control
  ) {
    const fixedLabels = {
      notice:
        "공지사항",

      tmMeeting:
        "TM 회의",

      teamInstruction:
        "설비운영팀 전달사항",

      otherNotes:
        "기타사항"
    };

    return (
      fixedLabels[
        control?.name
      ] ||
      control?.getAttribute?.(
        "aria-label"
      ) ||
      control?.name ||
      "선택한 입력칸"
    );
  }


  function renderToolbar(
    elements =
      getFormatElements()
  ) {
    if (
      !elements.toolbar
    ) {
      return false;
    }

    const target =
      isFormatControl(
        state.target,
        elements
      )
        ? state.target
        : null;

    state.target =
      target;

    const isBusy =
      efficiencyDailyWorkState
        .isLoading ||
      efficiencyDailyWorkState
        .isSaving ||
      efficiencyDailyWorkDateTransitionPending;

    const canEdit =
      Boolean(
        target
      ) &&
      !isBusy;

    const format =
      readControlFormat(
        target
      );

    const color =
      format.textColor ||
      "#111111";

    elements.toolbar.dataset
      .formatTargetState =
      target
        ? "ready"
        : "empty";

    if (
      elements.targetLabel
    ) {
      elements.targetLabel
        .textContent =
        target
          ? getTargetLabel(
              target
            )
          : "입력칸을 먼저 클릭하세요.";
    }

    if (
      elements.fontFamily
    ) {
      elements.fontFamily.value =
        format.fontFamily ||
        "";

      elements.fontFamily.disabled =
        !canEdit;
    }

    if (
      elements.fontSize
    ) {
      elements.fontSize.value =
        format.fontSize ===
          undefined
          ? ""
          : String(
              format.fontSize
            );

      elements.fontSize.disabled =
        !canEdit;
    }

    if (
      elements.boldButton
    ) {
      elements.boldButton
        .setAttribute(
          "aria-pressed",
          String(
            format.bold ===
              true
          )
        );

      elements.boldButton.disabled =
        !canEdit;
    }

    if (
      elements.textColor
    ) {
      elements.textColor.value =
        color;

      elements.textColor.disabled =
        !canEdit;
    }

    if (
      elements.textColorValue
    ) {
      elements.textColorValue.value =
        color.toUpperCase();

      elements.textColorValue.textContent =
        color.toUpperCase();
    }

    if (
      elements.resetButton
    ) {
      elements.resetButton.disabled =
        !canEdit ||
        !Object.keys(
          format
        ).length;
    }

    return true;
  }


  function setTarget(
    control
  ) {
    const elements =
      getFormatElements();

    if (
      !isFormatControl(
        control,
        elements
      )
    ) {
      return false;
    }

    getFormatControls(
      elements
    ).forEach(
      candidate => {
        candidate.removeAttribute(
          "data-efficiency-daily-work-format-target"
        );
      }
    );

    control.setAttribute(
      "data-efficiency-daily-work-format-target",
      "true"
    );

    state.target =
      control;

    renderToolbar(
      elements
    );

    return true;
  }


  function notifyFormatChanged() {
    if (
      typeof clearEfficiencyDailyWorkSaveFeedbackOnEdit ===
        "function"
    ) {
      clearEfficiencyDailyWorkSaveFeedbackOnEdit();
    }

    if (
      typeof refreshEfficiencyDailyWorkDirtyState ===
        "function"
    ) {
      refreshEfficiencyDailyWorkDirtyState();
    }

    if (
      typeof refreshEfficiencyDailyWorkPageOverflowState ===
        "function"
    ) {
      refreshEfficiencyDailyWorkPageOverflowState();
    }
  }


  function updateTargetFormat(
    patch
  ) {
    const elements =
      getFormatElements();

    if (
      efficiencyDailyWorkState
        .isLoading ||
      efficiencyDailyWorkState
        .isSaving ||
      efficiencyDailyWorkDateTransitionPending
    ) {
      renderToolbar(
        elements
      );

      return false;
    }

    if (
      !isFormatControl(
        state.target,
        elements
      )
    ) {
      clearTarget(
        elements
      );

      return false;
    }

    const before =
      JSON.stringify(
        readControlFormat(
          state.target
        )
      );

    const applied =
      writeControlFormat(
        state.target,
        {
          ...readControlFormat(
            state.target
          ),

          ...patch
        }
      );

    const changed =
      before !==
      JSON.stringify(
        applied
      );

    if (changed) {
      notifyFormatChanged();
    }

    renderToolbar(
      elements
    );

    return changed;
  }


  function bindToolbarEvents() {
    const elements =
      getFormatElements();

    if (
      !elements.form ||
      !elements.paper ||
      !elements.toolbar
    ) {
      return false;
    }

    const selectTarget =
      event => {
        setTarget(
          event.target
        );
      };

    elements.paper.addEventListener(
      "pointerdown",
      selectTarget
    );

    elements.paper.addEventListener(
      "focusin",
      selectTarget
    );

    elements.fontFamily
      ?.addEventListener(
        "change",
        event => {
          updateTargetFormat({
            fontFamily:
              event.target.value
          });
        }
      );

    elements.fontSize
      ?.addEventListener(
        "change",
        event => {
          updateTargetFormat({
            fontSize:
              event.target.value
          });
        }
      );

    elements.boldButton
      ?.addEventListener(
        "click",
        () => {
          const current =
            readControlFormat(
              state.target
            );

          updateTargetFormat({
            bold:
              current.bold ===
                true
                ? false
                : true
          });
        }
      );

    elements.textColor
      ?.addEventListener(
        "input",
        event => {
          updateTargetFormat({
            textColor:
              event.target.value
          });
        }
      );

    elements.resetButton
      ?.addEventListener(
        "click",
        () => {
          if (
            !state.target
          ) {
            return;
          }

          const before =
            JSON.stringify(
              readControlFormat(
                state.target
              )
            );

          writeControlFormat(
            state.target,
            {}
          );

          if (
            before !==
              "{}"
          ) {
            notifyFormatChanged();
          }

          renderToolbar(
            elements
          );
        }
      );

    elements.form.addEventListener(
      "reset",
      () => {
        clearAllFormats(
          elements
        );
      }
    );

    renderToolbar(
      elements
    );

    return true;
  }


  function getRecordFieldFormats(
    record
  ) {
    const sourceRecord =
      parseEfficiencyDailyWorkStructuredValue(
        record,
        {}
      );

    const contentSource =
      getEfficiencyDailyWorkContentSource(
        sourceRecord ||
        {}
      );

    return normalizeFieldFormats(
      getEfficiencyDailyWorkFirstDefined(
        [
          sourceRecord,
          contentSource
        ],
        [
          "fieldFormats",
          "field_formats",
          "formats"
        ],
        {}
      )
    );
  }


  const originalNormalizeRecord =
    normalizeEfficiencyDailyWorkRecord;

  normalizeEfficiencyDailyWorkRecord =
    function (
      record
    ) {
      const normalized =
        originalNormalizeRecord(
          record
        );

      return normalized
        ? {
            ...normalized,

            fieldFormats:
              getRecordFieldFormats(
                record
              )
          }
        : null;
    };


  const originalCollectEditorData =
    collectEfficiencyDailyWorkEditorData;

  collectEfficiencyDailyWorkEditorData =
    function () {
      return {
        ...originalCollectEditorData(),

        fieldFormats:
          collectFieldFormats()
      };
    };


  const originalBuildSavePayload =
    buildEfficiencyDailyWorkSavePayload;

  buildEfficiencyDailyWorkSavePayload =
    function (
      sourceData =
        collectEfficiencyDailyWorkEditorData()
    ) {
      const payload =
        originalBuildSavePayload(
          sourceData
        );

      if (
        payload?.content
      ) {
        payload.content
          .fieldFormats =
          normalizeFieldFormats(
            sourceData
              ?.fieldFormats
          );
      }

      return payload;
    };


  const originalComparableContent =
    getEfficiencyDailyWorkComparableContent;

  getEfficiencyDailyWorkComparableContent =
    function (
      sourceData
    ) {
      return {
        ...originalComparableContent(
          sourceData
        ),

        fieldFormats:
          getRecordFieldFormats(
            sourceData
          )
      };
    };


  if (
    typeof populateEfficiencyDailyWorkEditorFromRecord ===
      "function"
  ) {
    const originalPopulateEditor =
      populateEfficiencyDailyWorkEditorFromRecord;

    populateEfficiencyDailyWorkEditorFromRecord =
      function (
        record
      ) {
        const normalized =
          normalizeEfficiencyDailyWorkRecord(
            record
          );

        const result =
          originalPopulateEditor(
            normalized ||
            record
          );

        applyFieldFormats(
          normalized
            ?.fieldFormats ||
          {}
        );

        return result;
      };
  }


  const originalSetLoading =
    setEfficiencyDailyWorkLoading;

  setEfficiencyDailyWorkLoading =
    function (
      isLoading
    ) {
      const result =
        originalSetLoading(
          isLoading
        );

      renderToolbar();

      return result;
    };


  const originalSetSaving =
    setEfficiencyDailyWorkSaving;

  setEfficiencyDailyWorkSaving =
    function (
      isSaving
    ) {
      const result =
        originalSetSaving(
          isSaving
        );

      renderToolbar();

      return result;
    };


  const originalStaticizeControl =
    staticizeEfficiencyDailyWorkControl;

  staticizeEfficiencyDailyWorkControl =
    function (
      sourceControl,
      clonedControl,
      targetDocument
    ) {
      if (
        !isFormatControl(
          sourceControl
        ) ||
        !clonedControl
          ?.parentNode
      ) {
        return originalStaticizeControl(
          sourceControl,
          clonedControl,
          targetDocument
        );
      }

      const marker =
        targetDocument
          .createComment(
            "daily-work-format"
          );

      clonedControl
        .parentNode
        .insertBefore(
          marker,
          clonedControl
        );

      const result =
        originalStaticizeControl(
          sourceControl,
          clonedControl,
          targetDocument
        );

      const output =
        marker.nextSibling;

      if (
        output?.style
      ) {
        STYLE_PROPERTIES
          .forEach(
            propertyName => {
              const value =
                sourceControl
                  .style
                  .getPropertyValue(
                    propertyName
                  )
                  .trim();

              if (!value) {
                return;
              }

              output.style.setProperty(
                propertyName,
                value,
                sourceControl
                  .style
                  .getPropertyPriority(
                    propertyName
                  )
              );
            }
          );
      }

      marker.remove();

      return result;
    };


  bindToolbarEvents();
})();

