  /* =====================================================
    문자열 안전 처리
  ====================================================== */

  function escapeLimestoneHtml(
    value
  ) {
    return String(
      value ??
      ""
    )
      .replaceAll(
        "&",
        "&amp;"
      )
      .replaceAll(
        "<",
        "&lt;"
      )
      .replaceAll(
        ">",
        "&gt;"
      )
      .replaceAll(
        '"',
        "&quot;"
      )
      .replaceAll(
        "'",
        "&#039;"
      );
  }


  /* =====================================================
    날짜 처리
  ====================================================== */

  function formatLimestoneDate(
    date
  ) {
    return [
      date.getFullYear(),

      String(
        date.getMonth() +
        1
      ).padStart(
        2,
        "0"
      ),

      String(
        date.getDate()
      ).padStart(
        2,
        "0"
      )
    ].join(
      "-"
    );
  }


  function getLimestoneToday() {
    return formatLimestoneDate(
      new Date()
    );
  }


  function addLimestoneDays(
    sourceDate,
    dayCount
  ) {
    const nextDate =
      new Date(
        sourceDate
      );


    nextDate.setDate(
      nextDate.getDate() +
      dayCount
    );


    return nextDate;
  }


  function isValidLimestoneDate(
    value
  ) {
    const normalizedValue =
      String(
        value ||
        ""
      ).trim();


    if (
      !/^\d{4}-\d{2}-\d{2}$/.test(
        normalizedValue
      )
    ) {
      return false;
    }


    const parsedDate =
      new Date(
        `${normalizedValue}T00:00:00`
      );


    return (
      !Number.isNaN(
        parsedDate.getTime()
      ) &&
      formatLimestoneDate(
        parsedDate
      ) ===
        normalizedValue
    );
  }


  /* =====================================================
    수량 표시
  ====================================================== */

  function normalizeLimestoneQuantity(
    value
  ) {
    const numericValue =
      Number(
        value
      );


    if (
      !Number.isFinite(
        numericValue
      )
    ) {
      return 0;
    }


    return (
      Math.round(
        numericValue *
        100
      ) /
      100
    );
  }


  function formatLimestoneQuantity(
    value
  ) {
    return normalizeLimestoneQuantity(
      value
    ).toLocaleString(
      "ko-KR",
      {
        minimumFractionDigits:
          2,

        maximumFractionDigits:
          2
      }
    );
  }


  /* =====================================================
    현재 시각
  ====================================================== */

  function getLimestoneCurrentTime() {
    const now =
      new Date();


    return [
      String(
        now.getHours()
      ).padStart(
        2,
        "0"
      ),

      String(
        now.getMinutes()
      ).padStart(
        2,
        "0"
      )
    ].join(
      ":"
    );
  }


  /* =====================================================
    API 헤더

    기존 업무일지 로그인 세션을 그대로 사용한다.
  ====================================================== */

  function getLimestoneApiHeaders(
    extraHeaders = {}
  ) {
    if (
      typeof getShiftLogAuthHeaders ===
        "function"
    ) {
      return getShiftLogAuthHeaders({
        Accept:
          "application/json",

        ...extraHeaders
      });
    }


    return {
      Accept:
        "application/json",

      ...extraHeaders
    };
  }


  /* =====================================================
    API 요청
  ====================================================== */

  async function requestLimestoneApi(
    requestUrl,
    options = {}
  ) {
    const response =
      await fetch(
        requestUrl,
        {
          cache:
            "no-store",

          ...options
        }
      );


    const responseText =
      await response.text();


    let result = {};


    if (
      responseText.trim()
    ) {
      try {
        result =
          JSON.parse(
            responseText
          );

      } catch {
        throw new Error(
          `석회석 서버 응답 형식이 올바르지 않습니다. HTTP ${response.status}`
        );
      }
    }


    if (
      !response.ok ||
      result.ok ===
        false
    ) {
      const error =
        new Error(
          result.message ||
          result.error ||
          `석회석 서버 요청 실패 (HTTP ${response.status})`
        );


      error.status =
        response.status;


      error.result =
        result;


      throw error;
    }


    return result;
  }


  /* =====================================================
    메시지
  ====================================================== */

  function showLimestoneToast(
    message
  ) {
    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );


      return;
    }


    alert(
      message
    );
  }


  function showLimestoneEditorMessage(
    message,
    type = "error"
  ) {
    const {
      editorMessage
    } =
      getLimestoneReceiptElements();


    if (
      !editorMessage
    ) {
      return;
    }


    editorMessage.textContent =
      String(
        message ||
        ""
      );


    editorMessage.hidden =
      !message;


    editorMessage.dataset.type =
      type;
  }


/* =====================================================
  날짜 문자열 → Date
===================================================== */

function parseLimestoneDateValue(
  value
) {
  const normalizedValue =
    String(
      value ||
      ""
    ).trim();


  if (
    !isValidLimestoneDate(
      normalizedValue
    )
  ) {
    return null;
  }


  const [
    year,
    month,
    day
  ] =
    normalizedValue
      .split(
        "-"
      )
      .map(
        Number
      );


  return new Date(
    year,
    month - 1,
    day
  );
}


/* =====================================================
  조회 기간 일수

  시작일과 종료일을 모두 포함한다.
===================================================== */

function getLimestoneDateRangeDayCount(
  startDateValue,
  endDateValue
) {
  const startDate =
    parseLimestoneDateValue(
      startDateValue
    );


  const endDate =
    parseLimestoneDateValue(
      endDateValue
    );


  if (
    !startDate ||
    !endDate ||
    startDate >
      endDate
  ) {
    return 0;
  }


  return (
    Math.round(
      (
        endDate.getTime() -
        startDate.getTime()
      ) /
      86400000
    ) +
    1
  );
}


/* =====================================================
  하루 이동바 표시용 날짜

  예:
  26.08.03 (월)
===================================================== */

function formatLimestoneDayNavigationLabel(
  dateValue
) {
  const parsedDate =
    parseLimestoneDateValue(
      dateValue
    );


  if (
    !parsedDate
  ) {
    return "-";
  }


  const weekdayLabels = [
    "일",
    "월",
    "화",
    "수",
    "목",
    "금",
    "토"
  ];


  const year =
    String(
      parsedDate.getFullYear()
    ).slice(
      -2
    );


  const month =
    String(
      parsedDate.getMonth() +
      1
    ).padStart(
      2,
      "0"
    );


  const day =
    String(
      parsedDate.getDate()
    ).padStart(
      2,
      "0"
    );


  const weekday =
    weekdayLabels[
      parsedDate.getDay()
    ];


  return `${year}.${month}.${day} (${weekday})`;
}


/* =====================================================
  하루 이동바와 기간 조회 표시 갱신
===================================================== */

function updateLimestonePeriodDisplay() {
  const {
    view,
    dayLabel,
    todayBadge,
    activeRangeInformation,
    startDateInput,
    endDateInput,
    periodLabel,
    periodDayCount
  } =
    getLimestoneReceiptElements();


  const today =
    getLimestoneToday();


  const startDate =
    String(
      startDateInput?.value ||
      ""
    ).trim();


  const endDate =
    String(
      endDateInput?.value ||
      ""
    ).trim();


  const selectedDay =
    isValidLimestoneDate(
      limestoneReceiptState
        .selectedDay
    )
      ? limestoneReceiptState
          .selectedDay
      : today;


  const isRangeMode =
    limestoneReceiptState
      .queryMode ===
    "range";


  if (
    dayLabel
  ) {
    dayLabel.textContent =
      formatLimestoneDayNavigationLabel(
        selectedDay
      );
  }


  if (
    todayBadge
  ) {
    todayBadge.hidden =
      selectedDay !==
      today;
  }


  if (
    activeRangeInformation
  ) {
    activeRangeInformation.hidden =
      !isRangeMode;
  }


  if (
    periodLabel
  ) {
    periodLabel.textContent =
      startDate &&
      endDate
        ? `${startDate} ~ ${endDate}`
        : "-";
  }


  if (
    periodDayCount
  ) {
    const dayCount =
      getLimestoneDateRangeDayCount(
        startDate,
        endDate
      );


    periodDayCount.textContent =
      dayCount >
        0
        ? `${dayCount}일`
        : "-";
  }


  view?.classList.toggle(
    "is-day-query-mode",
    !isRangeMode
  );


  view?.classList.toggle(
    "is-range-query-mode",
    isRangeMode
  );
}


/* =====================================================
  기본 조회 설정

  오늘 하루만 조회한다.
===================================================== */

function setDefaultLimestoneDateRange() {
  const {
    startDateInput,
    endDateInput,
    unitFilter
  } =
    getLimestoneReceiptElements();


  if (
    !startDateInput ||
    !endDateInput
  ) {
    return;
  }


  const today =
    getLimestoneToday();


  limestoneReceiptState
    .queryMode =
    "day";


  limestoneReceiptState
    .selectedDay =
    today;


  startDateInput.value =
    today;


  endDateInput.value =
    today;


  endDateInput.min =
    today;


  if (
    unitFilter
  ) {
    unitFilter.value =
      "";
  }


  setLimestoneGroupMode(
    "daily",
    {
      render:
        false
    }
  );


  closeLimestonePeriodSearchPanel();


  updateLimestonePeriodDisplay();
}


/* =====================================================
  특정 날짜 하루 조회

  시작일과 종료일을 같은 날짜로 설정한다.
===================================================== */

async function setLimestoneDayQuery(
  dateValue,
  options = {}
) {
  const {
    load =
      true
  } = options;


  const {
    startDateInput,
    endDateInput,
    unitFilter
  } =
    getLimestoneReceiptElements();


  const parsedDate =
    parseLimestoneDateValue(
      dateValue
    );


  if (
    !parsedDate ||
    !startDateInput ||
    !endDateInput
  ) {
    showLimestoneToast(
      "조회할 날짜를 확인해 주세요."
    );


    return;
  }


  const normalizedDate =
    formatLimestoneDate(
      parsedDate
    );


  limestoneReceiptState
    .queryMode =
    "day";


  limestoneReceiptState
    .selectedDay =
    normalizedDate;


  startDateInput.value =
    normalizedDate;


  endDateInput.value =
    normalizedDate;


  endDateInput.min =
    normalizedDate;


  /*
    하루 조회에서는 전체 호기를 조회한다.

    합계 카드에서 1호기와 2호기를
    각각 확인할 수 있다.
  */
  if (
    unitFilter
  ) {
    unitFilter.value =
      "";
  }


  setLimestoneGroupMode(
    "daily",
    {
      render:
        false
    }
  );


  closeLimestonePeriodSearchPanel();


  closeLimestoneImportPanel();


  updateLimestonePeriodDisplay();


  if (
    load
  ) {
    await loadLimestoneReceipts();
  }
}


/* =====================================================
  이전·다음 하루 이동

  -1:
  전날

  1:
  다음 날
===================================================== */

async function moveLimestoneDay(
  direction
) {
  const normalizedDirection =
    Number(
      direction
    );


  if (
    ![
      -1,
      1
    ].includes(
      normalizedDirection
    )
  ) {
    return;
  }


  const currentDateValue =
    isValidLimestoneDate(
      limestoneReceiptState
        .selectedDay
    )
      ? limestoneReceiptState
          .selectedDay
      : getLimestoneToday();


  const currentDate =
    parseLimestoneDateValue(
      currentDateValue
    );


  if (
    !currentDate
  ) {
    showLimestoneToast(
      "현재 조회 날짜를 확인할 수 없습니다."
    );


    return;
  }


  const nextDate =
    addLimestoneDays(
      currentDate,
      normalizedDirection
    );


  await setLimestoneDayQuery(
    formatLimestoneDate(
      nextDate
    )
  );
}


/* =====================================================
  오늘 하루로 이동
===================================================== */

async function moveLimestoneDateRangeToToday() {
  await setLimestoneDayQuery(
    getLimestoneToday()
  );
}


/* =====================================================
  기간 조회 설정창 열기

  - 연도 목록 생성
  - 주차 버튼 생성
  - 월 버튼 생성
  - 현재 조회 단위 화면 표시
===================================================== */

function openLimestonePeriodSearchPanel() {
  const {
    searchForm,
    startDateInput,
    endDateInput,
    openPeriodSearchButton
  } =
    getLimestoneReceiptElements();


  if (
    !searchForm
  ) {
    showLimestoneToast(
      "기간 조회 설정창을 찾을 수 없습니다."
    );


    return;
  }


  closeLimestoneReceiptEditor();


  closeLimestoneImportPanel();


  /*
    하루 조회 중이면 현재 보고 있던 날짜를
    일별 시작일·종료일 기본값으로 사용한다.
  */
  if (
    limestoneReceiptState
      .queryMode ===
      "day"
  ) {
    const selectedDay =
      isValidLimestoneDate(
        limestoneReceiptState
          .selectedDay
      )
        ? limestoneReceiptState
            .selectedDay
        : getLimestoneToday();


    if (
      startDateInput
    ) {
      startDateInput.value =
        selectedDay;
    }


    if (
      endDateInput
    ) {
      endDateInput.value =
        selectedDay;


      endDateInput.min =
        selectedDay;
    }
  }


  searchForm.hidden =
    false;


  searchForm.removeAttribute(
    "hidden"
  );


  searchForm.classList.add(
    "is-open"
  );


  openPeriodSearchButton
    ?.classList
    .add(
      "is-active"
    );


  openPeriodSearchButton
    ?.setAttribute(
      "aria-expanded",
      "true"
    );


  /*
    주별·월별 선택 기능을 초기화한다.
  */
  initializeLimestonePeriodSelectionControls();


  window.requestAnimationFrame(
    () => {
      searchForm.scrollIntoView({
        behavior:
          "smooth",

        block:
          "nearest"
      });
    }
  );
}


/* =====================================================
  기간 조회 설정창 닫기
===================================================== */

function closeLimestonePeriodSearchPanel() {
  const {
    searchForm,
    openPeriodSearchButton
  } =
    getLimestoneReceiptElements();


  if (
    !searchForm
  ) {
    return;
  }


  searchForm.classList.remove(
    "is-open"
  );


  searchForm.hidden =
    true;


  searchForm.setAttribute(
    "hidden",
    ""
  );


  openPeriodSearchButton
    ?.classList
    .remove(
      "is-active"
    );


  openPeriodSearchButton
    ?.setAttribute(
      "aria-expanded",
      "false"
    );
}


/* =====================================================
  기간 조회 실행
===================================================== */

async function applyLimestonePeriodSearch() {
  const {
    startDateInput,
    endDateInput
  } =
    getLimestoneReceiptElements();


  const startDate =
    String(
      startDateInput?.value ||
      ""
    ).trim();


  const endDate =
    String(
      endDateInput?.value ||
      ""
    ).trim();


  if (
    !isValidLimestoneDate(
      startDate
    ) ||
    !isValidLimestoneDate(
      endDate
    )
  ) {
    showLimestoneToast(
      "조회 시작일과 종료일을 선택해 주세요."
    );


    return;
  }


  if (
    startDate >
      endDate
  ) {
    showLimestoneToast(
      "조회 시작일은 종료일보다 늦을 수 없습니다."
    );


    return;
  }


  limestoneReceiptState
    .queryMode =
    "range";


  /*
    기간 조회 후 화살표를 누르면
    기간 종료일을 기준으로 하루 이동한다.
  */
  limestoneReceiptState
    .selectedDay =
    endDate;


  updateLimestonePeriodDisplay();


  closeLimestoneImportPanel();


  await loadLimestoneReceipts();


  closeLimestonePeriodSearchPanel();
}

